import React, { useContext, useState } from 'react'
import { View, Text, TouchableOpacity, FlatList, Dimensions } from 'react-native'
import { useNavigation } from '@react-navigation/native';
import EmrResponseComponentContext from '../../Handlers/emrResponseComponentContext';
import { normalize } from '../../CommonStyle/componentStyle';
import Icons from '../../Common/Icons';
import { isBNUL, isNU, isNUQ } from '../../CommonStyle/ComponentFunctions';
import { Global } from '../../Common/Global';
import ABlink from '../../Alerts/ABlink';
import HOCIcons from '../../HOC/HOCIcons';
import { APIURL } from '../../Common/apiConstants';
import STemplateContext from '../../Handlers/sTemplateContext';
import { manageContext } from '../../Handlers/manageContext';

export default function CVitalSignSavedData(props) {
  

    const navigation = useNavigation();
    const { responseJSON, setResponseJSON } = useContext(EmrResponseComponentContext);
      console.log("CVitalSignSavedData props....", JSON.stringify(responseJSON));
    console.log("responseJSON....", JSON.stringify(responseJSON));
    const stemplate = props.stemplate ?? false;
    const { contextdata, setContextData } = manageContext(stemplate);
    const data = contextdata.consultation?.[props.natureindex]?.NewData;
    
    console.log("eeeeeee",props.natureindex,props.stemplate);
    console.log("data....", JSON.stringify(contextdata));
    // const data =  responseJSON.consultation?.[props.natureindex]?.NewData;


    function getEditVitalSign() {

        const testdata =   {
            ...contextdata,
            "consultationEdit": data,
            'natureindex': props.natureindex
        };

        setContextData(testdata);

        // console.log("testdata....",JSON.stringify(testdata));


        //     setResponseJSON({
        //         ...responseJSON,
        //         "consultationEdit": data,
        //         'natureindex': props.natureindex
        //     })


        navigation.navigate('ConsultationEdit',
            {
                data: props.data,
                parent: data,
                stemplate: stemplate
            })

    }

    function navigateToVitalSignReport(Subitem) {

        // setIsLoading(true);
        // Global.consultationapi = blockData.item.detailapi;
        // Global.PatientDetails = blockData.item;
        navigation.navigate('PdfPreview', {
            'headerblockstyle': { marginBottom: normalize(35) },
            // 'link': `${APIURL}jremr/jrcommonreport/rnhopapatientvitalsign(${Global.PatientDetails.hopapatient},${Global.PatientDetails.homrpatientchart},NULL,NULL,NULL,1)/0/VitalSignDetail`
            'link': `${APIURL}jremr/jrcommonreport/rnhopapatientvitalsign(${Global.PatientDetails.hopapatient},${Global.PatientDetails.homrpatientchart},NULL,NULL,${Subitem.datavalue},3)/0/VitalSignSummarytemp`
        })
    }

    return (
        isBNUL(data) ?
            <TouchableOpacity onPress={() => getEditVitalSign()} style={{
                borderWidth: 1, borderColor: 'lightgrey', padding: normalize(5), margin: normalize(5), paddingTop: normalize(6),
                backgroundColor: stemplate ? '#ffffff00' :'white'   //'white' //'rgba(237, 232, 232,0.3)' 
            }}>
                <FlatList
                scrollEnabled={false}
                    data={data}
                    renderItem={renderItem}
                    numColumns={2}
                    keyExtractor={(item, index) => 'key' + index}
                    listKey={(item, index) => 'key' + index}
                />
            </TouchableOpacity>
            : null
    )

    function renderItem({ item }) {

        console.log("item....", JSON.stringify(item));
        return (
            <View style={{ width: Dimensions.get('screen').width * 0.48, borderWidth: 0 }}>

                {item.display != undefined && item.display != "" ?
                    <View style={{ flexDirection: 'row', alignItems: 'center', backgroundColor: 'rgba(255, 255, 255,0.5)', borderBottomWidth: 1, borderColor: 'lightgrey', marginVertical: normalize(6) }}>
                        <Icons.FontAwesome5 name="dot-circle" color="darkblue" size={normalize(12)} />
                        <Text style={{ fontSize: normalize(14), fontWeight: 'normal', paddingLeft: normalize(10), }}>{(item.display).toUpperCase()}</Text>
                    </View>
                     : null}
                <View>
                    {item.editArray != undefined ? item.editArray.map((Subitem, k) => {
                        return (
                            <View key={k}>
                                <View
                                    style={{
                                        justifyContent: 'center',
                                        backgroundColor: 'transparent',
                                        width: '100%',
                                        borderWidth: isBNUL(Subitem.vitalsignstatus) ? 1 : 0,
                                        borderRadius: 10,
                                        borderColor: 'lightgrey',
                                    }}>
                                    {Subitem.displaytext != undefined && Subitem.displaytext != "" ?
                                        <View style={{ flexDirection: 'row', paddingLeft: normalize(5), borderWidth: 0, width: '100%', borderWidth: 0, marginVertical: normalize(5) }}>
                                            {Subitem.question ?
                                                <Icons.AntDesign
                                                    name={"checkcircle"}
                                                    color={Subitem.questionValue ? "darkblue" : "grey"} size={normalize(12)}
                                                    style={{ paddingRight: normalize(3) }}
                                                />
                                                :
                                                <Icons.Entypo
                                                    name="dot-single"
                                                    color="darkblue"
                                                    size={normalize(20)}
                                                />
                                            }
                                            <View style={{ flexDirection: 'row' }}>
                                                <Text style={{ fontSize: normalize(12), width: normalize(85) }}>
                                                    {Subitem.displaytext.toUpperCase()}
                                                    {'  '}
                                                </Text>

                                                <Text style={{ fontWeight: 'bold', fontSize: normalize(12), color: 'black' }}>
                                                    {Subitem.value}
                                                </Text>

                                                {Subitem.unit != undefined && Subitem.unit != "" && Subitem.value != undefined && Subitem.value != "" ?
                                                    <Text style={{ fontWeight: '300', fontSize: normalize(13), fontStyle: 'italic', color: 'black' }}>

                                                        {Subitem.unit}
                                                    </Text>
                                                    : null}
                                            </View>
                                        </View>
                                        : null}
                                    {isBNUL(Subitem.vitalsignstatus) ?
                                        <TouchableOpacity

                                            onPress={() => {
                                                navigateToVitalSignReport(Subitem)
                                            }}>
                                            {/* <ABlink duration={1000}> */}
                                            <View style={{ flexDirection: 'row', alignItems: 'center' }}>
                                                <HOCIcons.MaterialCommunityIcons
                                                    name={'clipboard-pulse'}
                                                    size={normalize(20)}
                                                    color={isNUQ(Subitem.vitalsignstatus[0].color) ? Subitem.vitalsignstatus[0].color : Global.AppTheme.primary_color}
                                                    style={{
                                                        marginHorizontal: normalize(5)
                                                    }}
                                                />
                                                <Text style={{
                                                    textAlign: 'left',
                                                    fontSize: normalize(10),
                                                    color: isNUQ(Subitem.vitalsignstatus[0].color) ? Subitem.vitalsignstatus[0].color : Global.AppTheme.primary_color,
                                                    fontWeight: 'bold'
                                                }}>
                                                    {Subitem.vitalsignstatus[0].hopapatientobservationnature ? Subitem.vitalsignstatus[0].hopapatientobservationnature : null}
                                                </Text>
                                            </View>
                                            {/* </ABlink> */}
                                        </TouchableOpacity>
                                        : null}
                                </View>
                                {Subitem.remarksStatus && Subitem.remarks != undefined && Subitem.remarks != "" ?
                                    <View style={{ borderRadius: 10, padding: normalize(5), backgroundColor: 'rgba(255,255,255,0.5)', marginLeft: normalize(12), flexDirection: 'column', marginVertical: normalize(5), borderWidth: 0.5, borderColor: 'lightgrey', }}>
                                        {/* <View style={{borderWidth:0,height:normalize(20)}}>
                                            <Text style={{color:'darkblue'}}>Remark :</Text>
                                            </View> */}
                                        <Text style={{ fontSize: normalize(11), fontStyle: 'italic', color: 'black' }}>{Subitem.remarks}</Text>
                                    </View>
                                    : null}
                            </View>
                        )
                    }) : null}
                </View>
            </View>

        )
    }
}