import React, { useState } from 'react';
import {
  Dimensions,
  Text,
  View,
  Platform,
  ScrollView,
} from 'react-native';
import MaterialCommunityIcons from 'react-native-vector-icons/MaterialCommunityIcons';
import ReactNativeBlobUtil from 'react-native-blob-util';
import WebSignaturePad from '../Custom/WebSignaturePad';
import BloodDonationConsent from '../Registration/BloodDonationConsent';
import DocumentPicker from 'react-native-document-picker';
import { normalize } from '../CommonStyle/componentStyle';
import { isPermitted, notifyMessage } from '../CommonStyle/ComponentFunctions';
import { Global } from '../Common/Global';

// Conditional import for RNSketchCanvas
let RNSketchCanvas;
if (Platform.OS !== 'web') {
  try {
    RNSketchCanvas = require('@terrylinla/react-native-sketch-canvas').default;
  } catch (e) {
    console.error('RNSketchCanvas import failed:', e);
  }
}

export default function CSignature(props) {
  const [consentAccepted, setConsentAccepted] = useState(false);
  const [signatureAreaHeight, setSignatureAreaHeight] = useState(null);
  const [scrollEnabled, setScrollEnabled] = useState(true);
  const currentLanguage = props.language || 'en';

  function fnIcon(text, icon, color) {
    return (
      <View
        style={{
          width: Dimensions.get('window').width * 0.22,
          backgroundColor: Global.AppTheme.primary_color,
          marginHorizontal: normalize(6),
          marginVertical: normalize(5),
          flexDirection: 'row',
          alignItems: 'center',
          borderWidth: 1,
          borderRadius: 10,
          paddingHorizontal: normalize(5),
          justifyContent: 'center',
        }}>
        <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'center' }}>
          <MaterialCommunityIcons name={icon} size={normalize(22)} color={color} />
          <Text
            adjustsFontSizeToFit
            style={{
              marginHorizontal: normalize(5),
              color: '#ffffff',
              fontSize: normalize(10),
              fontWeight: 'bold',
              textAlign: 'center',
            }}>
            {text}
          </Text>
        </View>
      </View>
    );
  }

  const getResolvedPath = async (uri, filen) => {
    let cleanUri = uri;
    if (cleanUri.startsWith('file://')) {
      cleanUri = cleanUri.replace('file://', '');
    }
    const fileBase64 = await ReactNativeBlobUtil.fs.readFile(cleanUri, 'base64');
    const relativePath = ReactNativeBlobUtil.fs.dirs.CacheDir;
    const fileName = `${filen}`;
    const path = `${relativePath}/${fileName}`;
    await ReactNativeBlobUtil.fs.writeFile(path, fileBase64, 'base64');
    return { relativePath, fileName, path };
  };

  const fnUploadImage = async () => {
    try {
      if (Platform.OS === 'web') {
        notifyMessage('Image upload not supported on web yet', 2);
        return;
      }
      const fileDetails = await DocumentPicker.pick({ type: [DocumentPicker.types.images] });
      const { relativePath, fileName, path } = await getResolvedPath(fileDetails[0].uri, fileDetails[0].name);
      let dataset = { fileid: 1, uri: 'file://' + path, filename: fileDetails[0].name + Date(), uritype: false };
      fnEditor(dataset, path);
    } catch (error) {
      if (!DocumentPicker.isCancel(error)) {
        notifyMessage('Unknown Error', 2);
      }
    }
  };

  const SaveDrawing = async (success, pathfile) => {
    if (!success) {
      notifyMessage('Failed to capture signature', 2);
      return;
    }
    if (!pathfile) {
      notifyMessage('Signature path is missing', 2);
      return;
    }

    try {
      var pathname = pathfile;
      var NewPathName = pathname.slice(-12);
      const { relativePath, fileName, path } = await getResolvedPath(pathfile, NewPathName);
      let dataset = {
        fileid: 1,
        uri: 'file://' + path,
        filename: NewPathName + Date(),
        uritype: false,
      };
      fnEditor(dataset, path);
    } catch (error) {
      console.log('SaveDrawing error:', error);
      notifyMessage('Error saving signature', 2);
    }
  };

  const handleWebSave = (dataUrl) => {
    // dataUrl is "data:image/png;base64,..."
    // props.onsave expects an object with uri
    let dataset = {
      fileid: 1,
      uri: dataUrl, // Pass key data URI directly for web
      filename: 'signature_' + Date.now() + '.png',
      uritype: true // Using encoded data
    };
    fnEditor(dataset, null);
  };

  function fnEditor(dataset, path) {
    if (props.onsave) {
      props.onsave(dataset);
    }
  }

  const handleConsentAccept = (accepted) => {
    setConsentAccepted(accepted);
    if (props.onConsentChange) {
      props.onConsentChange(accepted);
    }
  };

  const screenHeight = Dimensions.get('window').height;
  const defaultHeight = Math.max(250, Math.floor(screenHeight * 0.35));
  const maxHeight = Math.min(400, Math.floor(screenHeight * 0.5));

  const containerHeightStyle = {
    minHeight: 250,
    height: signatureAreaHeight || defaultHeight,
    maxHeight: maxHeight,
  };

  return (
    <ScrollView
      contentContainerStyle={{ flexGrow: 1, paddingBottom: 20 }}
      showsVerticalScrollIndicator={false}
      scrollEnabled={scrollEnabled}
    >
      <BloodDonationConsent
        onAccept={handleConsentAccept}
        showCheckbox={false}
        compact={false}
        language={currentLanguage}
      />

      <View
        style={containerHeightStyle}
        onLayout={(event) => {
          const h = event?.nativeEvent?.layout?.height;
          if (h && h > 0) {
            setSignatureAreaHeight(h);
          } else {
            setSignatureAreaHeight(defaultHeight);
          }
        }}
      >
        {Platform.OS === 'web' ? (
          <WebSignaturePad
            onSave={handleWebSave}
            onClear={() => { }}
            onStrokeStart={() => setScrollEnabled(false)}
            onStrokeEnd={() => setScrollEnabled(true)}
            style={{
              backgroundColor: '#ffffff71',
              flex: 1,
              borderWidth: 1,
              borderColor: '#a5a5a5',
              borderRadius: 10,
              marginHorizontal: normalize(5),
              marginVertical: normalize(5),
            }}
          />
        ) : (
          RNSketchCanvas && (
            <RNSketchCanvas
              containerStyle={{
                backgroundColor: '#ffffff71',
                flex: 1,
                borderWidth: 1,
                borderColor: '#a5a5a5',
                borderRadius: 10,
                marginHorizontal: normalize(5),
                marginVertical: normalize(5),
              }}
              canvasStyle={{ backgroundColor: '#ffffff00', flex: 1 }}
              defaultStrokeIndex={0}
              defaultStrokeWidth={3}

              onStrokeStart={() => setScrollEnabled(false)}
              onStrokeEnd={() => setScrollEnabled(true)}

              closeComponent={fnIcon('Image', 'image', 'white')}
              clearComponent={fnIcon('Clear all', 'eraser', 'white')}
              saveComponent={fnIcon('Save', 'content-save', 'white')}
              onClosePressed={() => {
                fnUploadImage();
              }}
              savePreference={() => {
                return {
                  folder: ReactNativeBlobUtil.fs.dirs.CacheDir,
                  filename: String(Math.ceil(Math.random() * 100000000)),
                  transparent: false,
                  imageType: 'png',
                };
              }}
              onSketchSaved={(success, pathfile) => {
                SaveDrawing(success, pathfile);
              }}
              onPathsChange={(pathsCount) => { }}
            />
          )
        )}
      </View>
    </ScrollView>
  );
}
