const DonationControls = memo(({
  donorId,
  donationInProgress,
  onStartDonation,
  onEndDonation,
  formatTime,
  backendDonationStart,   // expected: ISO string or backend string (we parse robustly)
  onStartConfirmation,
  onStopConfirmation
}) => {
  const [currentTimer, setCurrentTimer] = useState(0);
  const startBlinkAnim = useRef(new Animated.Value(1)).current;
  const deferBlinkAnim = useRef(new Animated.Value(1)).current;
  const acceptBlinkAnim = useRef(new Animated.Value(1)).current;
  const DONATION_STATUS = 'DONATING';

  // robust parser: accepts ISO or non-ISO backend string (falls back to moment)
  const calculateElapsedSeconds = (startTime) => {
    if (!startTime) return 0;
    // Try Date parse first (works for ISO)
    const t = new Date(startTime).getTime();
    if (!isNaN(t)) return Math.floor((Date.now() - t) / 1000);
    // fallback to moment parsing (handles 'YYYY-MM-DD HH:mm:ss' etc)
    const m = moment(startTime);
    if (m.isValid()) return Math.floor((Date.now() - m.valueOf()) / 1000);
    return 0;
  };

  // Timer effect: use the passed backendDonationStart value (not an undefined timerData)
  useEffect(() => {
    let timerInterval;
    if (donationInProgress && backendDonationStart) {
      const updateTimer = () => {
        const elapsed = calculateElapsedSeconds(backendDonationStart);
        setCurrentTimer(elapsed);
      };


      updateTimer();
      timerInterval = setInterval(updateTimer, 1000);
    } else {
      setCurrentTimer(0);
    }

    return () => {
      if (timerInterval) clearInterval(timerInterval);
    };
  }, [donationInProgress, backendDonationStart]);

  // Blinking animations (unchanged logic, kept tidy)
  useEffect(() => {
    if (!donationInProgress) {
      const blinkStart = Animated.loop(
        Animated.sequence([
          Animated.timing(startBlinkAnim, { toValue: 0.4, duration: 800, useNativeDriver: true }),
          Animated.timing(startBlinkAnim, { toValue: 1, duration: 800, useNativeDriver: true })
        ])
      );
      blinkStart.start();

      deferBlinkAnim.setValue(1);
      acceptBlinkAnim.setValue(1);

      return () => blinkStart.stop();
    } else {
      const blinkDefer = Animated.loop(
        Animated.sequence([
          Animated.timing(deferBlinkAnim, { toValue: 0.5, duration: 700, useNativeDriver: true }),
          Animated.timing(deferBlinkAnim, { toValue: 1, duration: 700, useNativeDriver: true })
        ])
      );

      const blinkAccept = Animated.loop(
        Animated.sequence([
          Animated.timing(acceptBlinkAnim, { toValue: 0.5, duration: 700, useNativeDriver: true }),
          Animated.timing(acceptBlinkAnim, { toValue: 1, duration: 700, useNativeDriver: true })
        ])
      );

      blinkDefer.start();
      blinkAccept.start();
      startBlinkAnim.setValue(1);

      return () => {
        blinkDefer.stop();
        blinkAccept.stop();
      };
    }
  }, [donationInProgress]);

  // When donating — show defer/accept + timer
  if (donationInProgress) {
    return (
      <View style={donationStyles.minimalControlsContainer}>
        {/* DEFER Button - Minimal circular */}
        <TouchableOpacity
          style={donationStyles.minimalDeferButton}
          onPress={() => onStopConfirmation(donorId, 'DEFER')}
          activeOpacity={0.7}
        >
          <Animated.View style={{ opacity: deferBlinkAnim, alignItems: 'center', justifyContent: 'center' }}>
            <Text style={[donationStyles.buttonLabel, { color: '#c70f0fff' }]}>DEFER</Text>
            <Icons.MaterialCommunityIcons
              name="close-circle"
              size={normalize(22)}
              color="#c70f0fff"
            />
          </Animated.View>
        </TouchableOpacity>

        {/* Timer Display - Compact */}
        <View style={donationStyles.minimalTimerContainer}>
          <Text style={donationStyles.minimalTimerText}>
            {formatTime(currentTimer)}
          </Text>
        </View>

        {/* ACCEPT Button - Minimal circular */}
        <TouchableOpacity
          style={donationStyles.minimalAcceptButton}
          onPress={() => onStopConfirmation(donorId, 'ACCEPT')}
          activeOpacity={0.7}
        >
          <Animated.View style={{ opacity: acceptBlinkAnim, alignItems: 'center', justifyContent: 'center' }}>
            <Text style={[donationStyles.buttonLabel, { color: '#38be1dff' }]}>ACCEPT</Text>
            <Icons.MaterialCommunityIcons
              name="check-circle"
              size={normalize(22)}
              color="#38be1dff"
            />
          </Animated.View>
        </TouchableOpacity>
      </View>
    );
  }

  // When not donating — show START button
  return (
    <TouchableOpacity
      style={donationStyles.minimalStartButton}
      onPress={() => onStartConfirmation(donorId)}
      activeOpacity={0.7}
    >
      <Animated.View style={[donationStyles.startIconContainer, { opacity: startBlinkAnim }]}>
        <Icons.MaterialCommunityIcons
          name="iv-bag"
          size={normalize(23)}
          color="#ffffff"
        />
      </Animated.View>
    </TouchableOpacity>
  );
});


// save timer data locally
const persistTimer = async (donorId, startISO, status = 'DONATING') => {
  try {
    await AsyncStorage.setItem(
      `donationTimer_${donorId}`,
      JSON.stringify({ startTime: startISO, status })
    );
  } catch (e) {
    console.warn('persistTimer error', e);
  }
};

const removePersistedTimer = async (donorId) => {
  try {
    await AsyncStorage.removeItem(`donationTimer_${donorId}`);
  } catch (e) {
    console.warn('removePersistedTimer error', e);
  }
};

const restorePersistedTimer = async (donorId) => {
  try {
    const raw = await AsyncStorage.getItem(`donationTimer_${donorId}`);
    if (!raw) return null;
    return JSON.parse(raw);
  } catch (e) {
    console.warn('restorePersistedTimer error', e);
    return null;
  }
};



