import React, { useState, useContext, useRef, useEffect } from 'react'
import { View, Text, TouchableOpacity, FlatList, Dimensions, ActivityIndicator, StyleSheet } from 'react-native'
import Icons from '../../Common/Icons'
import { normalize } from '../../CommonStyle/componentStyle'
import EmrResponseComponentContext from '../../Handlers/emrResponseComponentContext'
import STextInput from '../../StaticComponents/STextInput'
