import React, { createContext, useState } from 'react';

export const QuestionBuilderContext = createContext();

export const QuestionBuilderProvider = ({ children }) => {
  const [questions, setQuestions] = useState([
    { code: 1, questionname: 'Are you feeling well?', order: 1, flag: 0 },
    { code: 2, questionname: 'Do you have pain?', order: 2, flag: 0 },
    { code: 3, questionname: 'Have you donated blood in the last 3 months?', order: 3, flag: 0 }
  ]);

  const [answerTags, setAnswerTags] = useState([
    { code: 1, answertag: 'General Symptoms', answers: ['Yes', 'No', 'Sometimes'], flag: 0 },
    { code: 2, answertag: 'Yes/No', answers: ['Yes', 'No'], flag: 0 }
  ]);

  const [mappings, setMappings] = useState([
    { questionCode: 3, answerCodes: [2], allocation: 'DonorScreening', flag: 0 }
  ]);

  // NEW: forms - each form has a name and nature ('S'|'R'|'D')
  const [forms, setForms] = useState([
    // seed example so mapping has something by default
    { id: 'f_donor_screen', formname: 'Donor Screening', nature: 'S' },
    { id: 'f_donor_reg', formname: 'Donor Registration', nature: 'R' },
  ]);

  // derive allocationScreens as an array of objects: {label, nature}
  const allocationScreens = forms.map(f => ({ label: f.formname, nature: f.nature, id: f.id }));

  return (
    <QuestionBuilderContext.Provider
      value={{
        questions, setQuestions,
        answerTags, setAnswerTags,
        mappings, setMappings,
        forms, setForms,
        allocationScreens,
      }}
    >
      {children}
    </QuestionBuilderContext.Provider>
  );
};
