import React, { useState, memo, useEffect } from 'react';
import { View, Dimensions, Text, TouchableOpacity, StyleSheet, TextInput, Platform, Modal, Image, Animated } from 'react-native';
// import Overlay from "react-native-modal-overlay"; // Not available for web
import { Global } from '../Common/Global';
import Icons from '../Common/Icons';
import { ValueCheck } from '../CommonStyle/ComponentFunctions';
import { normalize } from '../CommonStyle/componentStyle';
// import FastImage from 'react-native-fast-image'; // Not available for web

export default function AAlert(props) {
  const [overlay, setOverlay] = useState(true)
  const [fadeAnim] = useState(new Animated.Value(0));
  const [data] = useState({
    ...props.data,
    "bgcolor": getBgColor(props.data.datavalue),
    "durartion": getDurarion(props.data.datavalue)
  });

  useEffect(() => {
    // Fade in animation
    Animated.timing(fadeAnim, {
      toValue: 1,
      duration: 300,
      useNativeDriver: true,
    }).start();

    setTimeout(() => {
      props.close(false)
      setOverlay(false)
    }, data.durartion)
  }, []);

  function getBgColor(key) {
    switch (key) {
      case 1: return "#0ca004"
      case 2: return "#f44e4e"
      case 3: return "#bfbf18"
      case 4: return "#d88304"
      default: return Global.AppTheme.primary_color
    }
  }

  function getTransparentColor(key) {
    switch (key) {
      case 1: return "rgba(0, 90, 0, 0.2)"
      case 2: return "rgba(90, 0, 0, 0.2)"
      case 3: return "rgba(249, 242, 172, 0.2)"
      case 4: return "rgba(249, 212, 167, 0.2)"
      default: return "rgba(0, 0, 0, 0.2)"
    }
  }

  function getDurarion(key) {
    switch (key) {
      case 1: return 2000
      case 2: return 2000
      case 3: return 2000
      case 4: return 2000
      default: return 2000
    }
  }

  function getPopupContainerStyleIOS() {
    return {
      ...styles.overlaystyle,
      backgroundColor: ValueCheck(data.bgcolor) ? data.bgcolor : '#fff',
      bottom: normalize(100),
    };
  }

  function getClose() {
    setOverlay(false)
    props.close != undefined ? props.close(false) : null
  }

  if (!overlay) return null;

  return (
    <Modal
      visible={overlay}
      transparent={true}
      animationType="fade"
      onRequestClose={getClose}
    >
      <View style={[styles.modalOverlay, { backgroundColor: getTransparentColor(data.datavalue) }]}>
        <Animated.View style={[getPopupContainerStyleIOS(), { opacity: fadeAnim }]}>
          <TouchableOpacity
            style={{ position: 'absolute', right: normalize(15), zIndex: 1, top: normalize(5) }}
            onPress={getClose}>
            <Icons.AntDesign name={"closecircleo"} size={normalize(15)} color={"#fff"} />
          </TouchableOpacity>
          <View style={{ flexDirection: 'row', width: '100%', borderWidth: 0 }}>
            <View style={{ flexDirection: 'row', alignItems: 'center', borderWidth: 0, justifyContent: 'center' }}>
              <View
                style={{
                  borderWidth: 0,
                  height: normalize(30),
                  width: normalize(30),
                  borderRadius: normalize(50),
                  backgroundColor: '#fff',
                  justifyContent: 'center',
                  alignItems: 'center',
                }}
              >
                <Icons.FontAwesome5 name="info-circle" size={normalize(20)} color={Global.AppTheme.primary_color} />
              </View>
              <Icons.Entypo
                color={"#fff"}
                name={'info'}
                size={normalize(15)}
                style={{
                  borderWidth: 0
                }}
              />
            </View>

            <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'center', flex: 1 }}>
              <Text
                adjustsFontSizeToFit
                style={{
                  color: "#fff",
                  fontWeight: 'bold',
                  fontSize: normalize(16),
                  paddingLeft: normalize(7),
                }}>
                {ValueCheck(data.displaytext) ? data.displaytext : ''}
              </Text>
            </View>
          </View>
        </Animated.View>
      </View>
    </Modal>
  );
}


const styles = StyleSheet.create({
  modalOverlay: {
    flex: 1,
    justifyContent: 'flex-end',
    alignItems: 'center',
  },
  overlaystyle: {
    position: 'absolute',
    width: Dimensions.get('window').width,
    borderRadius: normalize(30),
    borderWidth: 2,
    borderColor: '#e0e0e0',
    padding: normalize(15),
    marginBottom: normalize(50),
  },
});
