


import React, { useState, useEffect } from 'react';
import { APIURL } from '../Common/apiConstants';
import { Global } from '../Common/Global';
import { isBNU } from '../CommonStyle/ComponentFunctions';

export default function HReportHeader(props) {
    const hasPatientOrSpecimen = (props && (props.patientid || props.specimenid));


    return (`
        <div style="width: 100%;">
            <div style="position: relative; width: 100%; height: 100px;">
                <img style="height: 100px; width: 100%; position: absolute; top: 0; left: 0;" src=${Global.headerfooter[0]} />
                <div style="position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); text-align: center; width: 100%; z-index: 10;">
                    ${isBNU(props) && isBNU(props.hospitalname) ? `<div style="font-size: 18px; font-weight: bold; color: #094498; margin-bottom: 4px;">${props.hospitalname}</div>` : ''}
                    ${isBNU(props) && isBNU(props.departmentname) ? `<div style="font-size: 15px; font-weight: bold; color: #094498; margin-bottom: 2px;">${props.departmentname}${' REPORT'}</div>` : ''}
                    ${isBNU(props) && isBNU(props.reportperiod) ? `<div style="font-size: 11px; color: #555;">${props.reportperiod}</div>` : ''}
                </div>
            </div>
            ${hasPatientOrSpecimen ? `
                <table style="width:100%;">
                    <tr>
                        <td style="width:40%;text-align:center;border: 0px solid black;">
                        <div id="patientidbarcode" style="border: 0px solid black;font-family: 'Libre Barcode 39';font-size:40px;height:25px;">
                        ${isBNU(props) && isBNU(props.patientid) ? props.patientid : ''}
                        </div>
                        ${isBNU(props) && isBNU(props.patientid) ? `<b style="font-size:20px;"><b style="font-size:8px;">PATIENT ID :&nbsp;&nbsp;&nbsp;&nbsp;</b> ${props.patientid}</b>` : ''}
                        </td>
                        <td style="30%;text-align:center;">
                        &nbsp;
                        </td>
                        <td style="30%;text-align:center;">
                        <div id="patientidbarcode" style="border: 0px solid black;font-family: 'Libre Barcode 39';font-size:40px;height:25px;">
                        ${isBNU(props) && isBNU(props.specimenid) ? `${APIURL}${props.specimenid}` : ''}
                        </div>
                        ${isBNU(props) && isBNU(props.specimenid) ? `<b style="font-size:20px;"><b style="font-size:8px;">SPECIMEN ID :&nbsp;&nbsp;&nbsp;&nbsp;</b>${props.specimenid}</b>` : ''}
                        </td>
                    </tr>
                </table>
            ` : ''}
        </div>
    `)
}
