const buildApiEndpoint = (nature) => {
  return `${API_CONFIG.baseURL}${API_CONFIG.endpoints.mappingsBase} ${nature},0`;
};




const calculateQuestionScore = (questionData, userAnswer) => {
  if (!questionData || userAnswer === undefined || userAnswer === null) return null;

  // Use nullish coalescing so 0 is honoured
  const weight = Number(questionData.weight ?? 1);
  const penalty = Number(questionData.penalty ?? 1);

  // Accept safe/unsafe as array or comma-separated string
  const toArray = (v) => {
    if (Array.isArray(v)) return v;
    if (typeof v === 'string') return v.split(',').map(x => x.trim()).filter(Boolean);
    return [];
  };

  const safeAnswers = toArray(questionData.safeanswer);
  const unsafeAnswers = toArray(questionData.unsafeanswer);

  // Normalize candidate strings for comparison
  const normalize = (s) => String(s ?? '').toLowerCase().replace(/\s+/g, '').trim();

  // Derive a user-facing answer text for comparison
  // Find the answer text from the dynamic list if possible
  const answerObj = questionData.tag?.answers?.find(a => a.id === userAnswer);
  const answerText = answerObj?.text || (userAnswer === 'answer_yes' ? 'Yes'
    : userAnswer === 'answer_no' ? 'No'
      : userAnswer);

  const normalizedUser = normalize(answerText);

  // Also create a normalized list for safe/unsafe
  const normalizedSafe = safeAnswers.map(a => normalize(a));
  const normalizedUnsafe = unsafeAnswers.map(a => normalize(a));

  // In some systems safe/unsafe may be provided as ids like 'answer_yes' - include those too
  const possibleUserIds = new Set([
    normalizedUser,
    normalize(userAnswer),         // if userAnswer already an id like 'answer_yes'
  ]);

  // Category resolution: SAFE > UNSAFE > NEUTRAL
  let category = 'NEUTRAL';

  // Check SAFE (if any safe item matches either normalized text or id)
  for (const s of normalizedSafe) {
    if (possibleUserIds.has(s)) { category = 'SAFE'; break; }
  }

  // Check UNSAFE only if not SAFE
  if (category === 'NEUTRAL') {
    for (const u of normalizedUnsafe) {
      if (possibleUserIds.has(u)) { category = 'UNSAFE'; break; }
    }
  }

  // Compute score (coerced numbers)
  let score = 0;
  if (category === 'SAFE') score = weight;
  else if (category === 'UNSAFE') score = -(weight * penalty);
  else score = 0;

  return {
    questionCode: questionData.questioncode ?? questionData.code,
    questionText: questionData.questioneng ?? questionData.question ?? '',
    userAnswer: answerText,
    weight,
    penalty,
    score,
    category,
    maxPossibleScore: weight,
    minPossibleScore: -(weight * penalty)
  };
};


const QuestionnaireView = forwardRef(({
  onAnswersChange,
  style,
  nature,
  onQAComplete,
  onLoadStateChange,
  initialAnswers = {},
  getText,
  gender,
  onCaptureMedia = () => { }, // NEW: Prop to handle media capture clicks
}, ref) => {
  const { currentLanguage, isEnglish } = useLanguage();

  // State management
  const [questions, setQuestions] = useState([]);
  const [groupedQuestions, setGroupedQuestions] = useState({});
  const [selectedAnswers, setSelectedAnswers] = useState({});
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [rawApiData, setRawApiData] = useState([]);
  const [isInitialized, setIsInitialized] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [questionsPerPage] = useState(9); // Keep 8 as max per page
  const [currentGroupInfo, setCurrentGroupInfo] = useState(null);
  const [paginatedGroups, setPaginatedGroups] = useState([]);
  const [recordedVideos, setRecordedVideos] = useState({});
  const [capturedImages, setCapturedImages] = useState({});
  const [recordedAudios, setRecordedAudios] = useState({});

  // --- NEW: State to track active media clicks for visual feedback ---
  const [activeMedia, setActiveMedia] = useState({});

  // Define standard Yes/No answers (as a fallback)
  const YES_NO_ANSWERS = useMemo(() => [
    { id: 'answer_yes', text: isEnglish ? 'Yes' : 'അതെ', engText: 'Yes', malText: 'അതെ' },
    { id: 'answer_no', text: isEnglish ? 'No' : 'ഇല്ല', engText: 'No', malText: 'ഇല്ല' }
  ], [isEnglish]);

  // Get nature code for the current allocation
  const natureCode = useMemo(() => {
    return nature;
  }, [nature]);

  // Helper function to parse comma-separated answer strings
  const parseAnswerString = useCallback((answerStr) => {
    if (Array.isArray(answerStr)) return answerStr;
    if (typeof answerStr === 'string') return answerStr.split(',').map((x) => x.trim()).filter(Boolean);
    return [];
  }, []);

  // Replace the organizeQuestionsByGroup function in QuestionareView.js with this corrected version

  const organizeQuestionsByGroup = useCallback((questionsArray) => {
    const grouped = {};
    const groupMeta = new Map();

    console.log('🔍 DEBUG: All questions received by organizeQuestionsByGroup:', questionsArray);

    questionsArray.forEach((question) => {

      const rawGroupCode = question.groupCode; // Use camelCase 'groupCode'
      const groupKey = rawGroupCode !== null && rawGroupCode !== undefined
        ? String(rawGroupCode)
        : 'general';

      let groupName;
      if (rawGroupCode !== null && rawGroupCode !== undefined) {
        if (isEnglish) {
          groupName = question.groupeng || `Group ${rawGroupCode}`;
        } else {
          groupName = question.groupmal || `ഗ്രൂപ്പ് ${rawGroupCode}`;
        }
      } else {
        groupName = isEnglish ? 'General Questions' : 'പൊതു ചോദ്യങ്ങൾ';
      }

      const groupSort = question.groupSort || (rawGroupCode !== null && rawGroupCode !== undefined ? rawGroupCode : 999);

      if (!grouped[groupKey]) {
        grouped[groupKey] = [];

        // --- UPDATED: Set Group Metadata with Bulk Actions ---
        groupMeta.set(groupKey, {
          name: groupName,
          groupSort: Number(groupSort),
          groupCode: groupKey,
          // Extract the bulk actions from the question and store in group meta
          primaryAction: question.bulkPrimary,
          secondaryAction: question.bulkSecondary
        });
      }

      grouped[groupKey].push({
        ...question,
        groupKey,
        groupName,
      });
    });

    console.log('🔍 DEBUG: Final grouped data:', grouped);
    console.log('🔍 DEBUG: Group metadata:', Array.from(groupMeta.entries()));

    Object.keys(grouped).forEach((groupKey) => {
      grouped[groupKey].sort((a, b) => (a.sort || 0) - (b.sort || 0));
    });

    const orderedGroupKeys = Array.from(groupMeta.entries())
      .sort(([, a], [, b]) => a.groupSort - b.groupSort)
      .map(([key]) => key);

    console.log('🔍 DEBUG: Ordered group keys:', orderedGroupKeys);

    return { grouped, orderedGroupKeys, groupMeta };
  }, [isEnglish]);

  // Enhanced pagination that respects group boundaries
  const createGroupBoundaryAwarePages = useCallback((grouped, orderedGroupKeys, groupMeta, perPage) => {
    console.log('🔍 DEBUG: Creating group-boundary-aware pages with perPage:', perPage);

    const pages = [];
    let currentPageQuestions = [];
    let currentGroupKey = null;
    let absoluteIndex = 0;

    // Process each group in order
    orderedGroupKeys.forEach(groupKey => {
      const groupQuestions = grouped[groupKey];
      const groupInfo = groupMeta.get(groupKey);

      console.log(`🔍 DEBUG: Processing group "${groupInfo.name}" with ${groupQuestions.length} questions`);

      // Process each question in the group
      groupQuestions.forEach((question, questionIndex) => {
        absoluteIndex++;

        const questionWithInfo = {
          ...question,
          absoluteIndex,
          groupKey,
          groupInfo,
          groupName: groupInfo.name
        };

        // If starting a new group and we have questions from previous group, finish the current page
        if (currentGroupKey && currentGroupKey !== groupKey && currentPageQuestions.length > 0) {
          pages.push({
            questions: [...currentPageQuestions],
            group: currentGroupKey,
            groupInfo: groupMeta.get(currentGroupKey),
            pageNumber: pages.length + 1
          });
          currentPageQuestions = [];
        }

        // Set current group
        currentGroupKey = groupKey;

        // Add question to current page
        currentPageQuestions.push(questionWithInfo);

        // Check if we need to create a new page
        const isLastQuestionInGroup = questionIndex === groupQuestions.length - 1;
        const isPageFull = currentPageQuestions.length >= perPage;

        if (isPageFull || isLastQuestionInGroup) {
          pages.push({
            questions: [...currentPageQuestions],
            group: currentGroupKey,
            groupInfo: groupInfo,
            pageNumber: pages.length + 1
          });
          currentPageQuestions = [];
          // Don't reset currentGroupKey here to maintain group context
        }
      });
    });

    // Handle any remaining questions
    if (currentPageQuestions.length > 0) {
      pages.push({
        questions: [...currentPageQuestions],
        group: currentGroupKey,
        groupInfo: groupMeta.get(currentGroupKey),
        pageNumber: pages.length + 1
      });
    }

    console.log('🔍 DEBUG: Created', pages.length, 'pages with group boundaries');
    pages.forEach((pageData, index) => {
      console.log(`🔍 DEBUG: Page ${index + 1}: ${pageData.questions.length} questions from group "${pageData.groupInfo.name}"`);
    });

    return pages;
  }, []);


  const handleVideoCapture = useCallback((questionId, serverFileName) => {
    setRecordedVideos(prev => ({
      ...prev,
      [questionId]: serverFileName
    }));
  }, []);

  const handleImageCapture = useCallback((questionId, serverFileName) => {
    setCapturedImages(prev => ({
      ...prev,
      [questionId]: serverFileName
    }));
  }, []);

  const handleAudioCapture = useCallback((questionId, serverFileName) => {
    setRecordedAudios(prev => ({
      ...prev,
      [questionId]: serverFileName
    }));
  }, []);

  // Helper function to check if a question should be shown based on gender
  const shouldShowQuestion = useCallback((question) => {
    // Use backendCode which maps to API's 'code' field (228, 229)
    const backendCode = parseInt(question.backendCode);
    const normalizedGender = gender ? gender.trim().toLowerCase() : '';

    // Q228 (code=228): Show only for Male
    if (backendCode === 228) {
      return normalizedGender === 'male';
    }

    // Q229 (code=229): Show only for Female
    if (backendCode === 229) {
      return normalizedGender === 'female';
    }

    // All other questions: show by default
    return true;
  }, [gender]);

  // Get current page data
  const getCurrentPageData = useCallback(() => {
    if (paginatedGroups.length === 0 || currentPage > paginatedGroups.length) {
      return {
        items: [],
        totalQuestions: 0,
        totalPages: 0,
        hasMore: false,
        currentGroup: null,
        allAnsweredOnPage: true
      };
    }

    const currentPageData = paginatedGroups[currentPage - 1];

    // Filter questions based on current state (gender, answers, etc.)
    const filteredQuestions = currentPageData.questions.filter(shouldShowQuestion);

    const allAnsweredOnPage = filteredQuestions.every(question =>
      selectedAnswers[question.questionCode]
    );

    return {
      items: filteredQuestions,
      totalQuestions: paginatedGroups.reduce((total, page) => {
        const filtered = page.questions.filter(shouldShowQuestion);
        return total + filtered.length;
      }, 0),
      totalPages: paginatedGroups.length,
      hasMore: currentPage < paginatedGroups.length,
      currentGroup: currentPageData.groupInfo,
      allAnsweredOnPage
    };
  }, [paginatedGroups, currentPage, selectedAnswers, shouldShowQuestion]);

  const paginationData = useMemo(() => getCurrentPageData(), [getCurrentPageData]);

  // Update current group info when pagination changes
  useEffect(() => {
    setCurrentGroupInfo(paginationData.currentGroup);
  }, [paginationData.currentGroup]);

  // Replace the transformApiData function in QuestionareView.js with this fixed version:
  const transformApiData = useCallback((apiData, targetAllocation, targetNature, gender) => {
    const questionMap = new Map();
    console.log('🔍 DEBUG: transformApiData received:', apiData.length, 'items');
    console.log('👤 Current gender for filtering:', gender);

    apiData.forEach((mapping) => {

      // 1. Check for status first. If 'hide', skip it immediately.
      if (mapping.status === 'hide') {
        console.log('🚫 Skipping hidden question:', {
          questioncode: mapping.questioncode,
          status: mapping.status
        });
        return; // Don't process this question
      }

      const matchesNature = !targetNature ||
        String(mapping.suoptiondetail ?? '').toUpperCase() === String(targetNature ?? '').toUpperCase();

      if (!matchesNature) return;

      const {
        code: backendCode,
        questioncode,
        questioneng,
        questionmal,
        answercode,
        heading,
        nature,
        groupcode,
        groupeng,
        groupmal,
        sort,
        groupsort,
        weight,
        penalty,
        safeanswer,
        unsafeanswer,
        answer,
        answermal,
        status,
        // --- NEW: Extract Bulk Actions ---
        primary,
        secondary,
        bulk_primary,
        bulk_secondary,
        video, // NEW: Extract the 'video' flag (or whatever it's called in your JSON)
      } = mapping;

      // Enhanced gender-based filtering
      const isWomenSpecificGroup =
        groupeng?.toLowerCase().includes('physiological status for women');
      const isWomenSpecificQuestion = null;

      const shouldSkipForMale = gender && gender.toLowerCase() === 'male' &&
        (isWomenSpecificGroup || isWomenSpecificQuestion);

      if (shouldSkipForMale) {
        console.log('🚫 Skipping women-specific content for male donor:', {
          group: groupeng,
          questionCode: questioncode,
        });
        return;
      }

      const uniqueKey = `${questioncode}_${groupcode || 'general'}`;

      if (!questionMap.has(uniqueKey)) {
        const questionText = isEnglish
          ? (questioneng || `Question ${questioncode}`)
          : (questionmal || questioneng || `Question ${questioncode}`);

        const answerTextsEng = parseAnswerString(answer);
        const answerTextsMal = parseAnswerString(answermal || answer);

        const dynamicAnswers = answerTextsEng.map((engText, index) => {
          const malText = answerTextsMal[index] || engText;
          const text = isEnglish ? engText : malText;

          const id = `answer_${engText.toLowerCase().replace(/[^a-z0-9]/g, '_')}`;

          return {
            id: id,
            text: text,
            engText: engText,
            malText: malText,
          };
        });

        questionMap.set(uniqueKey, {
          questionCode: questioncode,
          backendCode: backendCode,
          name: questionText,
          nature,
          groupCode: groupcode || null,
          groupcode: groupcode || null,
          groupeng: groupeng || null,
          groupmal: groupmal || null,
          sort: sort || 0,
          groupSort: groupsort || 999,
          groupsort: groupsort || 999,
          isWomenSpecific: isWomenSpecificGroup || isWomenSpecificQuestion,
          tag: {
            id: `tag_${answercode}`,
            name: heading || 'Options',
            answers: dynamicAnswers.length > 0 ? dynamicAnswers : YES_NO_ANSWERS,
          },
          weight: weight || 1,
          penalty: penalty || 1,
          safeanswer: safeanswer || [],
          unsafeanswer: unsafeanswer || [],
          answer: answer,
          apiMapping: mapping,

          // --- NEW: Store Bulk Actions from API ---
          bulkPrimary: primary || bulk_primary || '',
          bulkSecondary: secondary || bulk_secondary || '',

          // --- NEW: Store the media flag ---
          // We check for `true` explicitly.
          allowMedia: video === 'true',
        });
      }
    });

    const result = Array.from(questionMap.values());
    return result;
  }, [currentLanguage, isEnglish, YES_NO_ANSWERS, parseAnswerString]);

  const calculateAllQuestionScores = useCallback(() => {
    if (!questions.length || Object.keys(selectedAnswers).length === 0) {
      return { questionScores: [], totalScore: 0, eligibilityStatus: 'PENDING' };
    }

    const questionScores = [];
    let totalScore = 0;
    let maxPossibleScore = 0;
    let minPossibleScore = 0;

    Object.entries(selectedAnswers).forEach(([questionCodeStr, answerId]) => {
      if (!answerId) return;

      const questionCode = parseInt(questionCodeStr, 10);
      const question = questions.find(q => q.questionCode === questionCode);

      if (question && question.apiMapping) {
        const scoreResult = calculateQuestionScore(
          { ...question.apiMapping, tag: question.tag },
          answerId
        );
        if (scoreResult) {
          questionScores.push(scoreResult);
          totalScore += scoreResult.score;
          maxPossibleScore += scoreResult.maxPossibleScore;
          minPossibleScore += scoreResult.minPossibleScore;
        }
      }
    });

    const unsafeCount = questionScores.filter(qs => qs.category === 'UNSAFE').length;
    let eligibilityStatus = 'ELIGIBLE';

    if (unsafeCount > 0) {
      eligibilityStatus = 'NOT_ELIGIBLE';
    } else {
      const percentage = maxPossibleScore > minPossibleScore
        ? ((totalScore - minPossibleScore) / (maxPossibleScore - minPossibleScore)) * 100
        : 0;

      if (percentage >= 80) {
        eligibilityStatus = 'ELIGIBLE';
      } else if (percentage >= 60) {
        eligibilityStatus = 'REVIEW_REQUIRED';
      } else {
        eligibilityStatus = 'NOT_ELIGIBLE';
      }
    }

    const answerBreakdown = questionScores.reduce(
      (acc, qs) => {
        acc[qs.category.toLowerCase()]++;
        acc.total++;
        return acc;
      },
      { safe: 0, unsafe: 0, neutral: 0, total: 0 }
    );

    return {
      questionScores,
      totalScore: Math.round(totalScore * 100) / 100,
      maxPossibleScore,
      minPossibleScore,
      percentage: maxPossibleScore > minPossibleScore
        ? Math.round(((totalScore - minPossibleScore) / (maxPossibleScore - minPossibleScore)) * 100 * 100) / 100
        : 0,
      eligibilityStatus,
      answerBreakdown,
      timestamp: new Date().toISOString()
    };
  }, [questions, selectedAnswers]);


  const getFormattedAnswersForSubmission = useCallback(() => {
    if (!questions.length || !selectedAnswers) return [];

    // Get only visible questions
    const visibleQuestions = questions.filter(q => shouldShowQuestion(q));

    const toArray = (v) => {
      if (Array.isArray(v)) return v.map(x => (x ?? '').toString().trim()).filter(Boolean);
      if (typeof v === 'string') return v.split(',').map(x => x.trim()).filter(Boolean);
      return [];
    };

    const codes = Object.entries(selectedAnswers)
      .filter(([, answerId]) => answerId !== null && answerId !== undefined)
      .map(([questionCode, answerId]) => {
        const questionCodeInt = parseInt(questionCode, 10);
        const question = visibleQuestions.find(q => q.questionCode === questionCodeInt);

        // Skip if question is not visible (hidden by our filtering logic)
        if (!question) {
          console.log(`🚫 Skipping hidden question ${questionCodeInt} from submission`);
          return null;
        }

        const answerObj = question.tag?.answers?.find(ans => ans.id === answerId);
        const answerText = answerObj?.text ?? answerId;

        let questionScore = 0;
        let category = 'NEUTRAL';
        let weightVal = Number(question?.apiMapping?.weight ?? question?.weight ?? 1);
        let penaltyVal = Number(question?.apiMapping?.penalty ?? question?.penalty ?? 1);

        if (question && question.apiMapping) {
          const scoreResult = calculateQuestionScore(
            { ...question.apiMapping, tag: question.tag },
            answerId
          );
          if (scoreResult) {
            questionScore = scoreResult.score;
            category = scoreResult.category;
            weightVal = Number(scoreResult.weight ?? weightVal);
            penaltyVal = Number(scoreResult.penalty ?? penaltyVal);
          }
        }

        const apiMap = question.apiMapping ?? question;
        const safeArr = toArray(apiMap?.safeanswer);
        const unsafeArr = toArray(apiMap?.unsafeanswer);

        return {
          code: question?.backendCode ?? question?.questionCode ?? question?.code ?? questionCodeInt,
          questionCode: question?.questionCode ?? questionCodeInt,
          answer: answerText ?? '',
          answer_id: answerId,
          nature: natureCode,
          flag: 1,
          score: questionScore,
          category,
          weight: weightVal,
          penalty: penaltyVal,
          safeanswer: safeArr,
          unsafeanswer: unsafeArr
        };
      })
      .filter(item => item !== null); // Remove null entries (hidden questions)

    return codes;
  }, [questions, selectedAnswers, natureCode, shouldShowQuestion]);


  const getEnhancedSubmissionData = useCallback(() => {
    const codesWithScores = getFormattedAnswersForSubmission();
    const scoringResults = calculateAllQuestionScores();

    return {
      questionnaire: codesWithScores,
      scoring: {
        totalScore: scoringResults.totalScore,
        maxPossibleScore: scoringResults.maxPossibleScore,
        percentage: scoringResults.percentage,
        eligibilityStatus: scoringResults.eligibilityStatus,
        answerBreakdown: scoringResults.answerBreakdown,
        timestamp: scoringResults.timestamp
      }
    };
  }, [getFormattedAnswersForSubmission, calculateAllQuestionScores]);


  // Notify parent about loading state changes
  const notifyLoadStateChange = useCallback((loadingState) => {
    if (onLoadStateChange) {
      onLoadStateChange({
        isLoading: loadingState.isLoading,
        hasQuestions: loadingState.hasQuestions,
        questionCount: loadingState.questionCount || 0,
        error: loadingState.error,
        pagination: loadingState.pagination || {}
      });
    }
  }, [onLoadStateChange]);

  // Fetch questions from API
  const fetchQuestions = useCallback(async (forceRefresh = false) => {

    const shouldFetchFromAPI = forceRefresh || !isInitialized || questions.length === 0;

    if (!shouldFetchFromAPI) {
      const successState = {
        isLoading: false,
        hasQuestions: true,
        questionCount: questions.length,
        answeredCount: Object.values(selectedAnswers).filter(Boolean).length,
        error: null,
        pagination: paginationData
      };
      notifyLoadStateChange(successState);
      return {
        success: true,
        message: 'Questions already loaded',
        count: questions.length
      };
    }

    setIsLoading(true);
    setError(null);
    notifyLoadStateChange({
      isLoading: true,
      hasQuestions: false,
      questionCount: 0,
      error: null
    });

    try {
      const apiUrl = buildApiEndpoint(natureCode);

      console.log('🔎 Fetching questionnaire API:', apiUrl);
      console.log('nature:', natureCode, 'gender:', gender);
      console.log('   NetworkServiceCall config:', { timeout: API_CONFIG.timeout, headers: API_CONFIG.headers });

      const response = await NetworkServiceCall('GET', apiUrl, null, null);

      // NetworkServiceCall returns { data, httpstatus }
      if (response.httpstatus === 200 && response.data?.data && Array.isArray(response.data.data)) {
        const apiData = response.data.data;
        setRawApiData(apiData);

        const transformedQuestions = transformApiData(apiData, null, natureCode, gender);



        if (transformedQuestions.length > 0) {
          setQuestions(transformedQuestions);

          // Create paginated groups
          const { grouped, orderedGroupKeys, groupMeta } = organizeQuestionsByGroup(transformedQuestions);
          const pages = createGroupBoundaryAwarePages(grouped, orderedGroupKeys, groupMeta, questionsPerPage);
          setPaginatedGroups(pages);

          const newAnswers = {};
          transformedQuestions.forEach(question => {
            newAnswers[question.questionCode] =
              selectedAnswers[question.questionCode] ||
              initialAnswers[question.questionCode] ||
              null;
          });

          setSelectedAnswers(newAnswers);
          setIsInitialized(true);

          const successState = {
            isLoading: false,
            hasQuestions: true,
            questionCount: transformedQuestions.length,
            answeredCount: Object.values(newAnswers).filter(Boolean).length,
            error: null,
            pagination: {
              totalQuestions: transformedQuestions.length,
              totalPages: pages.length,
              currentPage: 1,
              questionsPerPage
            }
          };

          notifyLoadStateChange(successState);
          return {
            success: true,
            data: transformedQuestions,
            count: transformedQuestions.length
          };
        } else {
          const error = 'No questions found for this allocation';
          setError(error);
          const errorState = {
            isLoading: false,
            hasQuestions: false,
            questionCount: 0,
            error
          };
          notifyLoadStateChange(errorState);
          return { success: false, error };
        }
      } else {
        const error = 'No Questions found for this allocation';
        setError(error);
        const errorState = {
          isLoading: false,
          hasQuestions: false,
          questionCount: 0,
          error
        };
        notifyLoadStateChange(errorState);
        return { success: false, error };
      }
    } catch (error) {
      const errorMessage = error.message || 'Failed to load questions';
      setError(errorMessage);
      const errorState = {
        isLoading: false,
        hasQuestions: false,
        questionCount: 0,
        error: errorMessage
      };
      notifyLoadStateChange(errorState);
      return { success: false, error: errorMessage };
    } finally {
      setIsLoading(false);
    }
  }, [natureCode, transformApiData, isInitialized, questions.length, selectedAnswers, initialAnswers, notifyLoadStateChange, currentLanguage, questionsPerPage, paginationData, organizeQuestionsByGroup, createGroupBoundaryAwarePages, gender]);

  // Load initial answers
  useEffect(() => {
    if (initialAnswers && Object.keys(initialAnswers).length > 0 && questions.length > 0) {
      const hasChanges = Object.keys(initialAnswers).some(key =>
        selectedAnswers[key] !== initialAnswers[key]
      );

      if (!hasChanges) return;

      const mappedAnswers = {};
      questions.forEach((question, index) => {
        const questionCode = question.questionCode || (index + 1);
        if (initialAnswers[questionCode]) {
          mappedAnswers[questionCode] = initialAnswers[questionCode];
        }
      });

      if (Object.keys(mappedAnswers).length > 0) {
        setSelectedAnswers(prev => {
          const newState = { ...prev, ...mappedAnswers };
          if (JSON.stringify(newState) === JSON.stringify(prev)) {
            return prev;
          }
          return newState;
        });
      }
    }
  }, [initialAnswers, questions.length]);

  // Language change
  useEffect(() => {
    if (rawApiData.length > 0) {
      const transformedQuestions = transformApiData(rawApiData, null, natureCode, gender);

      if (transformedQuestions.length > 0) {
        setQuestions(transformedQuestions);

        const { grouped, orderedGroupKeys, groupMeta } = organizeQuestionsByGroup(transformedQuestions);
        const pages = createGroupBoundaryAwarePages(grouped, orderedGroupKeys, groupMeta, questionsPerPage);
        setPaginatedGroups(pages);

        const newAnswers = {};
        transformedQuestions.forEach(question => {
          newAnswers[question.questionCode] = selectedAnswers[question.questionCode] || null;
        });
        setSelectedAnswers(newAnswers);
      }
    }
  }, [currentLanguage, rawApiData, transformApiData, natureCode, gender]);

  // AUTO-LOAD: fetch when component mounts and when nature changes
  useEffect(() => {
    fetchQuestions();
  }, [nature]); // re-fetch when nature changes

  // Clear answers for hidden questions when filtering conditions change
  useEffect(() => {
    if (!questions.length) return;

    const visibleQuestions = questions.filter(q => shouldShowQuestion(q));
    const visibleQuestionCodes = new Set(visibleQuestions.map(q => q.questionCode));

    // Check if any answered questions are now hidden
    const answersToRemove = Object.keys(selectedAnswers)
      .map(code => parseInt(code))
      .filter(code => selectedAnswers[code] && !visibleQuestionCodes.has(code));

    if (answersToRemove.length > 0) {
      console.log('🧹 Clearing answers for hidden questions:', answersToRemove);
      setSelectedAnswers(prev => {
        const updated = { ...prev };
        answersToRemove.forEach(code => {
          delete updated[code];
        });
        return updated;
      });
    }
  }, [questions, selectedAnswers, shouldShowQuestion]);

  // Notify parent when filtered question count changes (e.g., when gender changes)
  const prevCountsRef = useRef({ questionCount: 0, answeredCount: 0 });
  useEffect(() => {
    if (!questions.length || !onLoadStateChange) return;

    const visibleQuestions = questions.filter(q => shouldShowQuestion(q));
    const answeredCount = visibleQuestions.filter(q => selectedAnswers[q.questionCode]).length;
    const questionCount = visibleQuestions.length;

    // Only update if counts actually changed
    if (prevCountsRef.current.questionCount !== questionCount ||
      prevCountsRef.current.answeredCount !== answeredCount) {

      prevCountsRef.current = { questionCount, answeredCount };

      onLoadStateChange({
        isLoading: false,
        hasQuestions: questionCount > 0,
        questionCount,
        answeredCount,
        error: null,
        pagination: paginationData,
        loaded: true
      });
    }
  }, [questions.length, selectedAnswers, shouldShowQuestion, gender]); // Removed onLoadStateChange and paginationData from deps


  // --- UPDATED: Dynamic Select All Logic ---
  const selectAllAnswers = useCallback((targetText) => {
    if (!paginationData.items.length || !targetText) return;

    // Normalize for case-insensitive comparison
    const normalizedTarget = String(targetText).toLowerCase().trim();
    const newAnswers = { ...selectedAnswers };
    let hasChanges = false;

    paginationData.items.forEach(question => {
      const answers = question.tag?.answers || [];

      // Find the answer option where Display Text, English Text, or Malayalam Text matches
      const matchingAnswer = answers.find(a =>
        (a.text && a.text.toLowerCase().trim() === normalizedTarget) ||
        (a.engText && a.engText.toLowerCase().trim() === normalizedTarget) ||
        (a.malText && a.malText.toLowerCase().trim() === normalizedTarget)
      );

      if (matchingAnswer) {
        newAnswers[question.questionCode] = matchingAnswer.id;
        hasChanges = true;
      }
    });

    if (hasChanges) {
      setSelectedAnswers(newAnswers);
    }
  }, [paginationData.items, selectedAnswers]);

  // Clear all answers (CURRENT GROUP ONLY)
  const clearAllAnswers = useCallback(() => {
    const newAnswers = { ...selectedAnswers };
    paginationData.items.forEach(question => {
      newAnswers[question.questionCode] = null;
    });
    setSelectedAnswers(newAnswers);
  }, [paginationData.items, selectedAnswers]);

  // Pagination functions
  const goToPage = useCallback((pageNumber) => {
    if (pageNumber >= 1 && pageNumber <= paginationData.totalPages) {
      setCurrentPage(pageNumber);
    }
  }, [paginationData.totalPages]);

  const goToNextPage = useCallback(() => {
    if (currentPage < paginationData.totalPages) {
      setCurrentPage(prev => prev + 1);
    }
  }, [currentPage, paginationData.totalPages]);

  const goToPrevPage = useCallback(() => {
    if (currentPage > 1) {
      setCurrentPage(prev => prev - 1);
    }
  }, [currentPage]);

  const getGenderAwareQuestions = useCallback(() => {
    // Filter questions using the same logic as display
    return questions.filter(question => shouldShowQuestion(question));
  }, [questions, shouldShowQuestion]);

  const validateAllQuestionsAnswered = useCallback(() => {
    const genderAwareQuestions = getGenderAwareQuestions();
    const total = genderAwareQuestions.length;
    const answered = genderAwareQuestions.filter(question =>
      selectedAnswers[question.questionCode]
    ).length;

    return {
      isValid: answered === total,
      total,
      answered,
      missing: total - answered,
      percentage: total > 0 ? (answered / total) * 100 : 0,
      genderAwareTotal: total,
      originalTotal: questions.length
    };
  }, [questions.length, selectedAnswers, gender, getGenderAwareQuestions]);

  // Validate current page questions are answered
  const validateCurrentPageQuestions = useCallback(() => {
    // paginationData.items is already filtered by shouldShowQuestion in getCurrentPageData
    const visibleQuestions = paginationData.items;

    const answered = visibleQuestions.filter(question =>
      selectedAnswers[question.questionCode]
    ).length;

    return {
      isValid: answered === visibleQuestions.length,
      total: visibleQuestions.length,
      answered,
      missing: visibleQuestions.length - answered,
      originalTotal: paginationData.items.length
    };
  }, [paginationData.items, selectedAnswers]);

  useImperativeHandle(ref, () => ({
    loadQuestions: () => fetchQuestions(true),
    getSelectedAnswers: () => selectedAnswers,
    getFormattedAnswers: () => getFormattedAnswersForSubmission(),
    getEnhancedData: () => getEnhancedSubmissionData(),
    getMediaFiles: () => ({
      videos: recordedVideos,
      images: capturedImages,
      audios: recordedAudios,
    }),
    getQuestionsData: () => {
      const visibleQuestions = getGenderAwareQuestions();
      return {
        questions: visibleQuestions, // Return only visible questions
        selectedAnswers,
        isLoading,
        error,
        isInitialized,
        questionCount: visibleQuestions.length, // Count only visible questions
        answeredCount: visibleQuestions.filter(q => selectedAnswers[q.questionCode]).length, // Count only visible answered
        pagination: paginationData,
      };
    },
    setAnswers: (answersObject = {}) => {
      setSelectedAnswers(prev => ({
        ...prev,
        ...answersObject,
      }));
    },

    refreshQuestions: () => fetchQuestions(true),
    resetAnswers: () => setSelectedAnswers({}),
    resetMedia: () => {
      setRecordedVideos({});
      setCapturedImages({});
      setRecordedAudios({});
    },
  }), [
    selectedAnswers,
    getFormattedAnswersForSubmission,
    getEnhancedSubmissionData,
    recordedVideos,
    capturedImages,
    recordedAudios,
    questions,
    isLoading,
    error,
    isInitialized,
    paginationData,
    fetchQuestions,
    getGenderAwareQuestions,
  ]);

  const previousAnswersRef = useRef({});
  useEffect(() => {
    if (questions.length === 0 || !onAnswersChange) return;

    const currentAnswersString = JSON.stringify(selectedAnswers);
    const previousAnswersString = JSON.stringify(previousAnswersRef.current);

    if (currentAnswersString === previousAnswersString) {
      return;
    }

    previousAnswersRef.current = selectedAnswers;

    const formatted = Object.entries(selectedAnswers)
      .filter(([, ans]) => ans !== null)
      .map(([code, id]) => {
        const q = questions.find(q => q.questionCode === parseInt(code));
        const a = q?.tag?.answers?.find(ans => ans.id === id);
        return {
          questionCode: parseInt(code),
          questionName: q?.name,
          answerId: id,
          answerText: a?.text,
          nature: natureCode,
        };
      });

    const submissionData = getFormattedAnswersForSubmission();
    onAnswersChange(formatted, submissionData);
  }, [selectedAnswers, questions, onAnswersChange, natureCode,]);

  // Handle answer selection
  const handleAnswerSelect = useCallback((questionCode, answerId) => {
    setSelectedAnswers(prev => ({
      ...prev,
      [questionCode]: answerId,
    }));
  }, []);

  // Retry fetching questions
  const handleRetry = useCallback(() => {
    fetchQuestions(true);
  }, [fetchQuestions]);

  // Render a dynamic answer button
  const renderDynamicAnswerButton = (questionCode, answer) => {
    const isSelected = selectedAnswers[questionCode] === answer.id;

    return (
      <TouchableOpacity
        style={[
          styles.dynamicAnswerButton,
          isSelected
            ? styles.dynamicAnswerButtonSelected
            : styles.dynamicAnswerButtonUnselected
        ]}
        onPress={() => handleAnswerSelect(questionCode, answer.id)}
        activeOpacity={0.7}
      >
        <Text
          style={[
            styles.dynamicAnswerButtonText,
            isSelected
              ? styles.dynamicAnswerButtonTextSelected
              : styles.dynamicAnswerButtonTextUnselected
          ]}
        >
          {answer.text}
        </Text>
      </TouchableOpacity>
    );
  };

  const handleVideoDelete = useCallback((questionId) => {
    setRecordedVideos(prev => {
      const updated = { ...prev };
      delete updated[questionId];
      return updated;
    });
  }, []);

  const handleImageDelete = useCallback((questionId) => {
    setCapturedImages(prev => {
      const updated = { ...prev };
      delete updated[questionId];
      return updated;
    });
  }, []);

  const handleAudioDelete = useCallback((questionId) => {
    setRecordedAudios(prev => {
      const updated = { ...prev };
      delete updated[questionId];
      return updated;
    });
  }, []);

  const renderQuestionItem = useCallback(({ item, index }) => {
    const question = item;
    const questionCode = question.questionCode;
    const answers = question.tag?.answers || [];

    return (
      <View style={styles.compactQuestionCard}>
        {/* Question Text */}
        <View style={styles.compactQuestionHeader}>
          <Text style={styles.compactQuestionText}>
            <Text style={{ fontWeight: 'bold' }}>{item.absoluteIndex}.</Text> {question.name}
          </Text>
        </View>

        {/* Answer Buttons Row */}
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          style={styles.compactAnswerOptionsContainer}
          contentContainerStyle={styles.answerScrollContent}
        >
          {answers.map((answer) => (
            renderDynamicAnswerButton(questionCode, answer)
          ))}
        </ScrollView>

        {/* MEDIA RECORDER COMPONENT */}
        {question.allowMedia && (
          <MediaRecorder
            questionId={questionCode}
            onVideoCapture={handleVideoCapture}
            onImageCapture={handleImageCapture}
            onAudioCapture={handleAudioCapture}
            onVideoDelete={handleVideoDelete}
            onImageDelete={handleImageDelete}
            onAudioDelete={handleAudioDelete}
            existingVideo={recordedVideos[questionCode]}
            existingImage={capturedImages[questionCode]}
            existingAudio={recordedAudios[questionCode]}
            allowMedia={question.allowMedia}
          />
        )}
      </View>
    );
  }, [selectedAnswers, handleAnswerSelect, recordedVideos, capturedImages, recordedAudios, handleVideoCapture, handleImageCapture, handleAudioCapture]); // NEW: Added activeMedia dependency

  // Calculate progress
  const progressMetrics = useMemo(() => {
    const genderAwareQuestions = getGenderAwareQuestions();
    const total = genderAwareQuestions.length;
    const answered = genderAwareQuestions.filter(question =>
      selectedAnswers[question.questionCode]
    ).length;
    const percentage = total > 0 ? (answered / total) * 100 : 0;

    return {
      total,
      answered,
      percentage,
      originalTotal: questions.length,
      skippedForGender: questions.length - total
    };
  }, [questions.length, selectedAnswers, gender, getGenderAwareQuestions]);

  const keyExtractor = useCallback((item, index) => {
    return `question - ${item.questionCode} - ${item.backendCode} - ${index}`;
  }, []);

  // Render pagination controls
  const renderPagination = () => {
    if (paginationData.totalPages <= 1) return null;

    const getVisiblePageNumbers = () => {
      const totalPages = paginationData.totalPages;
      const current = currentPage;

      if (totalPages <= 5) {
        return Array.from({ length: totalPages }, (_, i) => i + 1);
      }

      const pages = [];
      if (current > 1) pages.push(current - 1);
      pages.push(current);
      if (current < totalPages) pages.push(current + 1);

      if (!pages.includes(1)) {
        pages.unshift(1);
        if (pages[1] > 2) pages.splice(1, 0, '...');
      }
      if (!pages.includes(totalPages)) {
        pages.push('...');
        pages.push(totalPages);
      }

      return pages;
    };

    const visiblePages = getVisiblePageNumbers();

    return (
      <View style={styles.paginationContainer}>
        <TouchableOpacity
          style={[
            styles.paginationNavButton,
            currentPage <= 1 && styles.paginationButtonDisabled,
          ]}
          onPress={goToPrevPage}
          disabled={currentPage <= 1}
        >
          <Icon
            name="chevron-left"
            size={normalize(16)}
            color={currentPage <= 1 ? THEME.colors.textMuted : 'white'}
          />
          <Text
            style={[
              styles.paginationNavText,
              currentPage <= 1 && styles.paginationButtonTextDisabled,
            ]}
          >
            {isEnglish ? 'Prev' : 'മുമ്പ്'}
          </Text>
        </TouchableOpacity>

        <View style={styles.pageNumbersContainer}>
          {visiblePages.map((page, index) => {
            if (page === '...') {
              return (
                <View key={`dots - ${index}`} style={styles.pageDots}>
                  <Text style={styles.pageDotsText}>•••</Text>
                </View>
              );
            }

            return (
              <TouchableOpacity
                key={page}
                style={[
                  styles.pageNumber,
                  currentPage === page && styles.pageNumberActive,
                ]}
                onPress={() => goToPage(page)}
              >
                <Text
                  style={[
                    styles.pageNumberText,
                    currentPage === page && styles.pageNumberTextActive,
                  ]}
                >
                  {page}
                </Text>
              </TouchableOpacity>
            );
          })}
        </View>

        <TouchableOpacity
          style={[
            styles.paginationNavButton,
            currentPage >= paginationData.totalPages && styles.paginationButtonDisabled,
          ]}
          onPress={goToNextPage}
          disabled={currentPage >= paginationData.totalPages}
        >
          <Text
            style={[
              styles.paginationNavText,
              currentPage >= paginationData.totalPages && styles.paginationButtonTextDisabled,
            ]}
          >
            {isEnglish ? 'Next' : 'അടുത്തത്'}
          </Text>
          <Icon
            name="chevron-right"
            size={normalize(16)}
            color={currentPage >= paginationData.totalPages ? THEME.colors.textMuted : 'white'}
          />
        </TouchableOpacity>
      </View>
    );
  };

  if (isLoading) {
    return (
      <View style={[styles.container, styles.centerContent]}>
        <ActivityIndicator size="large" color={THEME.colors.primary} />
        <Text style={styles.loadingText}>Loading questions...</Text>
      </View>
    );
  }

  if (error && !questions.length) {
    return null;
  }

  if (!questions.length && !isLoading) {
    return (
      <View style={styles.emptyState}>
        <Text style={styles.emptyText}>No questions available</Text>
        <TouchableOpacity style={styles.retryButton} onPress={handleRetry}>
          <Text style={styles.retryButtonText}>Load Questions</Text>
        </TouchableOpacity>
      </View>
    );
  }

  return (
    <View style={[styles.container, style]}>
      {/* Pagination Controls */}
      {renderPagination()}

      {/* Fixed Group Header with Actions */}
      {currentGroupInfo && (
        <View style={styles.fixedGroupHeader}>
          <View style={styles.groupInfoSection}>
            <Text style={styles.fixedGroupName}>{currentGroupInfo.name}</Text>
            <Text style={styles.progressText}>
              {progressMetrics.answered}/{progressMetrics.total} completed
              {paginationData.totalPages > 1 && ` • Page ${currentPage} / ${paginationData.totalPages}`}
            </Text>
          </View>

          {/* --- UPDATED: Dynamic Bulk Action Buttons --- */}
          <View style={styles.bulkActions}>

            {/* Primary Button */}
            {currentGroupInfo.primaryAction ? (
              <TouchableOpacity
                style={[styles.bulkActionButton, styles.bulkYesButton]}
                onPress={() => selectAllAnswers(currentGroupInfo.primaryAction)}
              >
                <Text style={styles.bulkActionText}>
                  All-{currentGroupInfo.primaryAction}
                </Text>
              </TouchableOpacity>
            ) : null}

            {/* Secondary Button */}
            {currentGroupInfo.secondaryAction ? (
              <TouchableOpacity
                style={[styles.bulkActionButton, styles.bulkNoButton]}
                onPress={() => selectAllAnswers(currentGroupInfo.secondaryAction)}
              >
                <Text style={styles.bulkActionText}>
                  All-{currentGroupInfo.secondaryAction}
                </Text>
              </TouchableOpacity>
            ) : null}

            <TouchableOpacity
              style={[styles.bulkActionButton, styles.bulkClearButton]}
              onPress={clearAllAnswers}
            >
              <Text style={styles.bulkActionText}>Clear</Text>
            </TouchableOpacity>
          </View>
        </View>
      )}

      {/* Questions list */}
      <FlatList
        data={paginationData.items}
        renderItem={renderQuestionItem}
        keyExtractor={keyExtractor}
        contentContainerStyle={styles.listContent}
        showsVerticalScrollIndicator={false}
      />

    </View>
  );
});

