import React, { useState, useEffect } from 'react';
import { View, Text, TextInput, Dimensions } from 'react-native';
import Icon from 'react-native-vector-icons/Feather';
import ModernMultiSelectDropdown from './ModernMultiSelectDropdown';
import { Global } from '../Common/Global';
import { APIURL } from '../Common/apiConstants';
import { normalize } from '../CommonStyle/componentStyle';

const AllergyDropdown = ({
  selectedAllergies,
  setSelectedAllergies,
  otherAllergyText,
  getText,
  setOtherAllergyText,
  label = getText('allergies'),
  defaultSelectedNames = [],
  masterList = []
}) => {
  // ✅ Safe initialization - always use array
  const safeSelectedAllergies = selectedAllergies || [];

  const [displayText, setDisplayText] = useState('Select Allergies');
  const [selectedAllergyNames, setSelectedAllergyNames] = useState(defaultSelectedNames);
  const [showOverlay, setShowOverlay] = useState(false);
  const [allergyOptions, setAllergyOptions] = useState([]);
  const [isInitialized, setIsInitialized] = useState(false);

  // ✅ Debug logging
  useEffect(() => {
    console.log('🔍 AllergyDropdown props:', {
      selectedAllergies,
      safeSelectedAllergies,
      defaultSelectedNames,
      otherAllergyText
    });
  }, [selectedAllergies, defaultSelectedNames, otherAllergyText]);

  // ✅ Sync when defaultSelectedNames changes (for fetched data)
  useEffect(() => {
    if (defaultSelectedNames.length > 0 && !isInitialized) {
      console.log('🔄 Initializing with fetched allergies:', defaultSelectedNames);
      setSelectedAllergyNames(defaultSelectedNames);
      setDisplayText(defaultSelectedNames.join(', '));
      setIsInitialized(true);
    }
  }, [defaultSelectedNames, isInitialized]);

  // ✅ Update display text whenever selectedAllergies changes
  useEffect(() => {
    if (safeSelectedAllergies.length > 0) {
      if (safeSelectedAllergies.length === 1) {
        setDisplayText(getText('selected one Allergy'));
      } else {
        setDisplayText(`${getText('selected')} ${safeSelectedAllergies.length} ${getText('allergies')}`);
      }
    } else {
      setDisplayText(getText('optional'));
    }
  }, [safeSelectedAllergies, getText]);

  // ✅ Map allergy names to IDs for the dropdown
  const getAllergyIdFromName = (allergyName) => {
    const allergyMap = {
      'No Known Allergies': 1,
      'Drug Allergies': 2,
      'Food Allergies': 3,
      'Environmental Allergies': 4,
      'Seasonal Allergies': 5,
      'Latex Allergy': 6,
      'Metal Allergies': 7,
      'Animal Allergies': 8,
      'Insect Sting Allergies': 9,
      'Pollen Allergy': 10,
      'Dust Allergy': 11,
      'Other (specify below)': 12,
    };
    return allergyMap[allergyName];
  };

  // ✅ Initialize with fetched allergy data
  useEffect(() => {
    if (defaultSelectedNames.length > 0 && safeSelectedAllergies.length === 0) {
      const fetchedAllergyIds = defaultSelectedNames.map(name => getAllergyIdFromName(name)).filter(id => id);
      console.log('🎯 Converting fetched names to IDs:', {
        names: defaultSelectedNames,
        ids: fetchedAllergyIds
      });

      if (fetchedAllergyIds.length > 0) {
        setSelectedAllergies(fetchedAllergyIds);
      }
    }
  }, [defaultSelectedNames, safeSelectedAllergies.length]);

  const handleSelectionChange = (newIds, newItems) => {
    // Determine what changed to apply exclusive logic
    const prevIds = safeSelectedAllergies;

    let finalIds = [...newIds];
    let finalItems = [...newItems];

    // Check if "No Known Allergies" (ID 1) was newly selected
    const justSelectedNoKnown = !prevIds.includes(1) && finalIds.includes(1);

    if (justSelectedNoKnown) {
      // Clear all others
      finalIds = [1];
      finalItems = finalItems.filter(i => i.datavalue === 1);
      setOtherAllergyText('');
    } else if (finalIds.includes(1) && finalIds.length > 1) {
      // If "No Known" matches exists with others, remove "No Known"
      finalIds = finalIds.filter(id => id !== 1);
      finalItems = finalItems.filter(i => i.datavalue !== 1);
    }

    // Update State
    setSelectedAllergies(finalIds);
    setSelectedAllergyNames(finalItems.map(i => i.displayvalue));

    // Update display text
    if (finalIds.length === 0) {
      setDisplayText('Select Allergies');
    } else if (finalIds.length === 1 && finalIds[0] === 1) {
      setDisplayText('No Known Allergies');
    } else {
      const names = finalItems.map(i => i.displayvalue);
      setDisplayText(names.join(', '));
    }

    // Clear other text if "Other" (ID 12) is deselected
    if (!finalIds.includes(12)) {
      setOtherAllergyText('');
    }
  };

  const clearSelection = () => {
    setSelectedAllergies([]);
    setSelectedAllergyNames([]);
    setOtherAllergyText('');
    setDisplayText('Select Allergies');
    setIsInitialized(false);
  };

  const handleOtherTextChange = (text) => {
    setOtherAllergyText(text);
  };

  return (
    <View>
      {/* Label */}
      <Text style={{
        fontSize: 12,
        fontWeight: '600',
        color: '#094485',
        marginBottom: 1,
        marginLeft: 4
      }}>
        {label}
      </Text>

      {/* Dropdown */}
      <ModernMultiSelectDropdown
        label={null} // We render our own label above
        placeholder="Select Allergies"
        api="bldgetweb/common/rnbbsuallergiesdropdownselect"
        searchable={true}
        value={safeSelectedAllergies}
        displayValue={displayText}
        onChange={handleSelectionChange}
        icon="alert-circle"
        iconGroup="Feather"
        masterList={masterList}
      />

      {/* Other Allergy Text Input - Show when ID 12 is selected */}
      {/* ✅ FIXED: Use safeSelectedAllergies instead of selectedAllergies */}
      {safeSelectedAllergies.includes(12) && (
        <View style={{ marginTop: 12 }}>
          <Text style={{
            fontSize: 12,
            fontWeight: '600',
            color: '#374151',
            marginBottom: 4,
            marginLeft: 4
          }}>
            Specify Other Allergies
          </Text>
          <TextInput
            placeholder="Please specify other allergies..."
            placeholderTextColor="#9ca3af"
            value={otherAllergyText}
            onChangeText={handleOtherTextChange}
            style={{
              borderWidth: 1,
              borderColor: '#d1d5db',
              borderRadius: 6,
              padding: 12,
              fontSize: 14,
              backgroundColor: '#f9fafb',
              minHeight: 40,
            }}
            multiline={true}
            textAlignVertical="top"
          />
        </View>
      )}

      {/* Display Selected Allergies for Debug */}
      {safeSelectedAllergies.length > 0 && (
        <View style={{ marginTop: 8, padding: 8, backgroundColor: '#f0f9ff', borderRadius: 4 }}>
          <Text style={{ fontSize: 12, color: '#1e40af' }}>
            {/* Selected IDs: [{safeSelectedAllergies.join(', ')}] */}
            Names: {selectedAllergyNames.join(', ')}
            {otherAllergyText && ` | Other Text: "${otherAllergyText}"`}
          </Text>
        </View>
      )}

      {/* Fetched Data Indicator
      {defaultSelectedNames.length > 0 && (
        <View style={{ marginTop: 4, padding: 4, backgroundColor: '#ecfdf5', borderRadius: 4 }}>
          <Text style={{ fontSize: 10, color: '#065f46', fontStyle: 'italic' }}>
            📋 Fetched allergies: {defaultSelectedNames.join(', ')}
          </Text>
        </View>
      )} */}

    </View>

  );

};

export default AllergyDropdown;