import React from 'react'
import { View, Text, TouchableOpacity, StyleSheet } from 'react-native'
// import AwesomeButton from "react-native-really-awesome-button"; // Not available for web
import { isNU, notifyMessage } from '../CommonStyle/ComponentFunctions';
import { normalize } from '../CommonStyle/componentStyle';
import HOCIcons from '../HOC/HOCIcons';

export default function CAwesomeButton({ data, callBack }) {
    function getCallBack(item) {
        callBack(item)
    }

    return (
        <View
            style={{
                shadowColor: '#000',
                shadowOffset: { width: 0, height: 2 },
                shadowOpacity: 0.2,
                shadowRadius: 3,
                elevation: 5, // Android shadow
                borderRadius: 10,
                marginVertical: 4,
            }}
        >
            <TouchableOpacity
                onPress={() => data.functionid != undefined ? getCallBack(data) : notifyMessage("Incorporate soon", 5)}
                style={[
                    styles.button,
                    {
                        height: normalize(40),
                        width: normalize(data.width != undefined ? data.width : 55),
                        backgroundColor: data.shadowcolor != undefined ? data.shadowcolor : "#f7efef",
                    }
                ]}
            >
                <View style={{ alignItems: 'center', justifyContent: 'center' }}>
                    <HOCIcons.Icons
                        icongroup={isNU(data.icongroup) ? data.icongroup : 5}
                        name={data.iconname != undefined ? data.iconname : "file"}
                        color={data.iconcolor != undefined ? data.iconcolor : "white"}
                        size={data.iconsize != undefined ? normalize(data.iconsize) : normalize(20)}
                    />
                    <Text
                        numberOfLines={1}
                        style={{
                            width: isNU(data.textwidth) ? normalize(data.textwidth) : normalize(50),
                            color: data.fontcolor != undefined ? data.fontcolor : "#fff",
                            textAlign: data.textAlign != undefined ? data.textAlign : 'center',
                            fontSize: data.size != undefined ? normalize(data.size) : normalize(10),
                            fontWeight: data.fontWeight != undefined ? data.fontWeight : 'normal'
                        }}
                    >
                        {data.displaytext != undefined ? data.displaytext : ''}
                    </Text>
                </View>
            </TouchableOpacity>
        </View>
    )
}

const styles = StyleSheet.create({
    button: {
        borderRadius: 10,
        borderWidth: 1,
        borderColor: 'lightblue',
        alignItems: 'center',
        justifyContent: 'center',
        padding: 0,
    }
});
