import React, { useState, useEffect, useRef, useCallback } from 'react';
import {
  SafeAreaView,
  View,
  StyleSheet,
  ActivityIndicator,
  Alert,
  Modal,
  Text,
  Image,
} from 'react-native';
// import { WebView } from '../Custom/WebViewShim'; // Replaced by HtmlContentViewer
import HtmlContentViewer from '../Custom/htmlcontentViewer';
import CFooterView from '../CustomComponents/CFooterView';
import CAwesomeButton from '../CustomComponents/CAwesomeButton';
import { notifyMessage } from '../CommonStyle/ComponentFunctions';
import RNHTMLtoPDF from 'react-native-html-to-pdf';
import RNFetchBlob from 'react-native-blob-util';
import moment from 'moment';
import { APIURL } from '../Common/apiConstants';
import Loader from '../Custom/Loader';
import { BackHandler } from 'react-native';
import CBackHandler from '../CustomComponents/CBackHandler';
import HReportFormat from '../Html/HReportFormat';
import HReportHeader from '../Html/HReportHeader';
import HReportFooter from '../Html/HReportFooter';
import HReportWaterMark from '../Html/HReportWaterMark';
import { Global } from '../Common/Global';



const RegistrationHTMLPreview = ({
  isVisible,
  onClose,
  formData,
  photo,
  signature,
  calculateAge,
  handleSubmit,
  getAllergyNames,
  formatDisplayDateForApi,
  isLoading = false,
  getText,
  bmi,
  questionnaireAnswers,
  questionnaireQuestions = [],
  isDeclareMode = false,
  isEditMode = false,  // ✅ New prop for edit mode (no OTP/signature required)
  onSignatureRequired,
  generatePdfOnSave = true,
  navigation,
}) => {
  const [htmlContent, setHtmlContent] = useState('');
  const [isGeneratingHTML, setIsGeneratingHTML] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingMessage, setProcessingMessage] = useState('');
  const [showBackConfirm, setShowBackConfirm] = useState(false);
  const webViewRef = useRef(null);


  useEffect(() => {
    const onBackPress = () => {
      if (isVisible) {
        setShowBackConfirm(true);
        return true; // prevent default back action
      }
      return false;
    };

    const backHandler = BackHandler.addEventListener(
      'hardwareBackPress',
      onBackPress,
    );

    return () => backHandler.remove();
  }, [isVisible]);


  // Optimized image processing with base64 conversion
  const processImage = useCallback(async (imageUri, isSignature = false) => {
    if (!imageUri?.uri) {
      return isSignature
        ? '<div style="height:50px;border-bottom:1px solid #ccc;color:#aaa;font-size:8px;padding:4px 0;">No Signature</div>'
        : '<div style="width:90px;height:110px;border:1px solid #ccc;display:flex;align-items:center;justify-content:center;color:#aaa;font-size:8px;">No Photo</div>';
    }

    try {
      if (Platform.OS === 'web') {
        const uri = imageUri.uri;
        // On web, we can usually just use the URI directly if it's external, or maybe we can't fetch it due to CORS.
        // For local files (blob:), they work in img src.
        // For signature/photo which are likely base64 or blob urls on web:
        return isSignature
          ? `<img src="${uri}" style="max-width:130px;max-height:32px;display:block;" alt="Signature"/>`
          : `<img src="${uri}" style="width:100px;height:100px;object-fit:cover;border:1px solid #ccc;" alt="Photo"/>`;
      }

      let base64Data = '';
      const uri = imageUri.uri;

      if (uri.startsWith('http://') || uri.startsWith('https://')) {
        const response = await RNFetchBlob.config({ fileCache: true }).fetch(
          'GET',
          uri,
        );
        const imagePath = response.path();
        base64Data = await RNFetchBlob.fs.readFile(imagePath, 'base64');
        await RNFetchBlob.fs.unlink(imagePath);
      } else {
        const filePath = uri.replace('file://', '');
        base64Data = await RNFetchBlob.fs.readFile(filePath, 'base64');
      }

      const imageType = isSignature ? 'png' : 'jpeg';

      return isSignature
        ? `<img src="data:image/${imageType};base64,${base64Data}" style="max-width:130px;max-height:32px;display:block;" alt="Signature"/>`
        : `<img src="data:image/${imageType};base64,${base64Data}" style="width:100px;height:100px;object-fit:cover;border:1px solid #ccc;" alt="Photo"/>`;
    } catch (error) {
      console.error(
        `Image error (${isSignature ? 'signature' : 'photo'}):`,
        error,
      );
      return isSignature
        ? '<div style="height:28px;color:#c33;font-size:8px;padding:4px 0;">Error</div>'
        : '<div style="width:90px;height:110px;border:1px solid #ccc;color:#c33;font-size:8px;display:flex;align-items:center;justify-content:center;">Error</div>';
    }
  }, []);

  const formatQuestionnaireAnswers = useCallback(() => {
    if (!questionnaireAnswers || Object.keys(questionnaireAnswers).length === 0)
      return '';

    const rows = Object.entries(questionnaireAnswers)
      .map(([questionCode, answerId], index) => {
        const question = questionnaireQuestions.find(
          q => q.questionCode?.toString() === questionCode.toString(),
        );
        const questionText = question?.name || `Question ${questionCode}`;
        const answerText = answerId === 'answer_yes' ? 'Yes' : 'No';
        const isYes = answerText === 'Yes';
        const answerClass = isYes ? 'yes' : 'no';
        const rowBg = index % 2 === 0 ? '#fff' : '#fafafa';
        return `<tr style="background:${rowBg}"><td style="padding:2px 4px;border:1px solid #eee;font-size:7pt">${questionText}</td><td class="ans ${answerClass}" style="padding:2px;border:1px solid #eee">${answerText}</td></tr>`;
      })
      .join('');

    return `<table class="q-table"><thead><tr><th>Question</th><th style="width:40px;text-align:center">Ans</th></tr></thead><tbody>${rows}</tbody></table>`;
  }, [questionnaireAnswers, questionnaireQuestions]);

  const generateHTMLReport = useCallback(async () => {
    if (!isVisible) return;
    setIsGeneratingHTML(true);

    try {
      const [photoHtml, signatureHtml] = await Promise.all([
        processImage(photo),
        processImage(signature, true),
      ]);

      // Load watermark image and convert to base64
      let watermarkImageBase64 = '';
      try {
        const watermarkUrl = Global.AmalaWatermark;

        console.log('Fetching watermark from URL:', watermarkUrl);

        if (Platform.OS === 'web') {
          // On web, we cannot use RNFetchBlob. Just SKIP base64 conversion for now and use URL directly if possible, or skip watermark image if CORS issues.
          // For simplicity, let's just use the URL directly in the HTML if it's accessible.
          // watermarkImageBase64 = ... (complex to fetch base64 without canvas or fetch)
          // If we leave watermarkImageBase64 empty, it falls back to text.
          console.log('Skipping watermark base64 fetch on web');
        } else {
          // Fetch the image and convert to base64
          const response = await RNFetchBlob.config({ fileCache: true }).fetch('GET', watermarkUrl);
          const imagePath = response.path();
          watermarkImageBase64 = await RNFetchBlob.fs.readFile(imagePath, 'base64');
          await RNFetchBlob.fs.unlink(imagePath);
        }

        console.log('Watermark image loaded, base64 length:', watermarkImageBase64.length);
      } catch (err) {
        console.log('Watermark image load error:', err);
      }

      const questionsHtml = formatQuestionnaireAnswers();
      const currentAge = calculateAge(formatDisplayDateForApi(formData.dob));
      const formattedDate = new Date().toLocaleDateString('en-GB', {
        day: '2-digit',
        month: 'short',
        year: 'numeric',
      });
      const fullAddress =
        [formData.houseName, formData.street, formData.postOffice, formData.landmark, formData.city, formData.state, formData.country]
          .filter(Boolean)
          .join(', ') + (formData.pinCode ? ` - ${formData.pinCode}` : '');

      // Simple and compact HTML matching other reports style
      const watermarkHtml = watermarkImageBase64
        ? HReportWaterMark('', '', `data:image/png;base64,${watermarkImageBase64}`)
        : HReportWaterMark('Amala Donor Registration', '#ccc');

      console.log('Using watermark:', watermarkImageBase64 ? 'IMAGE' : 'TEXT');

      const contentHtml = `
${watermarkHtml}
<style>
body{font-family:'Helvetica',sans-serif;font-size:8pt;color:#000;line-height:1.3;margin:0;padding:5px;position:relative;}
.page-content{position:relative;z-index:1;}
.title{text-align:center;font-size:11pt;font-weight:bold;color:#094485;padding:6px 0;border-bottom:2px solid #094485;margin-bottom:8px}
.section{margin-bottom:6px;background:#fff;}
.section-header{background:#f2f2f2;padding:4px 8px;font-weight:bold;font-size:8pt;border:1px solid #ccc;border-bottom:none}
.section-body{border:1px solid #ccc;padding:6px 8px;background:#fff;}
table{width:100%;border-collapse:collapse}
td{padding:3px 5px;vertical-align:top;font-size:7.5pt}
.lbl{width:28%;color:#333;font-weight:normal}
.val{color:#000;font-weight:bold}
.row{display:flex;gap:8px}
.row>.col{flex:1}
.photo-box{float:right;margin-left:10px;border:1px solid #094485;padding:2px;background:#fff;}
.q-table{width:100%;border-collapse:collapse;font-size:7pt}
.q-table th{background:#f2f2f2;padding:4px;text-align:left;border:1px solid #ccc;font-size:7pt}
.q-table td{padding:3px 4px;border:1px solid #eee;background:#fff;}
.q-table .ans{text-align:center;width:45px;font-weight:bold}
.yes{color:#0d6efd;background:#e7f1ff}
.no{color:#198754;background:#d1f5e0}
.sig-section{margin-top:10px;padding:8px;border:1px solid #ccc;background:#fafafa}
.sig-title{font-weight:bold;font-size:8pt;margin-bottom:6px}
.sig-text{font-size:7pt;color:#333;margin-bottom:8px}
.sig-row{display:flex;justify-content:space-between;align-items:flex-end;gap:30px}
.sig-block{text-align:center}
.sig-img{min-height:35px;margin-bottom:3px}
.sig-line{border-top:1px solid #000;padding-top:3px;font-size:7pt;color:#555}
</style>

<div class="page-content">
<div class="title">DONOR REGISTRATION FORM</div>

<div class="section">
  <div class="section-header">Personal Information</div>
  <div class="section-body">
    <div class="photo-box">${photoHtml}</div>
    <table>
      <tr><td class="lbl">Full Name</td><td class="val">${(formData.firstName || '') + ' ' + (formData.lastName || '')}</td></tr>
      <tr><td class="lbl">Date of Birth</td><td class="val">${formData.dob || 'N/A'}</td></tr>
      <tr><td class="lbl">Age / Gender</td><td class="val">${currentAge || 'N/A'} Years / ${formData.gender || 'N/A'}</td></tr>
      <tr><td class="lbl">Mobile</td><td class="val">${formData.mobile || 'N/A'}</td></tr>
      <tr><td class="lbl">WhatsApp</td><td class="val">${formData.whatsapp || 'N/A'}</td></tr>
      <tr><td class="lbl">Email</td><td class="val">${formData.email || 'N/A'}</td></tr>
    </table>
    <div style="clear:both"></div>
  </div>
</div>

<div class="section">
  <div class="section-header">Address</div>
  <div class="section-body">
    <div class="val">${fullAddress || 'N/A'}</div>
  </div>
</div>

<div class="row">
  <div class="col">
    <div class="section">
      <div class="section-header">Identification</div>
      <div class="section-body">
        <table>
          <tr><td class="lbl">Aadhar</td><td class="val">${formData.aadharId || 'N/A'}</td></tr>
          <tr><td class="lbl">ABHA</td><td class="val">${formData.abhaId || 'N/A'}</td></tr>
          <tr><td class="lbl">Passport</td><td class="val">${formData.passport || 'N/A'}</td></tr>
        </table>
      </div>
    </div>
  </div>
  <div class="col">
    <div class="section">
      <div class="section-header">Professional</div>
      <div class="section-body">
        <table>
          <tr><td class="lbl">Education</td><td class="val">${formData.education || 'N/A'}</td></tr>
          <tr><td class="lbl">Occupation</td><td class="val">${formData.occupation || 'N/A'}</td></tr>
        </table>
      </div>
    </div>
  </div>
</div>

${formData.allergies && formData.allergies.length > 0 ? `
<div class="section">
  <div class="section-header">Medical Information</div>
  <div class="section-body">
    <table>
      <tr><td class="lbl">Allergies</td><td class="val">${getAllergyNames ? getAllergyNames(formData.allergies).join(', ') : formData.allergies.join(', ')}${formData.otherAllergyText ? ', ' + formData.otherAllergyText : ''}</td></tr>
    </table>
  </div>
</div>` : ''}

${formData.remarks ? `
<div class="section">
  <div class="section-header">Remarks</div>
  <div class="section-body"><div class="val">${formData.remarks}</div></div>
</div>` : ''}

${questionsHtml ? `
<div class="section">
  <div class="section-header">Health Screening Questionnaire</div>
  <div class="section-body">${questionsHtml}</div>
</div>` : ''}

<div class="sig-section">
  <div class="sig-title">Declaration</div>
  <div class="sig-text">I hereby declare that the above information is true and correct. I voluntarily consent to donate blood and understand the associated risks.</div>
  <div class="sig-row">
    <div class="sig-block">
      <div class="sig-img">${signatureHtml}</div>
      <div class="sig-line">Donor's Signature</div>
    </div>
    <div class="sig-block">
      <div style="font-size:8pt;font-weight:bold">${formattedDate}</div>
      <div class="sig-line">Date of Registration</div>
    </div>
  </div>
</div>
</div>
`;

      const htmlReport = HReportFormat(contentHtml, HReportHeader({ hospitalname: Global.hospitaladdress[0] }), HReportFooter(), '105px', '95px');

      setHtmlContent(htmlReport);
    } catch (error) {
      console.error('HTML generation error:', error);
      Alert.alert('Error', 'Failed to generate report');
    } finally {
      setIsGeneratingHTML(false);
    }
  }, [
    isVisible,
    formData,
    photo,
    signature,
    questionnaireAnswers,
    processImage,
    formatQuestionnaireAnswers,
    calculateAge,
    formatDisplayDateForApi,
    getAllergyNames,
    bmi,
  ]);

  const handleGenerateAndUploadPdf = useCallback(async () => {
    if (isProcessing) return null;

    try {
      setIsProcessing(true);
      // setProcessingMessage('Loading.....');

      const timestamp = moment().format('DDMMYYYY_HHmmss');
      const fileName = `donor_reg_${formData.firstName || 'donor'
        }_${timestamp}.pdf`;

      if (Platform.OS === 'web') {
        console.warn('PDF generation & upload skipped on web (not supported). Returning mock data.');
        setIsProcessing(false);
        return {
          pdfUri: 'http://mock-pdf-url/doc.pdf',
          pdfFilename: fileName,
        };
      }

      const pdfOptions = {
        html: htmlContent,
        fileName: fileName,
        directory: 'Documents',
        base64: false,
        padding: 0,
      };

      const pdfFile = await RNHTMLtoPDF.convert(pdfOptions);
      console.log('✅ PDF generated:', pdfFile.filePath);

      // setProcessingMessage('Loading...');
      const uploadResult = await uploadPDFToBackend(pdfFile.filePath, fileName);

      if (uploadResult.success) {
        console.log('✅ PDF uploaded:', uploadResult.uploadedUri);
        setProcessingMessage('Complete!');

        setTimeout(() => {
          // notifyMessage('PDF generated successfully', 1);
          setIsProcessing(false);
          setProcessingMessage('');
        }, 400);

        return {
          pdfUri: uploadResult.uploadedUri,
          pdfFilename: uploadResult.uploadedFilename,
        };
      } else {
        throw new Error(uploadResult.error || 'Upload failed');
      }
    } catch (error) {
      console.error('❌ PDF error:', error);
      Alert.alert('Error', `Failed to generate PDF: ${error.message}`);
      setIsProcessing(false);
      setProcessingMessage('');
      return null;
    }
  }, [htmlContent, formData, isProcessing]);

  const uploadPDFToBackend = async (pdfPath, filename) => {
    try {
      const response = await RNFetchBlob.fetch(
        'POST',
        APIURL + 'bldfile/fileupload/emr/document',
        { 'Content-Type': 'multipart/form-data' },
        [
          {
            name: 'file',
            filename: filename,
            type: 'application/pdf',
            data: RNFetchBlob.wrap(pdfPath),
          },
        ],
      );

      const status = response.info().status;
      if (status >= 200 && status < 300) {
        const responseData = response.json();
        return {
          success: true,
          uploadedUri: responseData.fileuri || responseData.data?.fileuri,
          uploadedFilename: filename,
        };
      } else {
        console.error(`Upload failed with status ${status}`);
        return { success: false, error: `Server error ${status}` };
      }
    } catch (error) {
      console.error('Upload error:', error);
      return { success: false, error: error.message };
    }
  };

  const handleBackToDashboard = () => {
    onClose();
    if (navigation) {
      navigation.goBack();
    }
  };

  useEffect(() => {
    if (isVisible) {
      generateHTMLReport();
    }
  }, [isVisible, generateHTMLReport]);

  const onConfirmAndSave = async () => {
    if (generatePdfOnSave) {
      // Create a timeout promise that rejects after 15 seconds
      const timeoutPromise = new Promise((_, reject) => {
        setTimeout(() => {
          reject(new Error('Operation timed out after 15 seconds'));
        }, 15000);
      });

      try {
        // Race between the actual operation and the timeout
        const pdfResult = await Promise.race([
          handleGenerateAndUploadPdf(),
          timeoutPromise
        ]);

        if (pdfResult && handleSubmit) {
          handleSubmit(pdfResult);
        }
      } catch (error) {
        console.error('Save operation failed:', error);

        // Reset processing state
        setIsProcessing(false);
        setProcessingMessage('');

        // Show error alert
        Alert.alert(
          'Save Failed',
          error.message === 'Operation timed out after 15 seconds'
            ? 'The save operation took too long and was cancelled. Please try again.'
            : `Failed to save: ${error.message}`,
          [{ text: 'OK' }]
        );
      }
    } else {
      if (handleSubmit) {
        handleSubmit(null);
      }
    }
  };

  const onDonateAction = (donationType) => {
    // Start PDF generation in background (don't await)
    const pdfPromise = handleGenerateAndUploadPdf();

    if (onSignatureRequired) {
      // Pass the promise instead of the result
      onSignatureRequired(pdfPromise, donationType);
    }
  };

  if (!isVisible) return null;

  return (
    <>
      <Modal
        visible={isVisible}
        animationType="slide"
        transparent={false}
        onRequestClose={() => {
          setShowBackConfirm(true);
        }}>
        <SafeAreaView style={styles.container}>
          <View style={styles.header}>
            <Text style={styles.title}>Registration Preview</Text>
          </View>

          {isGeneratingHTML ? (
            <View style={styles.loadingContainer}>
              <ActivityIndicator size="large" color="#094485" />
              <Text style={styles.loadingText}>Generating Preview...</Text>
            </View>
          ) : (
            <HtmlContentViewer
              htmlContent={htmlContent}
              width="100%"
              height="100%"
            />
          )}

          <CFooterView>
            <View style={styles.footer}>
              {/* ✅ Edit mode: Show simple Back + Save buttons (no OTP/signature) */}
              {isEditMode ? (
                <>
                  <CAwesomeButton
                    data={{
                      ...buttonStyles.back,
                      disabled: isLoading || isProcessing,
                    }}
                    callBack={() => setShowBackConfirm(true)}
                  />
                  <CAwesomeButton
                    data={{
                      ...buttonStyles.save,
                      displaytext: 'Update',
                      disabled: isLoading || isProcessing,
                    }}
                    callBack={onConfirmAndSave}
                  />
                </>
              ) : isDeclareMode ? (
                <>
                  <CAwesomeButton
                    data={{
                      ...buttonStyles.donateLater,
                      disabled: isLoading || isProcessing,
                    }}
                    callBack={() => onDonateAction('later')}
                  />
                  <CAwesomeButton
                    data={{
                      ...buttonStyles.donateNow,
                      disabled: isLoading || isProcessing,
                    }}
                    callBack={() => onDonateAction('now')}
                  />

                </>
              ) : (
                <>
                  <CAwesomeButton
                    data={{
                      ...buttonStyles.back,
                      disabled: isLoading || isProcessing,
                    }}
                    callBack={() => setShowBackConfirm(true)}
                  />
                  <CAwesomeButton
                    data={{
                      ...buttonStyles.save,
                      disabled: isLoading || isProcessing,
                    }}
                    callBack={onConfirmAndSave}
                  />
                </>
              )}
            </View>
          </CFooterView>
        </SafeAreaView>
      </Modal>

      {/* Move CBackHandler here - outside the Modal */}
      {showBackConfirm && (
        <CBackHandler
          type={8}
          displaytext="Do you really want to go back?"
          callBack={response => {
            setShowBackConfirm(false);
            if (response) {
              onClose(); // This should navigate back to registration form
            }
          }}
          close={() => setShowBackConfirm(false)}
        />
      )}

      <Loader
        visible={isProcessing}
        message={processingMessage}
        overlayColor="rgba(0,0,0,0.75)"
        size={40}
        hasBackground={true}
        shadow={true}
        messageStyle={{
          fontSize: 16,
          fontWeight: '600',
          color: '#004aad',
        }}
      />
    </>
  );
};

const buttonStyles = {
  back: {
    functionid: 'back',
    displaytext: 'Back',
    width: 120,
    iconname: 'arrow-left',
    icongroup: 3,
    fontcolor: '#333',
    shadowcolor: '#e9ecef',
    iconcolor: '#333',
  },
  save: {
    functionid: 'save',
    displaytext: 'Save',
    width: 180,
    iconname: 'save',
    icongroup: 5,
    fontcolor: '#fff',
    shadowcolor: '#28a745',
    iconcolor: '#fff',
  },
  donateLater: {
    functionid: 'donatelater',
    displaytext: 'Donate Later',
    width: 150,
    iconname: 'calendar-clock',
    icongroup: 3,
    fontcolor: '#333',
    shadowcolor: '#e9ecef',
    iconcolor: '#333',
    textwidth: 120
  },
  donateNow: {
    functionid: 'donatenow',
    displaytext: 'Donate Now',
    width: 150,
    iconname: 'tint',
    icongroup: 5,
    fontcolor: '#fff',
    shadowcolor: '#28a745',
    iconcolor: '#fff',
  },
};

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: '#f9f9f9' },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    padding: 10,
    backgroundColor: '#fff',
    borderBottomWidth: 1,
    borderBottomColor: '#eee',
  },
  title: { fontSize: 13, fontWeight: '600', color: '#333' },
  webview: { flex: 1, margin: 8, backgroundColor: '#fff' },
  loadingContainer: { flex: 1, justifyContent: 'center', alignItems: 'center' },
  loadingText: { marginTop: 12, fontSize: 16, color: '#666' },
  footer: {
    flexDirection: 'row',
    justifyContent: 'space-around',
    alignItems: 'center',
    paddingHorizontal: 16,
    paddingVertical: 12,
    gap: 12,
  },
});

export default React.memo(RegistrationHTMLPreview);
