import React, { useState, useEffect } from 'react';
import {
  Modal,
  View,
  Text,
  TextInput,
  TouchableOpacity,
  ScrollView,
  StyleSheet,
  Alert,
  KeyboardAvoidingView,
  Platform,
  Keyboard,
  ActivityIndicator
} from 'react-native';
import HOCIcons from '../HOC/HOCIcons';
import { normalize } from '../CommonStyle/componentStyle';
import { Global } from '../Common/Global';
import moment from 'moment';

// Import the exact BagCard component
import BagCard from './BagCard';

const MOCK_PATIENT_DB = {
  '1001': { name: 'Rajesh Kumar', ward: 'ICU-02', age: '45', sex: 'M' },
  '1002': { name: 'Sarah Jones', ward: 'Gen-Ward-A', age: '32', sex: 'F' },
  'P999': { name: 'Emergency Unknown', ward: 'Trauma Center', age: '??', sex: '?' },
};

// --- ISOLATED INPUT COMPONENT ---
const FocusableInput = ({
  label,
  required,
  iconName,
  value,
  onChangeText,
  placeholder,
  rightElement,
  isTextArea,
  isSuccess,
  containerStyle,
  inputStyle,
  ...props
}) => {
  return (
    <View style={[styles.fieldContainer, containerStyle]}>
      {label && (
        <Text style={styles.label}>
          {label} {required && <Text style={{ color: '#ef4444' }}>*</Text>}
        </Text>
      )}
      <View style={[
        styles.inputBox,
        isSuccess && styles.inputSuccess,
        isTextArea && styles.textAreaBox,
        props.editable === false && styles.inputDisabled // Visual cue for disabled state
      ]}>
        {iconName && (
          <HOCIcons.FontAwesome5
            name={iconName}
            size={normalize(12)}
            color={props.editable === false ? "#CBD5E1" : "#94A3B8"}
          />
        )}

        <TextInput
          style={[
            styles.input,
            isTextArea && styles.textArea,
            isSuccess && { fontWeight: '600', color: '#15803d' },
            props.editable === false && { color: '#64748B' }, // Grey text if read-only
            inputStyle,
          ]}
          value={value}
          onChangeText={onChangeText}
          placeholder={placeholder}
          placeholderTextColor="#94A3B8"
          {...props}
        />

        {rightElement}
      </View>
    </View>
  );
};

// --- MAIN COMPONENT ---
const ReservationModal = ({ visible, onClose, onSubmit, selectedBags = [], initialData = null }) => {
  // --- Form State ---
  const [patientId, setPatientId] = useState('');
  const [patientDetails, setPatientDetails] = useState('');
  const [wardNumber, setWardNumber] = useState('');
  const [age, setAge] = useState('');
  const [sex, setSex] = useState('');
  const [duration, setDuration] = useState('60');
  const [notes, setNotes] = useState('');

  // --- UI State ---
  const [isSearching, setIsSearching] = useState(false);

  useEffect(() => {
    if (visible) {
      if (initialData) {
        // --- AUTO-FILL MODE (From Request) ---
        setPatientId(initialData.patientId || '');
        setPatientDetails(initialData.patientName || '');
        setWardNumber(initialData.ward || '');
        setAge(initialData.age || '');
        setSex(initialData.sex || '');
        // Auto-add note linking to the Request ID
        setNotes(`Fulfilling Request ID: ${initialData.reqId || 'N/A'}`);
      } else {
        // --- MANUAL MODE ---
        resetForm();
      }
    }
  }, [visible, initialData]);

  const resetForm = () => {
    setPatientId('');
    setPatientDetails('');
    setWardNumber('');
    setAge('');
    setSex('');
    setDuration('60');
    setNotes('');
    setIsSearching(false);
  };

  const handlePatientSearch = () => {
    if (!patientId.trim()) return;
    setIsSearching(true);
    Keyboard.dismiss();

    setTimeout(() => {
      const id = patientId.trim().toUpperCase();
      const match = MOCK_PATIENT_DB[id];
      if (match) {
        setPatientDetails(match.name);
        setWardNumber(match.ward || '');
        setAge(match.age || '');
        setSex(match.sex || '');
      } else {
        Alert.alert('Not Found', `No patient found with ID: ${id}`);
      }
      setIsSearching(false);
    }, 600);
  };

  const handleSubmit = () => {
    if (!patientId.trim()) {
      Alert.alert('Required', 'Patient ID is missing.');
      return;
    }
    const reservationData = {
      patientId,
      patientName: patientDetails,
      wardNumber,
      age,
      sex,
      duration,
      notes,
      totalBags: selectedBags.length,
      bagNumbers: selectedBags.map(b => b.donationid),
      timestamp: new Date().toISOString(),
      // Link the reservation to the request if it exists
      linkedRequestId: initialData ? initialData.reqId : null
    };
    onSubmit(reservationData);
  };

  return (
    <Modal
      animationType="slide"
      transparent={true}
      visible={visible}
      onRequestClose={onClose}
      statusBarTranslucent={true}
    >
      <View style={styles.overlay}>
        <TouchableOpacity
          style={styles.backdropTouchable}
          activeOpacity={1}
          onPress={onClose}
        >
          <View />
        </TouchableOpacity>

        <KeyboardAvoidingView
          behavior={Platform.OS === 'ios' ? 'padding' : undefined}
          style={styles.keyboardView}
        >
          <View style={styles.modalContainer}>

            {/* --- HEADER --- */}
            <View style={styles.header}>
              <View>
                {/* Dynamic Title based on Context */}
                <Text style={styles.headerTitle}>
                  {initialData ? 'Process Request' : 'New Reservation'}
                </Text>
                <Text style={styles.headerSubtitle}>
                  {initialData ? `Fulfilling Request #${initialData.reqId}` : 'Assign units to patient'}
                </Text>
              </View>
            </View>

            <ScrollView
              style={styles.scrollContainer}
              contentContainerStyle={styles.scrollContent}
              showsVerticalScrollIndicator={false}
              keyboardShouldPersistTaps="handled"
              removeClippedSubviews={false}
            >

              <View style={styles.sectionHeaderRow}>
                <Text style={styles.sectionTitle}>PATIENT DETAILS</Text>
              </View>

              {/* ID & Duration Row */}
              <View style={styles.row}>
                <View style={{ flex: 1.5, marginRight: 10 }}>
                  <FocusableInput
                    label="Patient ID"
                    required
                    iconName="id-badge"
                    value={patientId}
                    onChangeText={setPatientId}
                    placeholder="Scan/Type ID"
                    returnKeyType="search"
                    onSubmitEditing={handlePatientSearch}
                    autoCorrect={false}
                    editable={!initialData} // Lock if auto-filled
                    rightElement={!initialData && (
                      <TouchableOpacity onPress={handlePatientSearch} style={styles.searchBtn}>
                        {isSearching ? (
                          <ActivityIndicator size="small" color={Global.AppTheme.primary_color} />
                        ) : (
                          <HOCIcons.FontAwesome5 name="search" size={normalize(12)} color={Global.AppTheme.primary_color} />
                        )}
                      </TouchableOpacity>
                    )}
                  />
                </View>

                <View style={{ flex: 1 }}>
                  <FocusableInput
                    label="Duration (Min)"
                    value={duration}
                    onChangeText={setDuration}
                    placeholder="60"
                    keyboardType="numeric"
                    inputStyle={{ textAlign: 'center' }}
                  />
                </View>
              </View>

              {/* Name */}
              <FocusableInput
                label="Patient Name"
                iconName="user"
                value={patientDetails}
                onChangeText={setPatientDetails}
                placeholder="Auto-filled from search"
                isSuccess={!!patientDetails}
                editable={!initialData} // Lock if auto-filled
                containerStyle={{ marginTop: 0 }}
              />

              {/* Ward & Age/Sex Row */}
              <View style={[styles.row, { marginTop: 12 }]}>
                <View style={{ flex: 2, marginRight: 10 }}>
                  <FocusableInput
                    label="Ward / Location"
                    value={wardNumber}
                    onChangeText={setWardNumber}
                    placeholder="e.g. ICU-02"
                    editable={!initialData} // Lock if auto-filled
                  />
                </View>
                <View style={{ flex: 1.5 }}>
                  <Text style={styles.label}>Age / Sex</Text>
                  <View style={[styles.inputBox, { paddingHorizontal: 0 }, initialData && styles.inputDisabled]}>
                    <TextInput
                      style={[styles.input, { textAlign: 'center' }, initialData && { color: '#64748B' }]}
                      value={age}
                      onChangeText={setAge}
                      placeholder="Age"
                      placeholderTextColor="#94A3B8"
                      keyboardType="numeric"
                      editable={!initialData}
                    />
                    <View style={styles.verticalLine} />
                    <TextInput
                      style={[styles.input, { textAlign: 'center' }, initialData && { color: '#64748B' }]}
                      value={sex}
                      onChangeText={setSex}
                      placeholder="Sex"
                      placeholderTextColor="#94A3B8"
                      editable={!initialData}
                    />
                  </View>
                </View>
              </View>

              {/* Notes */}
              <FocusableInput
                label="Notes"
                value={notes}
                onChangeText={setNotes}
                placeholder="Add clinical notes (optional)..."
                isTextArea={true}
                multiline={true}
                textAlignVertical="top"
                containerStyle={{ marginTop: 12 }}
              />

              {/* --- UNITS SECTION --- */}
              <View style={[styles.sectionHeaderRow, { marginTop: 20 }]}>
                <Text style={styles.sectionTitle}>
                  {initialData ? 'MATCHED UNIT' : `SELECTED UNITS (${selectedBags.length})`}
                </Text>
              </View>

              <View style={{ gap: 8 }}>
                {selectedBags.map((bag, index) => (
                  <View key={`${bag.donationid}_${index}`}>
                    <BagCard
                      data={bag}
                      selectedBags={[]}
                      isMultiSelectMode={false}
                      onActionPress={() => { }}
                    />
                  </View>
                ))}
              </View>

            </ScrollView>

            {/* --- FOOTER --- */}
            <View style={styles.footer}>
              <TouchableOpacity style={styles.cancelBtn} onPress={onClose}>
                <Text style={styles.cancelText}>Cancel</Text>
              </TouchableOpacity>
              <TouchableOpacity style={styles.confirmBtn} onPress={handleSubmit}>
                <Text style={styles.confirmText}>
                  {initialData ? 'Confirm & Process' : 'Confirm Reservation'}
                </Text>
                <HOCIcons.FontAwesome5 name={initialData ? "check-circle" : "arrow-right"} size={normalize(12)} color="#FFF" />
              </TouchableOpacity>
            </View>

          </View>
        </KeyboardAvoidingView>
      </View>
    </Modal>
  );
};

const styles = StyleSheet.create({
  // Overlay
  overlay: {
    flex: 1,
    backgroundColor: 'transparent',
  },
  backdropTouchable: {
    position: 'absolute',
    top: 0, left: 0, right: 0, bottom: 0,
    zIndex: 0,
  },
  keyboardView: {
    flex: 1,
    justifyContent: 'flex-end',
    zIndex: 1,
  },
  modalContainer: {
    backgroundColor: '#FFFFFF',
    width: '100%',
    maxHeight: '89%',
    shadowColor: "#000",
    shadowOffset: { width: 0, height: -5 },
    shadowOpacity: 0.1,
    shadowRadius: 10,
    elevation: 20,
    overflow: 'hidden'
  },

  // Header
  header: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: normalize(15),
    borderBottomWidth: 1,
    borderBottomColor: '#F1F5F9',
  },
  headerTitle: {
    fontSize: normalize(16),
    fontWeight: '800',
    color: Global.AppTheme.heading_text_color,
    letterSpacing: -0.5,
  },
  headerSubtitle: {
    fontSize: normalize(11),
    color: '#64748B',
    marginTop: 2,
  },

  // Scroll Content
  scrollContainer: {
    flexGrow: 0,
  },
  scrollContent: {
    padding: normalize(15),
    paddingBottom: normalize(6),
  },
  sectionHeaderRow: {
    marginBottom: 4,
  },
  sectionTitle: {
    fontSize: normalize(10),
    fontWeight: '700',
    color: '#94A3B8',
    letterSpacing: 1.2,
    marginBottom: 1,
  },

  // Form Styles
  row: {
    flexDirection: 'row',
  },
  fieldContainer: {
    marginBottom: 7
  },
  label: {
    fontSize: normalize(11),
    fontWeight: '600',
    color: '#334155',
    marginBottom: 3,
  },
  inputBox: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: '#F8FAFC',
    borderRadius: 12,
    height: normalize(38),
    paddingHorizontal: 12,
    borderWidth: 1,
    borderColor: Global.AppTheme.primary_color
  },
  // New style for read-only fields
  inputDisabled: {
    backgroundColor: '#F1F5F9',
    borderColor: '#E2E8F0',
  },
  inputSuccess: {
    backgroundColor: '#F0FDF4',
    borderColor: '#bbf7d0',
  },
  input: {
    flex: 1,
    fontSize: normalize(13),
    color: '#1E293B',
    height: '100%',
    marginLeft: 8,
    padding: 0,
  },
  searchBtn: {
    padding: 8,
  },
  verticalLine: {
    width: 1,
    height: '50%',
    backgroundColor: '#E2E8F0',
    marginHorizontal: 5,
  },
  textAreaBox: {
    height: normalize(80),
    alignItems: 'flex-start',
    paddingVertical: 10,
  },
  textArea: {
    textAlignVertical: 'top',
    marginLeft: 0,
  },

  // Footer
  footer: {
    flexDirection: 'row',
    padding: normalize(10),
    borderTopWidth: 1,
    borderTopColor: '#F1F5F9',
    gap: 12,
  },
  cancelBtn: {
    flex: 1,
    height: normalize(48),
    justifyContent: 'center',
    alignItems: 'center',
    borderRadius: 12,
    backgroundColor: '#FFF',
    borderWidth: 1,
    borderColor: '#E2E8F0',
  },
  cancelText: {
    color: '#64748B',
    fontWeight: '600',
    fontSize: normalize(12),
  },
  confirmBtn: {
    flex: 1,
    height: normalize(48),
    flexDirection: 'row',
    justifyContent: 'center',
    alignItems: 'center',
    borderRadius: 12,
    backgroundColor: Global.AppTheme.primary_color || '#0F172A',
    gap: 8,
    shadowColor: Global.AppTheme.primary_color,
    shadowOpacity: 0.3,
    shadowOffset: { width: 0, height: 4 },
    shadowRadius: 8,
    elevation: 4,
  },
  confirmText: {
    color: '#FFF',
    fontWeight: '700',
    fontSize: normalize(12),
  },
});

export default ReservationModal;