import React, { useState, useEffect } from 'react';
import { View, TouchableOpacity, Platform, Dimensions, Text, StyleSheet, Modal } from 'react-native';
import DateTimePicker from '@react-native-community/datetimepicker';
import moment from 'moment';
import { isNU, isNUQ } from '../CommonStyle/ComponentFunctions';
import HOCIcons from '../HOC/HOCIcons';

export default function CDatePickerAndroid(props) {

    const [data, setData] = useState(props.data != undefined ? props.data : {})
    const [date, setDate] = useState(props.passingDate != undefined ? new Date(props.passingDate) : null);
    const [tempDate, setTempDate] = useState(new Date()); // Temp date for iOS scrolling
    const [mode, setMode] = useState('date');
    const [show, setShow] = useState(false);

    // Sync local state when the parent component (API data) updates the date
    useEffect(() => {
        if (props.passingDate) {
            const newDate = new Date(props.passingDate);
            // Guard against unnecessary updates if time value hasn't changed
            if (!date || newDate.getTime() !== date.getTime()) {
                setDate(newDate);
            }
        }
    }, [props.passingDate]);

    const onChange = (event, selectedDate) => {
        // ANDROID: DatePicker closes automatically
        // iOS: We handle closing manually in the Modal
        if (Platform.OS === 'android') {
            setShow(false);
            if (props.onPickerToggle) props.onPickerToggle(false);
        }

        if (event.type === "set" || selectedDate) {
            const currentDate = selectedDate || date;

            if (Platform.OS === 'ios') {
                // On iOS, just update temp state, don't commit yet
                setTempDate(currentDate);
            } else {
                // On Android, commit immediately
                setDate(currentDate);
                setData({ ...data, ['value']: currentDate });
                props.onChangeData(currentDate);
            }
        } else if (event.type === "dismissed") {
            // Android dismissed
        }
    };

    const confirmIOSDate = () => {
        setDate(tempDate);
        setData({ ...data, ['value']: tempDate });
        props.onChangeData(tempDate);
        setShow(false);
        if (props.onPickerToggle) props.onPickerToggle(false);
    };

    const cancelIOSDate = () => {
        setShow(false);
        if (props.onPickerToggle) props.onPickerToggle(false);
    };

    const showMode = (currentMode) => {
        if (!props.disabled) {
            if (Platform.OS === 'ios') {
                // Initialize temp date when opening
                setTempDate(date || new Date());
            }
            setShow(true);
            setMode(currentMode);
            // Notify parent that picker is now shown
            if (props.onPickerToggle) {
                props.onPickerToggle(true);
            }
        }
    };

    const showDatepicker = () => {
        showMode('date');
    };

    // --- Floating Label Style ---
    const labelStyle = {
        position: 'absolute',
        left: 10,
        top: -10,
        backgroundColor: '#fff',
        paddingHorizontal: 6,
        zIndex: 10,
        fontSize: 11,
        color: props.disabled ? '#adb2b7' : '#094485',
        fontWeight: props.disabled ? '400' : '500',
    };

    return (
        <View style={[{ overflow: 'visible' }, props.label ? { marginTop: 10 } : {}]}>
            <TouchableOpacity
                disabled={props.disabled ? true : false}
                onPress={() => showDatepicker()}
                style={[props.pickerstyle, { overflow: 'visible' }]}
            >
                {/* --- RENDER FLOATING LABEL --- */}
                {props.label && (
                    <Text style={labelStyle}>
                        {props.label}
                        {props.isRequired && <Text style={{ color: '#dc3545' }}> *</Text>}
                    </Text>
                )}

                <View style={[props.positionviewstyle, { flex: 1 }]}>
                    <Text style={props.positiontextstyle}>
                        {date
                            ? moment(date).format('DD/MM/YYYY')
                            : (props.placeholder || '')}
                    </Text>
                </View>

                <HOCIcons.Icons
                    icongroup={props.icon.icongroup}
                    name={props.icon.name}
                    size={props.icon.size}
                    color={props.icon.color}
                    style={props.icon.style}
                />

            </TouchableOpacity>

            {/* ANDROID Date Picker (Default Behavior) */}
            {show && Platform.OS === 'android' && (
                <DateTimePicker
                    minimumDate={isNU(props.minimumdate) ? new Date(props.minimumdate) : null}
                    maximumDate={isNU(props.maximumdate) ? new Date(props.maximumdate) : null}
                    testID={"dateTimePicker"}
                    value={isNUQ(date) ? date : new Date()}
                    mode={'date'}
                    is24Hour={true}
                    display="default"
                    onChange={onChange}
                />
            )}

            {/* iOS Date Picker - MODAL WRAPPER */}
            {show && Platform.OS === 'ios' && (
                <Modal
                    visible={show}
                    transparent={true}
                    animationType="fade"
                    onRequestClose={cancelIOSDate}
                >
                    <TouchableOpacity
                        style={styles.modalOverlay}
                        activeOpacity={1}
                        onPress={cancelIOSDate}
                    >
                        <View style={styles.iosPickerContainer}>
                            {/* Toolbar */}
                            <View style={styles.iosToolbar}>
                                <TouchableOpacity onPress={cancelIOSDate} style={styles.toolbarButton}>
                                    <Text style={styles.cancelText}>Cancel</Text>
                                </TouchableOpacity>
                                <Text style={styles.toolbarTitle}>{props.label || 'Select Date'}</Text>
                                <TouchableOpacity onPress={confirmIOSDate} style={styles.toolbarButton}>
                                    <Text style={styles.confirmText}>Confirm</Text>
                                </TouchableOpacity>
                            </View>

                            {/* Spinner DatePicker */}
                            <View style={styles.pickerWrapper}>
                                <DateTimePicker
                                    minimumDate={isNU(props.minimumdate) ? new Date(props.minimumdate) : null}
                                    maximumDate={isNU(props.maximumdate) ? new Date(props.maximumdate) : null}
                                    testID={"dateTimePickerIOS"}
                                    value={tempDate}
                                    mode={'date'}
                                    is24Hour={true}
                                    display="spinner"
                                    onChange={onChange}
                                    textColor="#000000"
                                    themeVariant="light"
                                    style={{ width: Dimensions.get('window').width, height: 200 }}
                                />
                            </View>
                        </View>
                    </TouchableOpacity>
                </Modal>
            )}

            {/* Web Shim for Date Picker - Modal Portal - PRETTY VERSION */}
            {Platform.OS === 'web' && show && (
                <Modal
                    visible={true}
                    transparent={true}
                    animationType="fade"
                    onRequestClose={() => setShow(false)}
                >
                    <TouchableOpacity
                        style={{
                            flex: 1,
                            backgroundColor: 'rgba(0,0,0,0.4)', // Slightly lighter backdrop
                            justifyContent: 'center',
                            alignItems: 'center',
                            backdropFilter: 'blur(2px)', // Adds a nice blur effect on web
                        }}
                        activeOpacity={1}
                        onPress={() => setShow(false)}
                    >
                        <TouchableOpacity
                            activeOpacity={1}
                            onPress={(e) => e.stopPropagation()}
                            style={{
                                backgroundColor: 'white',
                                borderRadius: 16, // Softer corners
                                width: '90%',
                                maxWidth: 380,
                                elevation: 10,
                                shadowColor: '#000',
                                shadowOffset: { width: 0, height: 10 },
                                shadowOpacity: 0.15,
                                shadowRadius: 24,
                                overflow: 'hidden', // Ensures header color doesn't bleed
                            }}
                        >
                            {/* Modal Header */}
                            <View style={{
                                backgroundColor: '#094485',
                                paddingVertical: 18,
                                paddingHorizontal: 20,
                                alignItems: 'center',
                            }}>
                                <Text style={{
                                    fontSize: 18,
                                    fontWeight: '600',
                                    color: 'white',
                                    letterSpacing: 0.5
                                }}>
                                    {props.label || "Select Date"}
                                </Text>
                            </View>

                            {/* Modal Body */}
                            <View style={{ padding: 24 }}>
                                <Text style={{
                                    fontSize: 14,
                                    color: '#64748b',
                                    marginBottom: 8,
                                    fontWeight: '500'
                                }}>
                                    Date
                                </Text>

                                {React.createElement('input', {
                                    type: 'date',
                                    value: isNUQ(date) ? moment(date).format('YYYY-MM-DD') : '',
                                    min: isNU(props.minimumdate) ? moment(props.minimumdate).format('YYYY-MM-DD') : undefined,
                                    max: isNU(props.maximumdate) ? moment(props.maximumdate).format('YYYY-MM-DD') : undefined,
                                    onChange: (e) => {
                                        const val = e.target.value;
                                        if (val) {
                                            const parts = val.split('-');
                                            // Create date as local time 00:00:00
                                            const localDate = new Date(parts[0], parts[1] - 1, parts[2]);
                                            onChange({ type: 'set' }, localDate);
                                        }
                                    },
                                    style: {
                                        padding: '12px 16px',
                                        fontSize: '17px',
                                        border: '1px solid #cbd5e1',
                                        borderRadius: '8px',
                                        width: '100%',
                                        marginBottom: '24px',
                                        color: '#334155',
                                        boxSizing: 'border-box',
                                        backgroundColor: '#f8fafc',
                                        outline: 'none',
                                        transition: 'border-color 0.2s',
                                        cursor: 'pointer'
                                    }
                                })}

                                {/* Buttons Row */}
                                <View style={{ flexDirection: 'row', gap: 12 }}>
                                    <TouchableOpacity
                                        onPress={() => setShow(false)}
                                        style={{
                                            flex: 1,
                                            paddingVertical: 12,
                                            borderRadius: 8,
                                            alignItems: 'center',
                                            borderWidth: 1,
                                            borderColor: '#e2e8f0',
                                            backgroundColor: 'white'
                                        }}
                                    >
                                        <Text style={{ color: '#64748b', fontWeight: '600', fontSize: 15 }}>Cancel</Text>
                                    </TouchableOpacity>

                                    <TouchableOpacity
                                        onPress={() => setShow(false)}
                                        style={{
                                            flex: 1,
                                            backgroundColor: '#094485',
                                            paddingVertical: 12,
                                            borderRadius: 8,
                                            alignItems: 'center',
                                            shadowColor: '#094485',
                                            shadowOffset: { width: 0, height: 4 },
                                            shadowOpacity: 0.2,
                                            shadowRadius: 8,
                                        }}
                                    >
                                        <Text style={{ color: 'white', fontWeight: '600', fontSize: 15 }}>Confirm</Text>
                                    </TouchableOpacity>
                                </View>
                            </View>
                        </TouchableOpacity>
                    </TouchableOpacity>
                </Modal>
            )}
        </View>
    );
};

const styles = StyleSheet.create({
    modalOverlay: {
        flex: 1,
        justifyContent: 'flex-end',
        backgroundColor: 'rgba(0, 0, 0, 0.4)',
    },
    iosPickerContainer: {
        backgroundColor: 'white',
        borderTopLeftRadius: 20,
        borderTopRightRadius: 20,
        paddingBottom: 20, // Safe area buffer
        elevation: 5,
        shadowColor: '#000',
        shadowOffset: { width: 0, height: -2 },
        shadowOpacity: 0.1,
        shadowRadius: 4,
    },
    iosToolbar: {
        flexDirection: 'row',
        justifyContent: 'space-between',
        alignItems: 'center',
        paddingHorizontal: 16,
        paddingVertical: 12,
        borderBottomWidth: 1,
        borderBottomColor: '#f3f4f6',
        backgroundColor: '#f9fafb',
        borderTopLeftRadius: 20,
        borderTopRightRadius: 20,
    },
    toolbarButton: {
        padding: 5,
    },
    cancelText: {
        color: '#64748b',
        fontSize: 16,
        fontWeight: '500',
    },
    confirmText: {
        color: '#094485',
        fontSize: 16,
        fontWeight: '600',
    },
    toolbarTitle: {
        color: '#1e293b',
        fontSize: 16,
        fontWeight: '600',
    },
    pickerWrapper: {
        backgroundColor: 'white',
        alignItems: 'center',
        justifyContent: 'center',
    }
});