import React, { useState, useEffect } from 'react';
import { Global } from '../Common/Global';
import { isBNU } from '../CommonStyle/ComponentFunctions';

export default function HReportFooter(props) {
  const username = (props && props.printedby) ? props.printedby : (Global?.userData?.username || 'User');
  const printDateTime = (props && props.printdatetime) ? props.printdatetime : new Date().toLocaleString('en-IN', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: true
  });

  const pageInfo = (props && props.pageText) ? props.pageText : '';

  return (`
    <div style="display: flex; justify-content: space-between; align-items: center; padding: 1px 3px; margin: 0; font-size: 9px; color: #666; border-top: 1px solid #ddd;">
      <span>Printed by: <b>${username}</b> | ${printDateTime}</span>
      <span>${pageInfo}</span>
    </div>
    <img src="${Global.headerfooter[1]}" style="height: 80px; width: 100%; display: block; margin: 0; padding: 0;" />
  `)
}



