import React from 'react';
import {
  View,
  TouchableOpacity,
  Text,
  StyleSheet,
  Dimensions,
  Platform,
} from 'react-native';
import { useLanguage } from '../context/LanguageContext';
import { CButtonShadow } from '../CommonStyle/ComponentFunctions';
import { normalize } from '../CommonStyle/componentStyle';

const { width: SCREEN_WIDTH } = Dimensions.get('window');

const LanguageToggle = () => {
  const { changeLanguage, isEnglish } = useLanguage();

  return (
    <View style={styles.wrapper}>
      <View style={styles.container} accessible accessibilityRole="tablist">
        {/* English */}
        <TouchableOpacity
          onPress={() => changeLanguage('en')}
          activeOpacity={0.85}
          style={[
            styles.option,
            styles.leftOption,
            isEnglish ? styles.activeOption : styles.inactiveOption,
          ]}
          accessibilityRole="tab"
          accessibilityState={{ selected: isEnglish }}
          accessibilityLabel="English language"
          hitSlop={{ top: 6, bottom: 6, left: 6, right: 6 }}
        >
          <Text
            style={[styles.text, isEnglish ? styles.textActive : styles.textInactive]}
            numberOfLines={1}
            ellipsizeMode="tail"
            allowFontScaling
          >
            English
          </Text>
        </TouchableOpacity>

        {/* Separator */}
        <View pointerEvents="none" style={styles.separator} />

        {/* Malayalam */}
        <TouchableOpacity
          onPress={() => changeLanguage('ml')}
          activeOpacity={0.85}
          style={[
            styles.option,
            styles.rightOption,
            !isEnglish ? styles.activeOption : styles.inactiveOption,
          ]}
          accessibilityRole="tab"
          accessibilityState={{ selected: !isEnglish }}
          accessibilityLabel="Malayalam language"
          hitSlop={{ top: 6, bottom: 6, left: 6, right: 6 }}
        >
          <Text
            style={[styles.text, !isEnglish ? styles.textActive : styles.textInactive]}
            numberOfLines={1}
            ellipsizeMode="tail"
            allowFontScaling
          >
            മലയാളം
          </Text>
        </TouchableOpacity>
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  wrapper: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  container: {
    flexDirection: 'row',
    width: SCREEN_WIDTH * 0.45, // responsive
    maxWidth: normalize(115),
    height: normalize(24),
    borderRadius: 15,
    borderWidth: 1.5,
    borderColor: '#CBD5E1',
    overflow: 'hidden',
    // ...CButtonShadow(),
  },
  option: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
  },
  leftOption: {
    borderTopLeftRadius: 15,
    borderBottomLeftRadius: 15,
  },
  rightOption: {
    borderTopRightRadius: 15,
    borderBottomRightRadius: 15,
    paddingLeft: normalize(5)
  },

  /* Active / Inactive backgrounds:
     - active: subtle bluish
     - inactive: slightly different (so you can clearly see the selected side)
  */
  activeOption: {
    // backgroundColor: '#D6E9FF', // slightly darker than #E6F2FF if you want


  },
  inactiveOption: {
    backgroundColor: '#EAF6FF', // very light blue/white tint (distinct but subtle)
  },

  separator: {
    width: 1,
    alignSelf: 'center',
    height: '60%', // vertical centering relative to container
    backgroundColor: '#CBD5E1', // matches border
  },

  text: {
    fontSize: 14,
    fontWeight: '600',
    letterSpacing: 0.3,
    textAlign: 'center',
    flexShrink: 1,
  },
  textActive: {
    color: '#1E3A8A',
  },
  textInactive: {
    color: '#9CA3AF',
  },
});

export default LanguageToggle;
