// src/Handlers/ContextBio.js
import React, {useContext, useState} from 'react';

const ContextBio = React.createContext({
  // Default empty context
});

// Exporting Context Provider
export const ContextBioProvider = ({children}) => {
  const [responseJSON, setResponseJSON] = useState({});
  const [updateData, setUpdateData] = useState(false);
  const [verifyData, setVerifyData] = useState(false);
  const [searchSelect, setSearchSelect] = useState(0);
  const [invoiceData, setInvoiceData] = useState({data: [], EditStatus: false});
  
  // ✅ FIX: Change from array [] to object {}
  const [dynamicReportOperators, setDynamicReportOperators] = useState({});
  
  const [dateOperators, setDateOperators] = useState([]);
  const [textOperators, setTextOperators] = useState([]);
  const [filteredData, setFilteredData] = useState([]);
  const [patientData, setPatientData] = useState([]);
  const [patients, setPatients] = useState([]);
  const [dashData, setDashData] = useState();

  return (
    <ContextBio.Provider
      value={{
        responseJSON,
        setResponseJSON,
        updateData,
        setUpdateData,
        verifyData,
        setVerifyData,
        searchSelect,
        setSearchSelect,
        invoiceData,
        setInvoiceData,
        dynamicReportOperators,
        setDynamicReportOperators,
        dateOperators,
        setDateOperators,
        textOperators,
        setTextOperators,
        filteredData,
        setFilteredData,
        dashData,
        setDashData,
        patientData,
        setPatientData,
        patients,
        setPatients,
      }}>
      {children}
    </ContextBio.Provider>
  );
};

// Custom Hook for Using Context (Optional)
export const useDataContext = () => {
  return useContext(ContextBio);
};

export default ContextBio;