import React, { useState, useEffect } from 'react';
import {
  Text,
  View,
  Dimensions,
  TouchableOpacity,
  StyleSheet,
} from 'react-native';
import Overlay from 'react-native-modal-overlay';
import HOCIcons from '../HOC/HOCIcons';
import { Global } from '../Common/Global';
import { APIURL } from '../Common/apiConstants';
import NetworkServiceCall from '../Common/NetworkServiceCall';
import { normalize, notifyMessage } from '../CommonStyle/ComponentFunctions';
import { Loader as LoaderLocal } from '../CommonStyle/ComponentFunctions';
import CInfoCard from './Cinfocard';

export default function DetailsOverlay(props) {
  const blockData = props.blockData;
  const [isLoading, setIsLoading] = useState(false);
  const [apiData, setApiData] = useState(null);

  useEffect(() => {
    // Use patientno from profilecontent as the primary ID, fallback to hopapatient
    const donorId = blockData?.item?.profilecontent?.[0]?.patientno || blockData?.item?.hopapatient;
    if (donorId) {
      fetchDonorDetails(donorId);
    }
  }, [blockData]);

  const fetchDonorDetails = async (donorId) => {
    try {
      setIsLoading(true);
      const apiUrl = `${APIURL}bldget/invcommonget/bbsupatientdetails "${donorId}"`;
      console.log("🔗 Fetching donor details:", apiUrl);

      const response = await NetworkServiceCall('get', apiUrl, '');
      console.log("📥 Donor details response:", JSON.stringify(response));

      if (response.httpstatus === 200 && response.data) {
        setApiData(response.data);
      } else {
        setApiData(null);
      }
    } catch (error) {
      console.error("Error fetching donor details:", error);
      notifyMessage("Failed to fetch donor details", 3);
    } finally {
      setIsLoading(false);
    }
  };

  function getOverlayChildrenWrapperStyle() {
    return {
      position: 'absolute',
      bottom: 0,
      borderTopLeftRadius: 20,
      borderTopRightRadius: 20,
      backgroundColor: '#fff',
      alignSelf: 'center',
      width: Dimensions.get('window').width,
      height: Dimensions.get('window').height * 0.85,
      padding: 0,
      paddingTop: 10,
    };
  }

  const displayData = blockData?.item;
  const profile = displayData?.profilecontent?.[0];

  return (
    <Overlay
      visible={true}
      onClose={() => props.closeOverlay()}
      closeOnTouchOutside={true}
      containerStyle={{ backgroundColor: 'rgba(0, 0, 0, 0.6)' }}
      childrenWrapperStyle={getOverlayChildrenWrapperStyle()}
      animationType="slideInUp"
      easing="ease-in-out"
    >
      <View style={{ width: '100%', flex: 1 }}>

        {/* Modern Header / Drag Handle Area */}
        <View style={styles.headerContainer}>
          <View style={styles.dragHandle} />

          <View style={styles.headerTitleRow}>
            <View style={styles.titleWrapper}>
              <HOCIcons.MaterialCommunityIcons name="account-details" size={24} color={Global.AppTheme.primary_color} />
              <Text style={styles.headerTitle}>Donor Details</Text>
            </View>

            <TouchableOpacity onPress={() => props.closeOverlay()} style={styles.closeButton}>
              <HOCIcons.Ionicons name="close" size={24} color="#555" />
            </TouchableOpacity>
          </View>
        </View>

        {/* Content */}
        <View style={{ flex: 1 }}>
          {isLoading && !profile ? (
            <View style={{ justifyContent: 'center', alignItems: 'center', flex: 1 }}>
              <LoaderLocal />
            </View>
          ) : (isLoading || profile) ? (
            // Even if loading, if we have profile data, show it immediately (optimistic UI)
            <CInfoCard
              profile={profile}
              displayData={displayData}
              apiData={apiData}
              showImage={true}
              cardStyle={{ marginHorizontal: 0, borderRadius: 0, borderWidth: 0 }} // Flat look inside sheet
            />
          ) : (
            <Text style={{ textAlign: 'center', marginTop: 20, color: '#888' }}>No details found</Text>
          )}
        </View>
      </View>
    </Overlay>
  );
}

const styles = StyleSheet.create({
  headerContainer: {
    width: '100%',
    backgroundColor: '#f8f9fa',
    paddingBottom: 10,
    borderTopLeftRadius: 20,
    borderTopRightRadius: 20,
  },
  dragHandle: {
    width: 40,
    height: 5,
    borderRadius: 3,
    backgroundColor: '#ccc',
    alignSelf: 'center',
    marginBottom: 10,
  },
  headerTitleRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    paddingHorizontal: 20,
  },
  titleWrapper: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  headerTitle: {
    fontSize: 18,
    fontWeight: 'bold',
    color: '#333',
    marginLeft: 10,
  },
  closeButton: {
    padding: 5,
    backgroundColor: '#eee',
    borderRadius: 20,
  },
});
