import React, { useState, useCallback } from 'react';
import { View, TextInput, StyleSheet, Text, Platform } from 'react-native';
import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
import { normalize } from '../CommonStyle/ComponentFunctions';

const CustomTextInput = ({
  inputRef,
  style,
  placeholder,
  placeholderTextColor = 'gray',
  value = '',
  onChangeText,
  onSubmitEditing,
  keyboardType = 'default',
  secureTextEntry = false,
  editable = true,
  autoCapitalize = 'none',
  iconName,
  iconColor = '#094485',
  iconSize = 16,
  isLocked = false,
  fetchedFields = [],
  fieldName = '',
  label,
  isRequired = false,
  ...rest
}) => {
  const [isFocused, setIsFocused] = useState(false);

  const isFieldLocked = isLocked || fetchedFields.includes(fieldName);

  const handleChangeText = useCallback(
    (text) => {
      if (!onChangeText || isFieldLocked) return;
      let processedText = text;
      if (keyboardType === 'phone-pad') {
        processedText = text.replace(/\D/g, '').slice(0, 10);
      }
      onChangeText(processedText);
    },
    [keyboardType, onChangeText, isFieldLocked]
  );

  const labelStyle = {
    position: 'absolute',
    left: iconName ? normalize(10) : normalize(10), // Adjusted left position
    top: normalize(-5), // Adjusted top position to sit on the border
    backgroundColor: '#fff',
    paddingHorizontal: 4,
    zIndex: 10,
    fontSize: normalize(9.1), // Slightly smaller font
    color: isFieldLocked ? '#adb2b7' : (isFocused ? '#094485' : '#094485'),
    fontWeight: isFocused ? '600' : '400',
  };

  return (
    <View
      style={[
        styles.container,
        isFocused && !isFieldLocked && styles.focusedContainer,
        isFieldLocked && styles.lockedContainer,
        label ? { marginTop: 12 } : {},
        style,
        // Adjust height for multiline
        rest.multiline ? { height: 'auto', minHeight: 45, paddingTop: 10, paddingBottom: 10 } : {}
      ]}
    >
      {label && (
        <Text style={labelStyle}>
          {label}
          {isRequired && <Text style={{ color: '#dc3545' }}> *</Text>}
        </Text>
      )}

      {iconName && (
        <FontAwesome5
          name={iconName}
          size={iconSize}
          color={isFieldLocked ? '#6c757d' : iconColor}
          style={[styles.icon, rest.multiline && { alignSelf: 'flex-start', marginTop: 4 }]}
        />
      )}

      <TextInput
        ref={inputRef}
        placeholder={placeholder}
        placeholderTextColor={isFieldLocked ? '#adb2b7' : placeholderTextColor}
        value={value}
        onChangeText={handleChangeText}
        onSubmitEditing={onSubmitEditing}
        keyboardType={keyboardType}
        secureTextEntry={secureTextEntry}
        editable={!isFieldLocked}
        autoCapitalize={autoCapitalize}
        onFocus={(e) => {
          setIsFocused(true);
          if (rest.onFocus) rest.onFocus(e);
        }}
        onBlur={(e) => {
          setIsFocused(false);
          if (rest.onBlur) rest.onBlur(e);
        }}
        maxLength={keyboardType === 'phone-pad' ? 10 : undefined}
        blurOnSubmit={false}
        importantForAutofill="no"
        autoComplete="off"
        textAlignVertical="center"
        includeFontPadding={false}
        allowFontScaling={false}
        {...rest}
        style={[
          styles.input,
          isFieldLocked && styles.lockedInput,
          rest.multiline && { textAlignVertical: 'top' },
          Platform.OS === 'web' && { outlineStyle: 'none' }
        ]}
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flexDirection: 'row',
    alignItems: 'center',
    borderColor: '#ccc',
    borderWidth: 0.8,
    borderRadius: normalize(8),
    paddingHorizontal: normalize(10),
    backgroundColor: '#fff',
    height: normalize(28), // <--- CHANGED: Increased from 34 to 40 for better visibility
    overflow: 'visible',
  },
  focusedContainer: {
    borderColor: '#094485',
    borderWidth: 1.5,
  },
  lockedContainer: {
    backgroundColor: '#f8f9fa',
    borderColor: '#d6d8db',
  },
  icon: {
    marginRight: normalize(8),
    marginLeft: normalize(2),
  },
  input: {
    flex: 1,
    fontSize: normalize(12),
    // lineHeight: 1, // <--- REMOVE THIS LINE. It causes the clipping.
    color: '#000',
    height: normalize(28),
    paddingVertical: 0,
    textAlignVertical: 'center', // Ensures text is centered vertically on Android
  },
  lockedInput: {
    color: '#6c757d',
  },
});

export default CustomTextInput;
