import React, { Component } from 'react';
import { Animated, View } from 'react-native';

export default class ABlink extends Component {
  static defaultProps = {
    duration: 600,
    repeat_count: -1,  // infinite loop
    style: {},
  };

  constructor(props) {
    super(props);
    this.fadeAnimation = new Animated.Value(1); // START visible
    this._anim = null;
  }

  componentDidMount() {
    const { duration, repeat_count } = this.props;

    const seq = Animated.sequence([
      Animated.timing(this.fadeAnimation, {
        toValue: 0,
        duration,
        useNativeDriver: true,
      }),
      Animated.timing(this.fadeAnimation, {
        toValue: 1,
        duration,
        useNativeDriver: true,
      }),
    ]);

    this._anim =
      repeat_count === -1
        ? Animated.loop(seq)
        : Animated.loop(seq, { iterations: repeat_count });

    this._anim.start();
  }

  componentWillUnmount() {
    this._anim?.stop();
  }

  render() {
    return (
      <View style={[{ overflow: 'visible' }, this.props.style]}>
        <Animated.View style={{ opacity: this.fadeAnimation }}>
          {this.props.children}
        </Animated.View>
      </View>
    );
  }
}
