import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ActivityIndicator,
  TouchableOpacity,
  SafeAreaView,
  Alert,
  Platform,
  PermissionsAndroid,
  ToastAndroid,
  ScrollView
} from 'react-native';
import { useNavigation } from '@react-navigation/native';
import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
import HeaderBlock from '../Screens/HeaderBlock';
import { WebView } from 'react-native-webview';
import ReactNativeBlobUtil from 'react-native-blob-util';

const PDFViewerScreen = ({ route }) => {
  const navigation = useNavigation();
  const {
    pdfUrl,
    title,
    donorId,
    donorData,
    save1,
    pdfHistory,
    baseUrl
  } = route.params;

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  const [downloading, setDownloading] = useState(false);
  const [currentPdfIndex, setCurrentPdfIndex] = useState(0);
  const [pdfList, setPdfList] = useState([]);
  const [currentPdfUrl, setCurrentPdfUrl] = useState(pdfUrl);
  const [webviewKey, setWebviewKey] = useState(0); // Key to force WebView re-mount

  // Multiple fallback viewers for better compatibility
  const getPdfViewerUrl = (url) => {
    return `https://docs.google.com/gview?embedded=true&url=${encodeURIComponent(url)}`;
  };

  // Initialize PDF list on component mount
  useEffect(() => {
    initializePdfList();
  }, []);

  // Update current PDF URL when index changes - with proper reset
  useEffect(() => {
    if (pdfList.length > 0 && pdfList[currentPdfIndex]) {
      const newUrl = pdfList[currentPdfIndex].url;
      console.log('Switching to PDF:', currentPdfIndex, newUrl);

      // Reset state before switching
      setLoading(true);
      setError(false);

      // Update URL and force WebView to remount with new key
      setCurrentPdfUrl(newUrl);
      setWebviewKey(prev => prev + 1);
    }
  }, [currentPdfIndex, pdfList]);

  // Fixed initializePdfList function
  const initializePdfList = () => {
    let pdfs = [];
    console.log('Initializing PDF list...');
    console.log('save1:', save1);
    console.log('pdfHistory:', pdfHistory);
    console.log('baseUrl:', baseUrl);

    // Add the current/latest PDF (save1) as PDF1
    if (save1) {
      pdfs.push({
        name: 'PDF1',
        url: `${baseUrl}${save1}`,
        filename: save1,
        isLatest: true,
        displayName: 'Latest Registration'
      });
      console.log('Added save1 PDF:', save1);
    }

    // Add historical PDFs as PDF2, PDF3, etc.
    if (pdfHistory && Array.isArray(pdfHistory) && pdfHistory.length > 0) {
      console.log('Processing pdfHistory:', pdfHistory.length, 'items');
      pdfHistory.forEach((pdf, index) => {
        const pdfItem = {
          name: `PDF${index + 2}`, // Start from PDF2 if save1 exists, otherwise PDF1
          url: `${baseUrl}${pdf.pdfPath}`,
          filename: pdf.pdfPath,
          isLatest: false,
          displayName: `History ${index + 1}`
        };
        pdfs.push(pdfItem);
        console.log(`Added history PDF ${index + 1}:`, pdf.pdfPath);
      });
    }

    // If no save1 but we have pdfHistory, renumber starting from PDF1
    if (!save1 && pdfHistory && pdfHistory.length > 0) {
      pdfs = pdfHistory.map((pdf, index) => ({
        name: `PDF${index + 1}`, // Start from PDF1
        url: `${baseUrl}${pdf.pdfPath}`,
        filename: pdf.pdfPath,
        isLatest: index === 0, // First one is latest if no save1
        displayName: index === 0 ? 'Latest Registration' : `History ${index}`
      }));
      setCurrentPdfUrl(`${baseUrl}${pdfHistory[0].pdfPath}`);
    }

    console.log('Final PDF list:', pdfs);
    setPdfList(pdfs);
  };

  const handleWebViewError = (syntheticEvent) => {
    const { nativeEvent } = syntheticEvent;
    console.warn('WebView error: ', nativeEvent);

    // On error, set error state
    setError(true);
    setLoading(false);
  };

  const requestStoragePermission = async () => {
    if (Platform.OS === 'android') {
      try {
        const granted = await PermissionsAndroid.request(
          PermissionsAndroid.PERMISSIONS.WRITE_EXTERNAL_STORAGE,
          {
            title: 'Storage Permission',
            message: 'App needs access to storage to download PDF files.',
            buttonNeutral: 'Ask Me Later',
            buttonNegative: 'Cancel',
            buttonPositive: 'OK',
          }
        );
        return granted === PermissionsAndroid.RESULTS.GRANTED;
      } catch (err) {
        console.warn(err);
        return false;
      }
    }
    return true;
  };

  const downloadPDF = async () => {
    try {
      setDownloading(true);
      const hasPermission = await requestStoragePermission();

      if (!hasPermission) {
        Alert.alert('Permission Denied', 'Storage permission is required to download files.');
        setDownloading(false);
        return;
      }

      const { dirs } = ReactNativeBlobUtil.fs;
      const dirToSave = Platform.OS === 'ios' ? dirs.DocumentDir : dirs.DownloadDir;
      const currentPdf = pdfList[currentPdfIndex];
      const fileName = `${currentPdf.name}_${donorId || 'donor'}_${new Date().getTime()}.pdf`;
      const filePath = `${dirToSave}/${fileName}`;

      const configOptions = Platform.select({
        ios: {
          fileCache: true,
          path: filePath,
          notification: true,
        },
        android: {
          fileCache: false,
          addAndroidDownloads: {
            useDownloadManager: true,
            notification: true,
            path: filePath,
            description: 'Downloading PDF...',
            mime: 'application/pdf',
          },
        },
      });

      ReactNativeBlobUtil.config(configOptions)
        .fetch('GET', currentPdfUrl)
        .progress((received, total) => {
          const progress = ((received / total) * 100).toFixed(2);
          console.log(`Download Progress: ${progress}%`);
        })
        .then((res) => {
          console.log('Download completed:', res.path());
          const message = Platform.OS === 'ios'
            ? 'PDF downloaded successfully!'
            : 'PDF downloaded to Downloads folder!';

          if (Platform.OS === 'android') {
            ToastAndroid.show(message, ToastAndroid.LONG);
          } else {
            Alert.alert('Success', message);
          }
        })
        .catch((error) => {
          console.error('Download error:', error);
          Alert.alert('Download Failed', 'Unable to download PDF. Please try again.');
        })
        .finally(() => {
          setDownloading(false);
        });
    } catch (error) {
      console.error('Download error:', error);
      Alert.alert('Download Failed', 'Unable to download PDF. Please try again.');
      setDownloading(false);
    }
  };

  const switchToPdf = (index) => {
    console.log('Switching to PDF index:', index);
    if (index !== currentPdfIndex) {
      setCurrentPdfIndex(index);
    }
  };

  return (
    <SafeAreaView style={styles.container}>
      <HeaderBlock
        title={`${title} - ${pdfList[currentPdfIndex]?.name || 'PDF'}`}
        onBackPress={() => navigation.goBack()}
      />

      {loading && (
        <View style={styles.loadingContainer}>
          <ActivityIndicator size="large" color="#094485" />
          <Text style={styles.loadingText}>Loading PDF...</Text>
        </View>
      )}

      {error && (
        <View style={styles.errorContainer}>
          <FontAwesome5 name="file-pdf" size={64} color="#ccc" />
          <Text style={styles.errorText}>Unable to load PDF</Text>
          <Text style={styles.errorSubText}>Please check your connection and try again</Text>

          <TouchableOpacity
            style={styles.retryButton}
            onPress={() => {
              setError(false);
              setLoading(true);
              setWebviewKey(prev => prev + 1); // Force WebView re-mount
            }}
          >
            <FontAwesome5 name="redo" size={16} color="#fff" />
            <Text style={styles.retryButtonText}>Retry</Text>
          </TouchableOpacity>
        </View>
      )}

      {!error && (
        <WebView
          key={`pdf-webview-${webviewKey}`}
          style={styles.webView}
          source={{ uri: getPdfViewerUrl(currentPdfUrl) }}
          onLoadStart={() => setLoading(true)}
          onLoadEnd={() => setLoading(false)}
          onError={handleWebViewError}
          javaScriptEnabled={true}
          domStorageEnabled={true}
          startInLoadingState={false}
          scalesPageToFit={true}
          mixedContentMode="compatibility"
          allowsInlineMediaPlayback={true}
          mediaPlaybackRequiresUserAction={false}
          cacheEnabled={true}
          cacheMode="LOAD_CACHE_ELSE_NETWORK"
        />
      )}

      {/* Footer with scrollable PDF buttons + download */}
      <View style={styles.footer}>
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={styles.footerScrollContent}
        >

          {/* PDF Buttons */}
          {pdfList.map((pdf, index) => (
            <TouchableOpacity
              key={`pdf-${index}`}
              style={[
                styles.pdfNavButton,
                currentPdfIndex === index && styles.pdfNavButtonActive
              ]}
              onPress={() => switchToPdf(index)}
            >
              <FontAwesome5
                name="file-pdf"
                size={14}
                color={currentPdfIndex === index ? '#fff' : '#094485'}
              />
              <Text style={[
                styles.pdfNavButtonText,
                currentPdfIndex === index && styles.pdfNavButtonTextActive
              ]}>
                {pdf.name}
              </Text>
              {pdf.isLatest && (
                <View style={styles.latestBadge}>
                  <Text style={styles.latestBadgeText}>Latest</Text>
                </View>
              )}
            </TouchableOpacity>
          ))}

        </ScrollView>
      </View>

    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#f4f5f7'
  },
  footerScrollContent: {
    alignItems: 'center',
    paddingHorizontal: 8,
  },

  webView: {
    flex: 1,
    backgroundColor: '#fff'
  },
  loadingContainer: {
    position: 'absolute',
    top: '50%',
    left: '50%',
    transform: [{ translateX: -75 }, { translateY: -50 }],
    alignItems: 'center',
    zIndex: 1000,
    backgroundColor: 'rgba(255,255,255,0.9)',
    padding: 20,
    borderRadius: 10,
    elevation: 5,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.25,
    shadowRadius: 3.84,
  },
  loadingText: {
    marginTop: 10,
    color: '#094485',
    fontWeight: '600'
  },
  errorContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    padding: 20
  },
  errorText: {
    fontSize: 18,
    color: '#333',
    marginTop: 20,
    marginBottom: 10,
    textAlign: 'center',
    fontWeight: '600'
  },
  errorSubText: {
    fontSize: 14,
    color: '#666',
    marginBottom: 30,
    textAlign: 'center'
  },
  retryButton: {
    backgroundColor: '#094485',
    paddingHorizontal: 24,
    paddingVertical: 12,
    borderRadius: 8,
    flexDirection: 'row',
    alignItems: 'center'
  },
  retryButtonText: {
    color: '#fff',
    fontWeight: '600',
    marginLeft: 8
  },
  footer: {
    backgroundColor: '#fff',
    paddingVertical: 15,
    paddingHorizontal: 16,
    // borderTopWidth: 1,
    borderTopColor: '#e0e0e0',
    elevation: 8,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: -2 },
    shadowOpacity: 0.1,
    shadowRadius: 3,
  },
  pdfNavContainer: {
    maxHeight: 70,
    marginBottom: 2,
  },
  pdfNavContent: {
    paddingHorizontal: 4,
  },
  pdfNavButton: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: '#f0f0f0',
    paddingHorizontal: 12,
    paddingVertical: 10,
    borderRadius: 20,
    marginHorizontal: 4,
    borderWidth: 1,
    borderColor: '#094485',
    position: 'relative',
  },
  pdfNavButtonActive: {
    backgroundColor: '#094485',
  },
  pdfNavButtonText: {
    color: '#094485',
    fontWeight: '600',
    fontSize: 12,
    marginLeft: 6,
  },
  pdfNavButtonTextActive: {
    color: '#fff',
  },
  latestBadge: {
    position: 'absolute',
    top: -4,
    right: -6,
    backgroundColor: '#ff4444',
    borderRadius: 8,
    paddingHorizontal: 4,
    paddingVertical: 3,
  },
  latestBadgeText: {
    color: '#fff',
    fontSize: 8,
    fontWeight: 'bold',
  },
  actionButtonsContainer: {
    flexDirection: 'row',
    justifyContent: 'space-between',
  },
  footerButton: {
    flex: 1,
    maxWidth: '30%',
    backgroundColor: '#094485',
    paddingVertical: 12,
    paddingHorizontal: 16,
    borderRadius: 8,
    marginHorizontal: 4,
    alignItems: 'center',
    justifyContent: 'center',
    flexDirection: 'row',
    minHeight: 44,
  },
  footerButtonDisabled: {
    backgroundColor: '#ccc',
  },
  footerButtonText: {
    color: '#fff',
    fontWeight: '600',
    fontSize: 12,
    marginLeft: 6,
    textAlign: 'center'
  }
});

export default PDFViewerScreen;
