import moment from 'moment'
import React, { useState, useContext } from 'react'
import { View, Text, Image, TouchableOpacity, FlatList, Dimensions, ActivityIndicator, StyleSheet } from 'react-native'
import { imageURL, APIURL } from '../../Common/apiConstants'
import { Global } from '../../Common/Global'
import Icons from '../../Common/Icons'
import { isBNUL, ValueCheck } from '../../CommonStyle/ComponentFunctions'
import { normalize } from '../../CommonStyle/componentStyle'
import NotesInstructionComments from '../../CustomComponents/NotesInstructionComments'
import EmrResponseComponentContext from '../../Handlers/emrResponseComponentContext'
import HHeading from '../../HOC/HHeading'
import HOverlay from '../../HOC/HOverlay'
import CSingleImage from '../../Media/CSingleImage'
import SCheckBox from '../../StaticComponents/SCheckBox'
import SDatePickerNew from '../../StaticComponents/SDatePickerNew'
import STextInput from '../../StaticComponents/STextInput'
import { useNavigation } from '@react-navigation/native'
import { manageContext } from '../../Handlers/manageContext'
import CLineChart from './CLineChart'

export default function CustomVitalSign(props) {

    const navigation = useNavigation();
    const { responseJSON, setResponseJSON } = useContext(EmrResponseComponentContext);
    const stemplate = props.stemplate ?? false;
    const { contextdata, setContextData } = manageContext(stemplate);
    // const [data, setData] = useState(props.data)
    const data = contextdata.consultation?.[contextdata.natureindex]?.NewData?.[props.index]?.editArray;
    const [overlayData, setOverlayData] = useState()
    const [overlay, setOverlay] = useState(false)
    const [refresh, setRefresh] = useState(0)
    const [itemindex, setItemIndex] = useState(0);
    const { parentClass } = props

    // --- NEW STATE FOR CHART DISPLAY ---
    const [historicalData, setHistoricalData] = useState(null);
    const [selectedItem, setSelectedItem] = useState(null);
    const [isLoading, setIsLoading] = useState(false);
    // -----------------------------------

    const patientDatalistId = Global.PatientDetails?.datalistid
    const apiUrlBase = APIURL + 'bldget/invcommonget/rnbbvitalchart';

    const fetchChartData = async (item) => {
        setIsLoading(true);
        setSelectedItem(item);
        setHistoricalData(null);

        const vitalName = item.displaytext.toLowerCase().replace(/\s/g, '');

        // Correct API URL construction: /rnbbvitalchart{space}ID,vitalName
        const apiUrl = `${apiUrlBase} ${patientDatalistId},${vitalName}`;

        console.log("Fetching chart data for vital:", item.displaytext, "from URL:", apiUrl);

        let chartData = [];

        try {
            const response = await fetch(apiUrl);
            const jsonResponse = await response.json();

            if (jsonResponse.success && jsonResponse.data && jsonResponse.data.data) {
                chartData = jsonResponse.data.data;
                setHistoricalData(chartData);
            } else {
                setHistoricalData([]);
            }

        } catch (error) {
            console.error(`Error fetching vital chart data for ${item.displaytext}:`, error);
            setHistoricalData([]);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <View style={{
            borderWidth: 1,
            borderColor: "lightgrey",
            margin: 5,
            padding: normalize(5),
            backgroundColor: 'rgba(237, 232, 232,0.3)',
        }}>
            {isBNUL(data) ?
                <FlatList
                    data={data}
                    renderItem={renderItem}
                    numColumns={2}
                    columnWrapperStyle={{ justifyContent: 'space-between' }}
                    keyExtractor={(item, index) => `key_${index}`}
                    listKey={(item, index) => `key_${index}`}
                    ListHeaderComponent={
                        ValueCheck(parentClass.display) ?
                            <HHeading
                                styles={{
                                    "iconname": "dot-circle",
                                    "bgcolor": "#f2efef",
                                    "iconsize": 16,
                                    "iconcolor": Global.AppTheme.primary_color,
                                    "displaytext": (parentClass.display).toUpperCase(),
                                    "textsize": 14,
                                    "textcolor": Global.AppTheme.primary_color
                                }}
                                callBack={val => (val == undefined ? null : console.log(val))}>
                            </HHeading>
                            : null
                    }
                />
                : null}
            {/* --- CONDITIONAL CHART DISPLAY AREA --- */}
            {(isLoading || historicalData !== null) && (
                <View style={styles.chartContainer}>
                    {isLoading ? (
                        <ActivityIndicator size="large" color="darkblue" style={{ padding: normalize(20) }} />
                    ) : selectedItem && historicalData !== null && historicalData.length > 0 ? (
                        <>
                            <Text style={styles.chartTitle}>
                                {selectedItem.displaytext} Trend ({selectedItem.unit})
                            </Text>
                            <CLineChart data={historicalData} />
                        </>
                    ) : selectedItem ? (
                        <Text style={styles.noDataText}>No historical data available for {selectedItem.displaytext}.</Text>
                    ) : null}
                </View>
            )}
            {/* -------------------------------------- */}
        </View>
    )

    function deleteItem(params) {
        if (data.length > 1) {
            const index = data.map(e => e.datavalue).indexOf(params.datavalue)
            if (index > -1) {
                // let obj = data[index]
                // obj.EditFlag = 5
                // console.log("Objecttttttttt",JSON.stringify(obj))
                // data.splice(index, 1);
            }
            setRefresh(refresh + 1)
        }
    }

    function handleInputChange(text, index, field, editflag, details) {
        const upperCaseText = typeof text === 'string' ? text.toUpperCase() : text;

        // ✅ get donor gender from donor card
        const donorGenderRaw = Global?.PatientDetails?.profilecontent?.[0]?.gender;
        const donorGender = typeof donorGenderRaw === 'string' ? donorGenderRaw.toLowerCase() : '';

        // Default Hb ranges
        const HB_MIN = 12.5;
        const HB_MAX_MALE = 18.5;
        const HB_MAX_FEMALE = 16.5;

        let errorStatus = false;
        let updatedDetails = { ...details };

        // ✅ apply hardcoded Hb range logic only if this is Hb field
        const isHbField =
            details.displaytext?.toLowerCase() === 'hb' ||
            details.displaytext?.toLowerCase().includes('hemoglobin') ||
            details.displaytext?.toLowerCase().includes('haemoglobin');

        if (isHbField && field === 'value') {
            const numValue = parseFloat(upperCaseText);

            // pick max depending on gender
            const hbMax = donorGender === 'male' ? HB_MAX_MALE : HB_MAX_FEMALE;
            const hbMin = HB_MIN;

            updatedDetails.minvalue = hbMin;
            updatedDetails.maxvalue = hbMax;

            if (!isNaN(numValue) && (numValue < hbMin || numValue > hbMax)) {
                errorStatus = true;
            }
        } else if (field === 'value') {
            // keep existing validation for other fields
            const numValue = parseFloat(upperCaseText);
            if (!isNaN(numValue)) {
                const minValue = details.minvalue || 0;
                const maxValue = details.maxvalue || 0;
                if (maxValue > 0 && (numValue < minValue || numValue > maxValue)) {
                    errorStatus = true;
                }
            }
        }

        updatedDetails = {
            ...updatedDetails,
            EditFlag:
                details.EditFlag === 1
                    ? 2
                    : details.EditFlag === 3
                        ? 4
                        : details.EditFlag,
            [field]: upperCaseText,
            errorStatus: errorStatus,
        };

        // ✅ same update logic you already have
        const updatedResponseJSON = {
            ...contextdata,
            editStatus: true,
            consultation: [...contextdata.consultation],
        };

        const natureindex = updatedResponseJSON.natureindex ?? 0;

        updatedResponseJSON.consultation[natureindex] = {
            ...updatedResponseJSON.consultation[natureindex],
            editStatus: true,
            NewData: [...updatedResponseJSON.consultation[natureindex].NewData],
        };

        updatedResponseJSON.consultation[natureindex].NewData[props.index] = {
            ...updatedResponseJSON.consultation[natureindex].NewData[props.index],
            editArray: [...updatedResponseJSON.consultation[natureindex].NewData[props.index].editArray],
        };

        updatedResponseJSON.consultation[natureindex].NewData[props.index].editArray[index] = {
            ...updatedResponseJSON.consultation[natureindex].NewData[props.index].editArray[index],
            ...updatedDetails,
        };

        setContextData(updatedResponseJSON);
        setRefresh(refresh + 1);
        Global.EditStatus = 1;
    }


    function renderItem({ item, index }) {
        return (
            <View style={{ paddingBottom: 0, }}>
                <View style={{
                    paddingBottom: 0,
                    width: Dimensions.get('screen').width * 0.46,
                    marginVertical: normalize(5)
                }}>
                    {ValueCheck(item.displaytext) ?
                        <TouchableOpacity
                            disabled={true}
                            onPress={() => deleteItem(item)}
                            style={{ flexDirection: 'row', marginLeft: normalize(5), marginTop: normalize(5), alignItems: 'center', width: '90%' }}>
                            <Icons.FontAwesome5 name={"dot-circle"} size={normalize(10)} color={Global.AppTheme.primary_color} />
                            <Text style={{ paddingLeft: normalize(10), fontWeight: 'normal', fontSize: normalize(14) }}>{(item.displaytext).toUpperCase()}</Text>
                        </TouchableOpacity>
                        : null}
                    {ValueCheck(item.question) ?
                        <SCheckBox
                            data={{ value: item.questionValue }}
                            callBack={val => (val == undefined ? null : (
                                handleInputChange(val, index, 'questionValue', 'EditFlag', item)
                            ))}
                        /> : null}
                </View>

                <View style={{ flexDirection: 'row', justifyContent: 'space-between' }}>
                    {ValueCheck(item.durationStatus) ?
                        <STextInput
                            data={{
                                value: item.duration,
                                itemwidth: Dimensions.get("screen").width * 0.25,
                                displaytext: "DURATION",
                                validation: 2,
                                capitalize: "characters"
                            }}
                            callBack={val => (val == undefined ? null : (
                                handleInputChange(val, index, 'duration', 'EditFlag', item)
                            ))}
                            unit={'SETUP'}
                            tprcallback={(val) => {
                                navigation.navigate('CTprVitalsign', {
                                    data: item
                                });
                            }}
                        /> : null}

                    {ValueCheck(item.frequencyStatus) ?
                        <STextInput
                            data={{
                                value: item.frequency,
                                itemwidth: Dimensions.get("screen").width * 0.25,
                                displaytext: "FREQUENCY",
                                validation: 2,
                                capitalize: "characters"
                            }}
                            callBack={val => (val == undefined ? null : (
                                handleInputChange(val, index, 'frequency', 'EditFlag', item)
                            ))}
                            unit={'SETUP'}
                            tprcallback={(val) => {
                                navigation.navigate('CTprVitalsign', {
                                    data: item
                                });
                            }}
                        /> : null}
                </View>

                <View style={{ flexDirection: 'row', justifyContent: 'space-between', }}>
                    {ValueCheck(item.fromDate) ?
                        <SDatePickerNew
                            minimumdate={moment().format('YYYY-MM-DD')}
                            passingDate={
                                item.fdate != undefined
                                    && item.fdate != null
                                    && item.fdate != "" ? item.fdate : null
                            }
                            table={false}
                            data={{
                                itemwidth: (Dimensions.get('screen').width * 0.3),
                                displaytext: "FROM DATE",
                                justifyContent: 'flex-start'
                            }}
                            onChangeData={val => (val == undefined ? null : (
                                handleInputChange(val, index, 'fdate', 'EditFlag', item)
                            ))} /> : null}

                    {ValueCheck(item.toDate) ?
                        <SDatePickerNew
                            minimumdate={moment().format('YYYY-MM-DD')}
                            passingDate={
                                item.tdate != undefined
                                    && item.tdate != null
                                    && item.tdate != "" ? item.tdate : null
                            }
                            table={false}
                            data={{
                                itemwidth: (Dimensions.get('screen').width * 0.3),
                                displaytext: "TO DATE",
                            }}
                            onChangeData={val => (val == undefined ? null : (
                                handleInputChange(val, index, 'tdate', 'EditFlag', item)
                            ))} /> : null}
                </View>

                <View style={{ flexDirection: 'row', justifyContent: 'space-between' }}>
                    {ValueCheck(item.valueStatus) ?
                        <View style={{
                            flex: 1,
                            justifyContent: 'center',
                        }}>
                            <STextInput
                                unit={ValueCheck(item.unit) ? item.unit.toUpperCase() : 'SETUP'}
                                data={{
                                    value: item.value,
                                    itemwidth: Dimensions.get("screen").width * 0.25,
                                    validation: 2,
                                    minvalue: ValueCheck(item.minvalue) ? item.minvalue : null,
                                    maxvalue: ValueCheck(item.maxvalue) ? item.maxvalue : null,
                                    capitalize: "characters",
                                    errorStatus: item.errorStatus
                                }}
                                callBack={val => (val == undefined ? null : (
                                    handleInputChange(val, index, 'value', 'EditFlag', item)
                                ))}
                                tprcallback={(val) => {
                                    navigation.navigate('CTprVitalsign', {
                                        data: item
                                    });
                                }}
                            />
                            <TouchableOpacity
                                style={{
                                    position: 'absolute',
                                    right: 0,
                                    top: normalize(2),
                                    paddingHorizontal: normalize(41),
                                    paddingVertical: normalize(2),
                                    justifyContent: 'center',
                                    alignItems: 'center',
                                    zIndex: 10,
                                    elevation: 5
                                }}
                                onPress={() => {
                                    fetchChartData(item);
                                }}
                            >
                                <Icons.FontAwesome5
                                    name="chart-line"
                                    size={normalize(18)}
                                    color="darkblue"
                                />
                            </TouchableOpacity>
                            {item.errorStatus && ValueCheck(item.minvalue) && ValueCheck(item.maxvalue) && item.maxvalue > 0 ? (
                                <Text style={{
                                    color: 'red',
                                    fontSize: normalize(10),
                                    fontWeight: 700,
                                    marginTop: normalize(2),
                                    marginLeft: normalize(5)
                                }}>
                                    Range: {item.minvalue}-{item.maxvalue}
                                </Text>
                            ) : null}
                        </View>
                        : null}

                    {ValueCheck(item.remarksStatus) ?
                        <STextInput
                            data={{
                                value: item.remarks,
                                disableheight: true,
                                itemwidth: Dimensions.get("screen").width * 0.25,
                                displaytext: "REMARKS",
                                validation: 2,
                                capitalize: "characters"
                            }}
                            callBack={val => (val == undefined ? null : (
                                handleInputChange(val, index, 'remarks', 'EditFlag', item)
                            ))}
                            unit={'SETUP'}
                            tprcallback={(val) => {
                                navigation.navigate('CTprVitalsign', {
                                    data: item
                                });
                            }}
                        /> : null}
                </View>

                <View style={{ justifyContent: 'flex-end' }}>
                    {ValueCheck(item.notesStatus) ?
                        <View style={{ flexDirection: 'row' }}>
                            <TouchableOpacity onPress={() => getNotes(item)}
                                style={{ marginLeft: normalize(5), marginTop: normalize(5), alignItems: 'center', width: normalize(50) }}>
                                <Icons.FontAwesome5 name={"pen-square"} size={normalize(18)} color={Global.AppTheme.primary_color} />
                                <Text style={{ fontSize: normalize(10) }}>{"NOTES"}</Text>
                            </TouchableOpacity>

                            <View
                                style={{
                                    marginBottom: normalize(2),
                                    marginLeft: normalize(5),
                                    flex: 1
                                }}>
                                <NotesInstructionComments
                                    disabled={true}
                                    data={item.NotesArray}
                                    icon={'notes'}
                                    verification={true}
                                />
                            </View>
                        </View> : null}

                    {ValueCheck(item.instructionStatus) ?
                        <View style={{ flexDirection: 'row' }}>
                            <TouchableOpacity onPress={() => getInstructions(item)}
                                style={{ marginLeft: normalize(5), marginTop: normalize(5), alignItems: 'center', width: normalize(50) }}>
                                <Icons.FontAwesome5 name={"info-circle"} size={normalize(18)} color={Global.AppTheme.primary_color} />
                                <Text style={{ fontSize: normalize(10) }}>{"INSTRUCTIONS"}</Text>
                            </TouchableOpacity>

                            <View
                                style={{
                                    marginBottom: normalize(2),
                                    marginLeft: normalize(5),
                                    flex: 1
                                }}>
                                <NotesInstructionComments
                                    disabled={true}
                                    data={item.InstructionsArray}
                                    icon={'notes'}
                                    verification={true}
                                />
                            </View>
                        </View> : null}
                </View>

                {ValueCheck(item.imageStatus) ?
                    <CSingleImage
                        imageurl={ValueCheck(item.imageurl) ? imageURL + item.imageurl : null}
                        callBack={(val) => (val == undefined ? null : (
                            handleInputChange(val, index, 'imageurl', 'EditFlag', item)
                        ))}
                    />
                    : null}

                {overlay ? (
                    <HOverlay
                        data={overlayData}
                        component={'CNotesOrInstructions'}
                        navigation={props.navigation}
                        heading={'NOTES'}
                        IconColour={val =>
                            val == undefined ? null : console.log(val)
                        }
                        arguments={contextdata.consultationEdit.hosumrclassificationnature}
                        selectionapi={
                            'emr/emrcommonget/exec rnddhosumrinstructionsornotes ' +
                            contextdata.consultationEdit.hosumrclassificationnature +
                            ",'',1"
                        }
                        visibility={val => (val == undefined ? null : setOverlay(val))}
                        loading={val => val == undefined ? null : console.log(val)}
                    />
                ) : null}
            </View>
        )
    }

    function getEditFlag(params) {
        if (params.EditFlag == 1) {
            params.EditFlag = 2
        } else if (params.EditFlag == 3) {
            params.EditFlag = 4
        }
        Global.EditStatus = 1
        contextdata.consultationEdit.editStatus = true
    }

    function getNotes(item) {
        console.log("ITEM NOTES ARRAYYYYYYY", JSON.stringify(item))
        let x = {
            "nature": "Y",
            "componentname": "overlay",
            "notes": "",
            "buttonapi": "emr/emrcommonget/exec rnddhosumrinstructionsornotes " + contextdata.consultationEdit.hosumrclassificationnature + "," + "''" + "," + 1,
            "name": "NOTES",
            "NotesArray": item.NotesArray
        }
        setOverlay(true)
        setOverlayData(x)
        getEditFlag(item)
    }

    function getInstructions(item) {
        let x = {
            "nature": "Y",
            "componentname": "overlay",
            "notes": "",
            "buttonapi": "emr/emrcommonget/exec rnddhosumrinstructionsornotes " + contextdata.consultationEdit.hosumrclassificationnature + "," + "''" + "," + 2,
            "name": "INSTRUCTIONS",
            "InstructionsArray": item.InstructionsArray
        }
        setOverlay(true)
        setOverlayData(x)
        getEditFlag(item)
    }
}

const styles = StyleSheet.create({
    chartContainer: {
        marginTop: normalize(10),
        padding: normalize(5),
        backgroundColor: 'rgba(237, 232, 232,0.3)',
        borderWidth: 1,
        borderColor: 'lightgrey',
        width: Dimensions.get('screen').width * 0.98
    },
    chartTitle: {
        fontSize: normalize(16),
        fontWeight: 'bold',
        color: 'darkblue',
        padding: normalize(5),
        marginBottom: normalize(5),
    },
    noDataText: {
        padding: normalize(15),
        textAlign: 'center',
        color: 'red',
        fontSize: normalize(14),
    }
});
