import React, { useState, useEffect } from 'react';
import { View, Text, TextInput, Alert, Keyboard, TouchableOpacity } from 'react-native';
import { styles } from './styles';
import CustomTextInput from '../CustomComponents/CustomTextInput'; // Import CustomTextInput
import Icon from 'react-native-vector-icons/Feather';

/**
 * ContactInfoSection
 * Mobile + WhatsApp placed on a single row (compact).
 *
 * Note: adjust `inputContainer` spacing or `flex` values below
 * if you want different width ratios (e.g. mobile narrower than whatsapp).
 */
const ContactInfoSection = ({
  formData,
  handleInputChange,
  getText,
  fetchedFields = [],
  selectedUserType = 'others',
}) => {
  const [sameAsMobile, setSameAsMobile] = useState(false);

  // When checkbox is toggled or mobile number changes
  useEffect(() => {
    if (sameAsMobile && formData.mobile && formData.mobile.length === 10) {
      handleInputChange('whatsapp', formData.mobile);
    } else if (!sameAsMobile) {
      // Clear WhatsApp number when checkbox is unchecked
      handleInputChange('whatsapp', '');
    }
  }, [sameAsMobile, formData.mobile]);

  // Auto-uncheck if WhatsApp is manually changed to differ from mobile
  useEffect(() => {
    if (sameAsMobile && formData.whatsapp !== formData.mobile) {
      setSameAsMobile(false);
    }
  }, [formData.whatsapp]);

  return (
    <View style={{ marginTop: 0 }}>

      {/* WhatsApp & Email in single row */}
      <View style={{ flexDirection: 'row', alignItems: 'flex-start', marginBottom: 7, gap: 12 }}>
        {/* WhatsApp - left field */}
        <View style={{ flex: 0.8 }}>
          <CustomTextInput
            label={getText('whatsappNumber')}
            iconName="whatsapp" // FontAwesome5 brand icon for WhatsApp
            placeholder=""
            keyboardType="phone-pad"
            value={formData.whatsapp || ''}
            onChangeText={(text) => {
              const numericText = text.replace(/[^0-9]/g, '').slice(0, 10);
              handleInputChange('whatsapp', numericText);
            }}
            fetchedFields={fetchedFields}
            fieldName="whatsapp"
            iconColor="#25D366" // WhatsApp green color
            returnKeyType="done"
            onSubmitEditing={() => Keyboard.dismiss()}
          />
        </View>

        {/* Email Address - right field (wider) */}
        <View style={{ flex: 1.2 }}>
          <CustomTextInput
            label={getText('emailAddress')}
            iconName="envelope" // FontAwesome5 icon for email
            placeholder=""
            keyboardType="email-address"
            autoCapitalize="none"
            value={formData.email || ''}
            onChangeText={(text) => {
              const emailText = text.toLowerCase().trim();
              handleInputChange('email', emailText);
            }}
            fetchedFields={fetchedFields}
            fieldName="email"
            onBlur={() => {
              const email = formData.email || '';
              if (email.length > 0) {
                // Basic email validation regex
                const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                if (!emailRegex.test(email)) {
                  Alert.alert('Invalid Email', 'Please enter a valid email address');
                }
              }
            }}
            returnKeyType="done"
            onSubmitEditing={() => Keyboard.dismiss()}
          />
        </View>
      </View>

      {/* Same as Mobile Checkbox - below the row */}
      {formData.mobile && formData.mobile.length > 0 && (
        <TouchableOpacity
          onPress={() => setSameAsMobile(!sameAsMobile)}
          style={{
            flexDirection: 'row',
            alignItems: 'center',
            marginTop: -2,
            marginBottom: 8,
            marginLeft: 8,
          }}
          activeOpacity={0.7}
        >
          <View
            style={{
              width: 14,
              height: 14,
              borderRadius: 2,
              borderWidth: 1.5,
              borderColor: sameAsMobile ? '#25D366' : '#CCC',
              backgroundColor: sameAsMobile ? '#25D366' : 'transparent',
              justifyContent: 'center',
              alignItems: 'center',
              marginRight: 5,
            }}
          >
            {sameAsMobile && (
              <Icon name="check" size={9} color="#fff" />
            )}
          </View>
          <Text style={{ fontSize: 11, color: '#666', fontWeight: '400' }}>
            WhatsApp same as mobile number
          </Text>
        </TouchableOpacity>
      )}
    </View>
  );
};

export default ContactInfoSection;
