export default function DeleteParameter(props) {
    const { responseJSON, setResponseJSON } = useContext(InsureResponseComponentContext);
    // console.log("GGGGGGHHHHHHHHTTTTTTTTEEEEEEEEEEEEEERRRRRRRR", JSON.stringify(responseJSON.consultationEdit))
    const { width, height } = Dimensions.get('window');
    const [searchData, setSearchData] = useState('');
    const [refreshCount, setRefreshCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);
    const [displayData, setDisplayData] = useState([]);
    const [overwrite, setOverwrite] = useState(0);
    const [tempString, settempString] = useState([]);
    const [isCollapseChild, setIsCollapseChild] = useState(props.collapse);
    const [selected, setSelected] = useState(0);
    const [alphaFilter, setAlphaFilter] = useState(false);
    const [alphaindex, setAlphaIndex] = useState();
    const [filterPurpose, setFilterPurpose] = useState([]);
    const [request, setRequest] = useState([]);
    const hosumrclassificationnature = responseJSON.consultation[responseJSON.natureindex].hosumrclassificationnature;
    const nature = responseJSON.consultation[responseJSON.natureindex].nature;
    const heading = responseJSON.consultation[responseJSON.natureindex].heading;


    useEffect(() => {
        DropDownList()
    }, []);

    var call = []

    function DropDownList() {
        setDisplayData(responseJSON.consultation[responseJSON.natureindex].NewData)
    }

    function getAlphabetData(alpha, index) {
        var filter = displayData.filter(value => (value.display != undefined ? value.display : "").charAt(0) == alpha)
        setFilterPurpose(filter)
        index == 0 ? setSearchData('') : setSearchData(alpha)
        index == 0 ? setAlphaFilter(false) : setAlphaFilter(true)
    }

    return (
        <View style={{ flex: 1 }}>

            <Text style={{ alignSelf: 'center', fontSize: normalize(12), fontWeight: 'bold', marginBottom: normalize(5), marginTop: normalize(-5) }}>{ValueCheck(responseJSON) && ValueCheck(heading) ? heading + " DELETE" : 'DELETE'}</Text>

            <View style={getOverlayScreenContainer()}>
                <SSearchBar
                    onChangeText={val => setSearchData(val)} />
            </View>

            <View style={{ flexDirection: 'row', justifyContent: 'space-between', flex: 1 }}>
                <View style={getOverlayScreenChildContainer()}>
                    {GetSearchData(alphaFilter ? filterPurpose : displayData)}
                </View>

                <View>
                    <SAlphabet
                        callBack={val =>
                            val == undefined ? null : getAlphabetData(val.alpha, val.index)
                        } />
                </View>
            </View>

            <CFooterView style={{ width: Dimensions.get('screen').width - normalize(15), backgroundColor: '#fff' }}>
                <View style={{ flexDirection: 'row' }}>
                    {[{
                        "displaytext": "Delete", "size": 10, "iconname": "trash", "iconcolor": '#FF0032',
                        "fontcolor": '#FF0032', "shadowcolor": '#f2d2d8', "size": 10, "selected": false, "visibility": true, "iconsize": 20, "functionid": "DP01"
                    }].map((item, i) => {
                        return (
                            <View key={i} style={{ width: normalize(50), borderRadius: normalize(10) }}>
                                <CAwesomeButton
                                    data={item}
                                    callBack={val => val == undefined ? null : getFooterFunctions(val)}
                                />
                            </View>
                        )
                    })}
                </View>
            </CFooterView>

            {isLoading ? <Loader displaytext={true} /> : null}
        </View>
    )

    function getFooterFunctions(val) {
        switch (val.functionid) {
            case "DP01": tempString.length > 0 ? getDelete(tempString) : notifyMessage("Please select at lease one item", 3)
                break;

            default:
                break;
        }
    }

    function getDelete() {
        var arr = []
        var arr1 = []
        tempString.map((item) => {
            var y = displayData.map(e => e.keyid).indexOf(item)
            arr1.push(displayData[y])
            arr.push(displayData.map(e => e.keyid).indexOf(item))
        })

        var output = {};
        output.groups = {};
        output.groups.procedurename = "homrpatientdatadelete1"
        output.groups.consultationdata = responseJSON.consultationdata
        output.groups.hosumrclassificationnature = hosumrclassificationnature
        output.groups.nature = nature
        output.groups.deleteArray = arr1

        let buttonapi = APIURL + 'commondelete/RnCommonDelete';
        console.log("deletebuttonapi", buttonapi)
        console.log("delete outputttttttttttttRRRRRRRRRRRRRRRRRRRRR", JSON.stringify(output))
        // setIsLoading(true)
        NetworkServiceCall("post", buttonapi, output)
            .then(function (response) {
                if (response.httpstatus == 200) {
                    
                    const removeValFromIndex = arr;
                    removeValFromIndex.sort(function (a, b) { return a - b; });
                    console.log('removeValFromIndex............', JSON.stringify(arr1));



                    const keysToRemove = arr1.map((item, i) => item.keyid);

                    const updatedResponseJSON = {
                        ...responseJSON,
                        editStatus: true,
                        consultation: [...responseJSON.consultation], // Clone the consultation array
                    };
            
                    const natureindex = updatedResponseJSON.natureindex ?? 0;
            
                    updatedResponseJSON.consultation[natureindex] = {
                        ...updatedResponseJSON.consultation[natureindex],
                        editStatus: true,
                        NewData: [...updatedResponseJSON.consultation[natureindex].NewData]
                    }
            
                    updatedResponseJSON.consultation[natureindex].NewData = [
                        ...updatedResponseJSON.consultation[natureindex].NewData.filter(item => !keysToRemove.includes(item.keyid))
                    ]
            
                    setResponseJSON(updatedResponseJSON);




                    // for (var i = removeValFromIndex.length - 1; i >= 0; i--) {
                    //     displayData.splice(removeValFromIndex[i], 1)
                    // }

                    setIsLoading(false)
                    props.visibility(false)
                }
                else {
                    setIsLoading(false)
                    notifyMessage("Delete Error", 2)
                    props.visibility(false)
                }
            })
        // getLoading(v => setIsLoading(false))
    }

    function GetSearchData(data) {
        var filterAlpha = alphaFilter ? filterPurpose : data;
        const newDropDownData = filterAlpha.filter(function (item) {
            const dataItem = item.display
                ? item.display.toUpperCase()
                : ''.toUpperCase();
            const textData = searchData.toUpperCase();
            return dataItem.indexOf(textData) > -1;
        });

        function renderItem(data) {
            return (
                data.item.display != undefined
                    && data.item.display != "" ?
                    <View style={{}}>
                        <Collapse
                            onToggle={() => onSelectItem(data.item, true, data.index)}>
                            <CollapseHeader>
                                <View
                                    style={[
                                        getListviewItem(data.item.selected),
                                        {
                                            flexDirection: 'row',
                                            alignItems: 'center',
                                            justifyContent: 'flex-start',
                                        },
                                    ]}>
                                    <Icons.FontAwesome5
                                        name="dot-circle"
                                        color={Global.AppTheme.primary_color}
                                        size={normalize(17)}
                                        style={[{ margin: 2, paddingLeft: 5 }]}
                                    />

                                    <Text
                                        style={[
                                            getListviewItemText(data.item.selected),
                                            { margin: 2, paddingLeft: 2 },
                                        ]}>
                                        {(data.item.display).toUpperCase()}
                                    </Text>
                                </View>
                            </CollapseHeader>
                        </Collapse>
                    </View> : null
            );
        }

        function onSelectItem(datavalue, multiselect, i) {
            if (multiselect == true) {
                if (tempString.includes(datavalue.keyid)) {

                    // datavalue.selected = !datavalue.selected;



                    setDisplayData(prevData => {
                        // To update state in the component
                        const updatedData = [...prevData];
                        updatedData[i] = {
                            ...updatedData[i],
                            selected: !datavalue.selected
                        };
                        return updatedData;
                    });

                    setSelected(selected + 1);
                    var index = tempString.indexOf(datavalue.keyid);
                    if (index > -1) {
                        tempString.splice(index, 1);
                    }
                } else {
                    setDisplayData(prevData => {
                        // To update state in the component
                        const updatedData = [...prevData];
                        updatedData[i] = {
                            ...updatedData[i],
                            selected: !datavalue.selected
                        };
                        return updatedData;
                    });
                    // datavalue.selected = !datavalue.selected;
                    setSelected(selected + 1);
                    tempString.push(datavalue.keyid);
                }
            } else {
                setDisplayData(prevData => {
                    // To update state in the component
                    const updatedData = [...prevData];
                    updatedData[i] = {
                        ...updatedData[i],
                        selected: !datavalue.selected
                    };
                    return updatedData;
                });
                // datavalue.selected = !datavalue.selected;
                tempString.push(datavalue.keyid)
                setSelected(selected + 1);
            }
        }

        return (
            <View style={layoutstyles.overlay_screen_listview_container}>
                <View style={getOverlayScreenChildlistContainer()}>
                    <FlatList data={newDropDownData} renderItem={renderItem} />
                </View>
            </View>
        );
    }

    function getOverlayScreenChildlistContainer() {
        return {
            flex: 1,
            marginBottom: height * 0.01,
            marginTop: height * 0.01,
        };
    }
    function getCollapseBody() {
        return {
            paddingLeft: width * 0.03,
        };
    }

    function getCollapseHeader() {
        return {
            margin: width * 0.002,
            padding: width * 0.007,
            ...layoutstyles.collapse_header,
        };
    }

    function getOverlayScreenChildContainer() {
        return {
            flex: 1,
        };
    }

    function getParameterView() {
        return {
            paddingLeft: width * 0.02,
        };
    }

    function getOverlayScreenContainer() {
        return {
            flexDirection: 'row',
        };
    }
}

