import React from 'react';
import {
    Text,
    View,
} from 'react-native';
import AwesomeButton from "react-native-really-awesome-button";
import HOCIcons from '../HOC/HOCIcons';
import { TouchableOpacity } from 'react-native';


export default function CAwesomeButton(props) {

    return (
        <AwesomeButton
            onPress={() => { props.disablepress ? null : props.callback(props.data) }}
            onLongPress={() => { props.enablelongpress ? props.callback(props.data) : null }}
            borderRadius={props.buttonstyle.borderRadius}
            borderWidth={props.buttonstyle.borderWidth}
            height={props.buttonstyle.height}
            width={props.buttonstyle.width}
            backgroundColor={props.buttonstyle.backgroundColor}
            paddingHorizontal={props.buttonstyle.paddingHorizontal}
            raiseLevel={props.buttonstyle.raiseLevel ? props.buttonstyle.raiseLevel  : 0}
            paddingBottom={props.buttonstyle.paddingBottom}
            borderColor={props.buttonstyle.borderColor}
            paddingTop={props.buttonstyle.paddingTop}
            style={props.buttonstyle.style}
            springRelease={true}
            // backgroundShadow={'pink'}
        >
            <View style={props.viewstyle}>
                {props.icon ?
                    <HOCIcons.Icons
                        icongroup={props.icon.icongroup}
                        name={props.icon.name}
                        color={props.icon.color}
                        size={props.icon.size}
                        style={props.icon.style}
                    />
                : null}
                {props.text ?
                    <Text adjustsFontSizeToFit style={props.text}>
                        {props.displaytext != null && props.displaytext != undefined ? props.displaytext : null}
                    </Text>
                : null}
            </View>
        </AwesomeButton>
    )

}