import React from 'react';
import { isBNU } from '../CommonStyle/ComponentFunctions';


export default function HReportWaterMark(props, color, imagePath) {

    // If imagePath is provided, use image watermark
    if (imagePath) {
        return (`
        <style>
            .watermark-container {
                position: fixed;
                top: 0;
                left: 0;
                right: 0;
                bottom: 0;
                width: 100%;
                height: 100%;
                display: flex;
                align-items: center;
                justify-content: center;
                pointer-events: none;
                z-index: 0;
            }
            .watermark-image {
                width: 450px;
                height: auto;
                max-width: 80%;
                opacity: 0.15;
                -webkit-print-color-adjust: exact !important;
                print-color-adjust: exact !important;
            }
            @media print {
                .watermark-container {
                    position: fixed;
                    top: 0;
                    left: 0;
                    right: 0;
                    bottom: 0;
                    -webkit-print-color-adjust: exact !important;
                    print-color-adjust: exact !important;
                }
            }
        </style>
        <div class="watermark-container">
            <img src="${imagePath}" class="watermark-image" alt="Watermark" />
        </div>
        `);
    }

    // Otherwise use text watermark
    return (`
    <style>
        .watermark-text-container {
            position: fixed;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%) rotate(-30deg);
            opacity: 0.15;
            font-weight: bold;
            z-index: 0;
            color: ${isBNU(color) ? color : 'lightgrey'};
            font-size: 80px;
            white-space: nowrap;
            pointer-events: none;
            -webkit-print-color-adjust: exact !important;
            print-color-adjust: exact !important;
        }
        @media print {
            .watermark-text-container {
                position: fixed;
                -webkit-print-color-adjust: exact !important;
                print-color-adjust: exact !important;
            }
        }
    </style>
    <div class="watermark-text-container">
        ${props}
    </div>
    `)

}