import React from 'react';

// import React, { useState, useEffect } from 'react';
// import { ValueCheck } from '../CommonStyle/ComponentFunctions';

export default function HReportFormat(content, header, footer, headerHeight = '80px', footerHeight = '50px') {
    // Check if we effectively have a header or footer passed
    const hasHeader = header && header.length > 0;
    const hasFooter = footer && footer.length > 0;

    return (`
        <html>
            <head>
                <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.2.1/css/all.min.css" />
                <style>
                    body { margin: 0; padding: 0; font-family: 'Helvetica', sans-serif; position: relative; }
                    /* Ensure exact printing of background colors/images */
                    * { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
                    
                    /* Ensure content appears above watermark */
                    .page-content { position: relative; z-index: 1; }
                    
                    ${hasHeader || hasFooter ? `
                        .page-header, .page-header-space { height: ${headerHeight}; }
                        .page-footer, .page-footer-space { height: ${footerHeight}; }
                        
                        .page-header { position: fixed; top: 0; width: 100%; background: white; z-index: 1000; }
                        .page-footer { position: fixed; bottom: 0; width: 100%; background: white; z-index: 1000; }
                        
                        .page { page-break-after: auto; position: relative; z-index: 1; }
                        @page { margin: 2mm; }
                        
                        @media print {
                            thead { display: table-header-group; } 
                            tfoot { display: table-footer-group; }
                            body { margin: 0; }
                        }
                    ` : ''}
                </style>
            </head>
            <body>
                ${hasHeader ? `
                <div class="page-header" style="text-align: center;">
                    ${header}
                </div>` : ''}

                ${hasFooter ? `
                <div class="page-footer" style="text-align: center;">
                    ${footer}
                </div>` : ''}

                ${(hasHeader || hasFooter) ? `
                <table style="width: 100%;">
                    <thead><tr><td><div class="page-header-space"></div></td></tr></thead>
                    <tbody>
                        <tr><td>
                            <div class="page">
                                ${content}
                            </div>
                        </td></tr>
                    </tbody>
                    <tfoot><tr><td><div class="page-footer-space"></div></td></tr></tfoot>
                </table>
                ` : content /* If no header/footer args, just return content as is (DonorflowReportScreen case) */}
                
            </body>
        </html>
    `)
}