import React from 'react';
import { Text, TouchableOpacity, StyleSheet } from 'react-native';
import { isBNU, isNU, isNUQ, normalize } from '../CommonStyle/ComponentFunctions';
import HOCIcons from './HOCIcons';
import { Global } from '../Common/Global';

export default function HShadowButton(props) {
    const {
        disabled,
        buttonCallback,
        buttonstyle,
        useicon,
        iconname,
        icongroup,
        iconcolor,
        iconsize,
        iconstyle,
        usetext,
        numberOfLines,
        disabletextadjust,
        textstyle,
        displaytext,
    } = props;

    return (
        <TouchableOpacity
            disabled={!!disabled}
            onPress={() => {
                if (isNU(buttonCallback)) buttonCallback(true);
            }}
            style={isNU(buttonstyle) ? buttonstyle : {}}
        >
            {useicon && (
                <HOCIcons.Icons
                    icongroup={isNU(icongroup) ? icongroup : 5}
                    name={isBNU(iconname) ? iconname : 'file-alt'}
                    color={isNU(iconcolor) ? iconcolor : Global.AppTheme.primary_color}
                    size={isNU(iconsize) ? iconsize : normalize(15)}
                    style={iconstyle ?? {}}
                />
            )}

            {usetext && (
                <Text
                    numberOfLines={isNU(numberOfLines) ? numberOfLines : 1}
                    adjustsFontSizeToFit={!disabletextadjust}
                    style={textstyle ?? styles.defaultText}
                >
                    {isNUQ(displaytext) ? displaytext : null}
                </Text>
            )}
        </TouchableOpacity>
    );
}

const styles = StyleSheet.create({
    defaultText: {
        color: Global.AppTheme.primary_color,
        fontSize: normalize(6),
        textAlign: 'center',
    },
});
