import { BackHandler, Dimensions, Modal, StatusBar, Text, TouchableOpacity } from "react-native";
import { View } from "react-native";
import CContainerView from "../CustomComponents/CContainerView";
import HeaderBlock from "./HeaderBlock";
import CDetailView from "../CustomComponents/CDetailView";
import CFooterView from "../CustomComponents/CFooterView";
import { CButtonShadow, isBNUL, isNU, isNUQ, isPermitted, normalize, notifyMessage } from "../CommonStyle/ComponentFunctions";
import { useNavigation } from "@react-navigation/native";
import { useEffect, useState } from "react";
import { EMRAPI } from "../Common/apiConstants";
import Pdf from "react-native-pdf";
import Loader from "../Custom/Loader";
import RNFS from 'react-native-fs';
import moment from 'moment';
import { Global } from "../Common/Global";
import CBackHandler from "../CustomComponents/CBackHandler";
import Overlay from 'react-native-modal-overlay';
import HOCIcons from "../HOC/HOCIcons";
import Icons from "../Common/Icons";
import HShadowButton from "../HOC/HShadowButton";
import WebView from "react-native-webview";
import HReportFormat from "../Html/HReportFormat";
import RNHTMLtoPDF from 'react-native-html-to-pdf';
import ReactNativeBlobUtil from 'react-native-blob-util';
import RNFetchBlob from 'react-native-blob-util';

export default function PdfPreviewOverlay(props) {

    const [isLoading, setIsLoading] = useState(false);

    function fnHeaderData(i) {
        let temp = i && i != null && i != undefined ?
            i.map(u => (u.componentname == 'header' ? u.value : '')).join('') : ' ';
        return temp;
    }

    function fnFooterData(i) {
        let temp = i && i != null && i != undefined ?
            i.map(u => (u.componentname == 'footer' ? u.value : '')).join('') : ' ';
        return temp;
    }

    function fnContentData(i) {
        let temp = i && i != null && i != undefined ?
            //i.map(u => u.componentname != 'header' &&  u.componentname != 'footer'   ? u.value : '').join('')
            i.map(u => isNU(u.value) ? u.value : '').join('')
            : ' ';
        return temp;
    }

    function HtmlPreview(data) {
        // const html = HReportFormat(fnContentData(data), fnHeaderData(data), fnFooterData(data), '70px', '80px');
        const html = fnContentData(data);
        // console.log('jooojojo', JSON.stringify(html));
        return html;
    }

    function getOverlayChildrenWrapperStyle() {

        return ({
            position: 'absolute',
            bottom: 0,
            top: Dimensions.get('screen').height * 0.065,
            borderTopLeftRadius: 10,
            borderTopRightRadius: 10,
            borderColor: Global.AppTheme.primary_color,
            borderWidth: 2,
            alignItems: 'center',
            alignSelf: 'center',
            justifyContent: 'flex-start',
            width: Dimensions.get('window').width,
            padding: 0
        })
    }

    function getFooterFunctions(item) {

        switch (item.functionid) {
            case "ST01":
                props.savecallback ? props.savecallback(item) : null
                break;
            case "ST02":
                props.mergecallback ? props.mergecallback(item) : null
                break;
            case "ST03":
                props.replacecallback ? props.replacecallback(item) : null
                break;
            case "ST04":
                props.closecallback ? props.closecallback(item) : null
                break;
            case "DW01":
                PreviewPDF()
                break;
            case "VER01":
                props.verifycallback ? props.verifycallback(item) : null
                break;
            case "GB01":
                props.closeOverlay();
                break;

            default:
                break;
        }
    }

    const PreviewPDF = async () => {
        // console.log('preview')

        if (isPermitted()) {
            // console.log('inside is permitted')
            setIsLoading(true);


            const results = await RNHTMLtoPDF.convert({
                // html: htmlString,
                html: HtmlPreview(props.data),
                // html: HReportFormat(HtmlData[1].value, HReportHeader({ "patientid": ValueCheck(Global.PatientDetails) && ValueCheck(Global.PatientDetails.profilecontent[0].patientno) ? Global.PatientDetails.profilecontent[0].patientno : '' }), HReportFooter(), '110px', '80px'),
                fileName: 'patient report',
                base64: true,
                height: 842, // a5 - 596(points) 21(cm)   // a4 - 842(points) 29.7(cm)
                width: 596   // a5 - 420(points) 14.8(cm) // a4 - 596(points) 21(cm)
            }).catch(errors => {
                setIsLoading(false);
            });
            console.log('2222')

            const fileBase64 = await ReactNativeBlobUtil.fs.readFile(results.filePath, 'base64');
            const filePath = RNFetchBlob.fs.dirs.DownloadDir + '/' + moment().format('DD-MM-YYYY hmmssSSS') + '.pdf';
            RNFetchBlob.fs.writeFile(filePath, fileBase64, 'base64').then(response => {
                notifyMessage(filePath, 1),
                    setIsLoading(false);
            })
                .catch(errors => {
                    notifyMessage("Download Failed", 2)
                    setIsLoading(false);
                });
            setIsLoading(false);
            // console.log('333333')
        }
    }

    return (
        // <Overlay
        //     visible={true}
        //     onClose={() => {
        //         props.closeOverlay();
        //     }}
        //     closeOnTouchOutside={false}
        //     containerStyle={{ backgroundColor: 'rgba(0, 0, 0, 0)' }}
        //     childrenWrapperStyle={getOverlayChildrenWrapperStyle()}
        // >
        <Modal
            animationType='none'
            transparent={true}
            visible={true}
            onRequestClose={() => {
                props.closeOverlay();
            }}
        >
            <View style={{ height: Dimensions.get('window').height - StatusBar.currentHeight, borderColor: 'red', justifyContent: 'flex-end' }}>
                <View style={{
                    height: '93%',
                    borderWidth: 0,
                    alignSelf: 'baseline',
                    width: '100%',
                }}>
                    {isLoading ?
                        <Loader displaytext={true} />
                        : null}
                    <View style={{
                        borderWidth: 0,
                        flexDirection: 'row',
                        backgroundColor: '#f0f0f0',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                        borderTopLeftRadius: 7,
                        borderTopRightRadius: 7,
                        paddingVertical: normalize(5)
                    }}>
                        <View style={{ borderWidth: 0, flex: 1, }}>
                            <View style={{ flexDirection: 'row', alignItems: 'center' }}>
                                <HOCIcons.Icons
                                    icongroup={props?.headingstyle?.headingicongroup ? props.headingstyle.headingicongroup : 3}
                                    name={props?.headingstyle?.headingicon ? props.headingstyle.headingicon : 'eye'}
                                    size={normalize(18)}
                                    color={Global.AppTheme.primary_color}
                                    style={{
                                        width: normalize(30),
                                        borderWidth: 0,
                                        textAlign: 'center'
                                    }}
                                />
                                <Text adjustsFontSizeToFit style={{
                                    paddingLeft: normalize(5),
                                    fontWeight: 'bold',
                                    color: Global.AppTheme.primary_color,
                                    fontSize: normalize(14)
                                }}>
                                    {props?.overlayheading ? props.overlayheading : ''}
                                </Text>
                            </View>
                        </View>

                        <TouchableOpacity
                            onPress={() => {
                                props.closeOverlay(); // Toggle the state
                            }}
                            style={{
                                justifyContent: 'flex-end',
                                alignItems: 'center',
                                borderWidth: 0.5,
                                borderColor: 'lightgrey',
                                borderRadius: 15,
                                flexDirection: 'row'
                            }}
                        >
                            <Text style={{ color: Global.AppTheme.primary_color, fontSize: normalize(11), fontWeight: 'bold' }}>{"CLOSE  "}</Text>
                            <HOCIcons.AntDesign name="closecircle" size={20} color={Global.AppTheme.primary_color} style={{ marginRight: normalize(5) }} />
                        </TouchableOpacity>
                    </View>
                    <View style={{ flex: 1, width: '100%' }}>
                        {isBNUL(props.data) ?
                            <WebView
                                source={{ html: HtmlPreview(props.data) }}
                                // style={{ height: '100%', width: '100%' }}
                                // style={{ height: Dimensions.get('screen').height * 0.42 }}
                                scalesPageToFit={true}
                            />
                            : null}
                    </View>
                    <CFooterView>
                        <View style={{ flexDirection: 'row' }}>
                            {[
                                {
                                    "displaytext": "Verify",
                                    "iconcolor": Global.AppTheme.primary_color,
                                    "fontcolor": Global.AppTheme.primary_color,
                                    "shadowcolor": '#fff',
                                    "size": 10,
                                    "icongroup": 4,
                                    "iconname": "check-square-o",
                                    "selected": false,
                                    "visibility": props.verifybutton ? true : false,
                                    "iconsize": 22,
                                    "functionid": "VER01",
                                    "componentname": "",
                                    "width": normalize(50)
                                },
                                {
                                    "displaytext": "Save",
                                    "iconcolor": Global.AppTheme.primary_color,
                                    "fontcolor": Global.AppTheme.primary_color,
                                    "shadowcolor": '#fff',
                                    "size": 10,
                                    "icongroup": 4,
                                    "iconname": "save",
                                    "selected": false,
                                    "visibility": props.savebutton ? true : false,
                                    "iconsize": 22,
                                    "functionid": "ST01",
                                    "componentname": "",
                                    "width": normalize(50)
                                },
                                {
                                    "displaytext": "Merge",
                                    "iconcolor": Global.AppTheme.primary_color,
                                    "fontcolor": Global.AppTheme.primary_color,
                                    "shadowcolor": '#fff',
                                    "size": 10,
                                    "icongroup": 3,
                                    "iconname": "merge",
                                    "selected": false,
                                    "visibility": props.mergebutton ? true : false,
                                    "iconsize": 22,
                                    "functionid": "ST02",
                                    "componentname": "",
                                    "width": normalize(50)
                                },
                                {
                                    "displaytext": "Replace",
                                    "iconcolor": Global.AppTheme.primary_color,
                                    "fontcolor": Global.AppTheme.primary_color,
                                    "shadowcolor": '#fff',
                                    "size": 10,
                                    "icongroup": 3,
                                    "iconname": "file-replace",
                                    "selected": false,
                                    "visibility": props.replacebutton ? true : false,
                                    "iconsize": 22,
                                    "functionid": "ST03",
                                    "componentname": "",
                                    "width": normalize(50)
                                },
                                {
                                    "displaytext": "No Change",
                                    "iconcolor": Global.AppTheme.primary_color,
                                    "fontcolor": Global.AppTheme.primary_color,
                                    "shadowcolor": '#fff',
                                    "size": 10,
                                    "icongroup": 5,
                                    "iconname": "exchange-alt",
                                    "selected": false,
                                    "visibility": props.closebutton ? true : false,
                                    "iconsize": 22,
                                    "functionid": "ST04",
                                    "componentname": "",
                                    "width": normalize(50)
                                },
                                {
                                    "displaytext": "Download",
                                    "iconcolor": Global.AppTheme.primary_color,
                                    "fontcolor": Global.AppTheme.primary_color,
                                    "shadowcolor": '#fff',
                                    "size": 10,
                                    "icongroup": 5,
                                    "iconname": "download",
                                    "selected": false,
                                    "visibility": isBNUL(props.data) ? true : false,
                                    "iconsize": 22,
                                    "functionid": "DW01",
                                    "componentname": "",
                                    "width": normalize(50)
                                },
                                {
                                    "displaytext": "Go Back",
                                    "iconcolor": Global.AppTheme.primary_color,
                                    "fontcolor": Global.AppTheme.primary_color,
                                    "shadowcolor": '#fff',
                                    "size": 10,
                                    "icongroup": 5,
                                    "iconname": "arrow-left",
                                    "selected": false,
                                    "visibility": true,
                                    "iconsize": 22,
                                    "functionid": "GB01",
                                    "componentname": "",
                                    "width": normalize(50)
                                }
                            ].map((item, i) => {
                                return (
                                    item.visibility ?
                                        <View key={i} style={{}}>
                                            <HShadowButton
                                                useicon={true}
                                                usetext={true}
                                                disabled={false}
                                                buttonstyle={{
                                                    ...CButtonShadow(),
                                                    alignItems: 'center',
                                                    justifyContent: 'center',
                                                    borderWidth: 1,
                                                    borderColor: 'lightblue',
                                                    borderRadius: 10,
                                                    height: normalize(50),
                                                    width: item.width ? item.width : normalize(50),
                                                    marginVertical: normalize(7),
                                                    marginLeft: normalize(7),
                                                    backgroundColor: 'white'
                                                }}
                                                iconcolor={Global.AppTheme.primary_color}
                                                icongroup={isNU(item.icongroup) ? item.icongroup : 5}
                                                iconname={isNU(item.iconname) ? item.iconname : 'file-alt'}
                                                iconsize={normalize(22)}
                                                displaytext={isNU(item.displaytext) ? item.displaytext : ''}
                                                buttonCallback={() => {
                                                    getFooterFunctions(item)
                                                }}
                                                textstyle={{
                                                    fontWeight: 'bold',
                                                    // fontFamily: Global.fontBold,
                                                    color: 'black',
                                                    fontSize: normalize(10),
                                                    textAlign: 'center',
                                                    alignSelf: 'center'
                                                }}
                                            />
                                        </View>
                                        : null
                                )
                            })}
                        </View>
                    </CFooterView>
                </View>
            </View>
        </Modal>
        //</Overlay> */ }
    )
}