import React, { useState, memo } from 'react';
import {
    Text,
    View,
    Image,
    TouchableOpacity,
    ActivityIndicator,
    StyleSheet,
    Dimensions,
    PermissionsAndroid,
    Platform
} from 'react-native';
import { colors } from '../CommonStyle/commonStyle';
import ComponentStyles, { normalize } from '../CommonStyle/componentStyle';
import NetworkServiceCall from '../Common/NetworkServiceCall';
import DocumentPicker from 'react-native-document-picker';
import FontAwesome from 'react-native-vector-icons/FontAwesome';
import { useNavigation } from '@react-navigation/native';
import { APIURL, EMRAPI, imageURL } from '../Common/apiConstants';
import { isNU, LoaderIndicator, notifyMessage } from '../CommonStyle/ComponentFunctions';
import ReactNativeBlobUtil from 'react-native-blob-util';
import PhotoEditor from 'react-native-photo-editor';
import { Global } from '../Common/Global';

function CSingleImage(props) {

    const navigation = useNavigation();
    const { width, height } = Dimensions.get('window');
    const [data, setData] = useState();
    const [isLoading, setIsLoading] = useState(false);
    const [isMsgShow, setIsMsgShow] = useState(false);
    const [Msg, setMsg] = useState(false);
    const [showImage, setShowImage] = useState(props.imageurl != undefined && props.imageurl != null && props.imageurl != "" ? props.imageurl
        : "https://icon-library.com/images/no-image-icon/no-image-icon-0.jpg")
    console.log('showImage', showImage)
    const [pathPE, setPathPE] = useState()

    const isPermitted = async () => {
        if (Platform.OS === 'android') {
            try {
                const granted = await PermissionsAndroid.request(
                    PermissionsAndroid.PERMISSIONS.WRITE_EXTERNAL_STORAGE,
                );
                return granted === PermissionsAndroid.RESULTS.GRANTED;
            } catch (err) {
                alert('Write permission error', err);
                return false;
            }
        } else {
            return true;
        }
    };

    const getResolvedPath = async (uri, filen) => {

        const fileBase64 = await ReactNativeBlobUtil.fs.readFile(uri, 'base64');
        const relativePath = ReactNativeBlobUtil.fs.dirs.CacheDir;
        const fileName = `${filen}`;
        const path = `${relativePath}/${fileName}`;

        // Create temporary file
        await ReactNativeBlobUtil.fs.writeFile(path, fileBase64, 'base64');
        return { relativePath, fileName, path };
    };

    const browseFromDevice = async () => {
        // if (await isPermitted()) {
        try {
            const fileDetails = await DocumentPicker.pick({
                type: [DocumentPicker.types.images],
            });
            console.log('browseFromDevice')
            const { relativePath, fileName, path } = await getResolvedPath(
                fileDetails[0].uri,
                fileDetails[0].name,
            );
            let fileid_autogenerate = 123
            let dataset = {
                fileid: fileid_autogenerate,
                uri: 'file://' + path,
                filename: fileDetails[0].name + Date(),
                uritype: false,
            };
            if (Platform.OS == 'ios') {
                props.route.params.onSelect({
                    uri: dataset.uri,
                    filename: 'image',
                    filetype: "image/jpeg",
                });
                props.navigation.goBack();
            }
            else {
                PhotoEditor.Edit({
                    path: path,
                    hiddenControls: ['sticker', 'save'],
                    onDone: () => {
                        setPathPE(path)
                        Media_Upload(dataset);
                    },
                });
            }
        } catch (error) {
            console.log("EROOROOOROROROOROROROROOROROROOROOR", error)
            notifyMessage(
                DocumentPicker.isCancel(error)
                    ? 'Canceled'
                    : 'Unknown Error: ' + JSON.stringify(error), 2
            );
        }
        // }
    };

    function getcontainerStyle() {
        return {
            ...layoutstyles.container_style,
            width: props.width != undefined ? props.width : '38%',
        };
    }

    // Add to folder
    const Media_Upload = async item => {

        setIsLoading(true);
        let uniquename = `.jpg`;
        var formData = new FormData();
        formData.append('file', {
            uri: item.uri,
            type: "image/jpeg",
            name: uniquename,
        });
        let buttonapi = props.doctorprofile ? EMRAPI.saveDoctorProfile : APIURL + 'file/fileupload/emr/image';
        console.log('buttonapi', buttonapi);
        NetworkServiceCall('multiform', buttonapi, formData)
            .then(function (response) {
                if (response.httpstatus == 200) {
                    if (response.data.filesize > 0) {
                        setData(response.data.fileuri);
                        if (props.doctorprofile) {
                            setShowImage(props.profilelink + response.data.fileuri);
                        }
                        else {
                            setShowImage(imageURL + response.data.fileuri);
                        }
                        props.callBack(response.data.fileuri)
                        setIsMsgShow(true, setMsg('Success...'));
                        setIsLoading(false);
                        setTimeout(() => {
                            setIsMsgShow(false);
                        }, 2000);
                    } else {
                        setIsLoading(false);
                        setIsMsgShow(true, setMsg('...'));
                        setTimeout(() => {
                            setIsMsgShow(false);
                        }, 2000);
                    }
                } else {
                    setIsLoading(false);
                    setIsMsgShow(true, setMsg('..'));
                    setTimeout(() => {
                        setIsMsgShow(false);
                    }, 2000);
                }
            });
    };

    function CaptureImageWithoutEdit() {
        // navigation.navigate('CCaptureImageWithoutEdit', {
        //     onSelect: Media_Upload
        // });

        navigation.navigate('CCaptureImageWithoutEdit', {
            'hidebuttons': false,
            'cameratype': 'back',
            onSelect: (s) => s && isNU(s) ? Media_Upload(s) : null
        })
    }

    function getPhotoEditor() {
        console.log("SHOWWWW IMAGEGGEGEGEGGEGEGEGEGG", JSON.stringify(showImage))

        let urlToFetch = showImage
        ReactNativeBlobUtil
            .config({
                fileCache: true,
                appendExt: 'jpg'
            })
            .fetch('GET', urlToFetch, {
                //some headers ..
            })
            .then((res) => {
                console.log('The file saved to ', res.path());
                let imgPath = res.path();
                setPathPE(imgPath)

                let dataset = {
                    fileid: Math.floor(Math.random() * 10),
                    uri: 'file://' + imgPath,
                    filename: `.jpg`,
                    uritype: false,
                };
                PhotoEditor.Edit({
                    path: imgPath,
                    hiddenControls: ['sticker', 'save'],
                    onDone: () => {
                        setPathPE(imgPath)
                        Media_Upload(dataset)
                    },
                });
            })


        // if (pathPE != undefined) {
        //     let dataset = {
        //         fileid: Math.floor(Math.random() * 10),
        //         uri: 'file://' + pathPE,
        //         filename: `.jpg`,
        //         uritype: false,
        //     };
        //     PhotoEditor.Edit({
        //         path: pathPE,
        //         hiddenControls: ['sticker', 'save'],
        //         onDone: () => {
        //             setPathPE(pathPE)
        //             Media_Upload(dataset)
        //         },
        //     });
        // }
    }

    function getTableStyle() {
        return {
            width: props.width != undefined ? props.width : '38%',
            flexDirection: 'row',
        };
    }

    return (
        <View style={props.table != undefined ? getTableStyle() : getcontainerStyle()}>
            <View style={props.table != undefined ? { flexDirection: 'row', width: normalize(65), alignItems: 'center' } : {}}>
                <TouchableOpacity
                    onPress={() => getPhotoEditor()}
                    disabled={(Platform.OS == 'ios' && isLoading) || props.disabled ? true : false}
                    style={props.table != undefined ? { borderRadius: 10 } : layoutstyles.image_container_style}>
                    {props.table != undefined ?
                        <Image style={{ width: normalize(35), height: normalize(35), borderRadius: 10 }}
                            source={{
                                uri: showImage,
                                headers: {
                                    Authorization: `Bearer ${Global.JWTToken}`
                                },
                            }}
                        />
                        :
                        <Image style={
                            props.customimagestyle ?
                                props.customimagestyle :
                                {
                                    width: '100%',
                                    height: normalize(110),
                                    borderRadius: 20,
                                    resizeMode: 'cover'
                                }}
                            source={{
                                uri: showImage,
                                headers: {
                                    Authorization: `Bearer ${Global.JWTToken}`
                                },
                            }}
                        />}
                    {isLoading ?
                        <View style={{ position: 'absolute', justifyContent: 'center', alignItems: 'center' }}>
                            <LoaderIndicator
                            />
                        </View>
                        : null}
                </TouchableOpacity>

                <View style={layoutstyles.options_row}>
                    <TouchableOpacity
                        disabled={props.disabled ? true : false}
                        onPress={() => browseFromDevice()}
                        style={{ backgroundColor: 'transparent', width: '50%', alignItems: 'center' }}
                    >
                        <FontAwesome name="folder-open" color={Global.AppTheme.primary_color} size={25} />
                    </TouchableOpacity>

                    {props.hidephoto != undefined && props.hidephoto ? null :
                        <TouchableOpacity
                            disabled={props.disabled ? true : false}
                            style={{ backgroundColor: 'transparent', width: '50%', alignItems: 'center', marginLeft: 5 }}
                            onPress={() => CaptureImageWithoutEdit()}>
                            <FontAwesome name="camera" color={Global.AppTheme.primary_color} size={25} />
                        </TouchableOpacity>}

                </View>
            </View>
        </View >
    );
}
const layoutstyles = StyleSheet.create({
    container_style: {
        ...ComponentStyles.View_col_center,
        padding: normalize(5),
        paddingBottom: 0,
        // height: normalize(165),
        alignItems: 'flex-start',
    },
    image_container_style: {
        flexDirection: 'row',
        justifyContent: 'center',
        alignItems: 'center',
        borderColor: colors.color_componentBordercolor,
        borderWidth: 1,
        borderRadius: 15,
        borderColor: 'lightgrey'
        // height:Dimensions.get('screen').height*0.1
    },
    image_style: {
        width: '100%',
        height: normalize(110),
        // resizeMode:'stretch',
        borderRadius: 20,
    },
    options_row: {
        flexDirection: 'row',
        justifyContent: 'space-around',
        padding: normalize(5),
        paddingBottom: 0,
    },
    option_text: {
        fontSize: normalize(12),
        // color: '#000059',
        color: 'white'
    }
})
export default memo(CSingleImage);

